INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42123237890', 'Boneca Fashion Doll Fada Dreameez Sortida e Unitária Multikids - BR2488', '*Produto Sortido e unitário, será enviado de acordo com a disponibilidade em estoque. Chegou a encantadora Fashion Doll Fada Dreameez, trazendo um toque de magia, brilho e imaginação para as brincadeiras das crianças! Com asas delicadas e um visual inspirado no mundo das fadas, essa boneca vem com um look encantador, cheio de cores vibrantes e detalhes que fazem brilhar os olhos. Seu cabelo estiloso e rostinho expressivo convidam a criar histórias mágicas e aventuras cheias de fantasia. Perfeita para presentear, colecionar ou viver momentos mágicos no mundo do faz de conta, a Fashion Doll Fada Dreameez estimula a criatividade e o desenvolvimento da imaginação. Deixe a magia fazer parte do dia a dia com a Fashion Doll Fada Dreameez e transforme cada brincadeira em um verdadeiro conto encantado! Ficha Técnica: - Material: Plástico - Idade recomendada: + 3 Anos Características: - Marca:Multikids - Modelo:BR2488 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Boneca Fashion Doll Fada Dreameez BR2488 (Sortida)', 86.06, 77.45, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-824gq-mfld72aqlmo8ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F42123237890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18998044241', '15 Cilindros Co2 12g Airsoft Leão Modelismo Sem Rosca', 'Produto de uso exclusivo em práticas esportivas (airsoft, carabina de pressão,brinquedos de bolinha) ESPECIFICAÇÕES TÉCNICAS DO CO2: Esse é um Cilindro de Co2 puro, sem óleo ou contaminantes, produzido pela Leão Modelismo, marca nacional reconhecida como símbolo de qualidade. Essa cápsula é descartável após o uso e possui 12 gramas de conteúdo interno. Não possui rosca. Pode ser utilizado em Armas de pressão, Airsoft, Paintball ou outros dispositivos que utilizem este modelo de Cápsula Co2. Compacto prático e com excelente custo benefício. - Marca: Leão Modelismo - Conteúdo: Gás Co2 - Peso: 12 gramas - Encaixe: 3/8 - Não possui rosca - Não reutilizável (descartável) - Diâmetro do cilindro: 1,8cm - Comprimento do cilindro: 8,2mm - Peso bruto: 43 gramas ITENS INCLUSOS: - 15 Cilindros Co2 Leão Modelismo Sem Rosca 12gr (cada)', 58.93, 58.93, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7reow-m8dqcf7r9bxe35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404617501%2F18998044241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
