INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993213614', 'Moldura 2 Din Vectra G2 c/ Ar Digital - Preta', 'Toda nossa linha de molduras automotivas são fabricadas pela Fiamon, que tem hoje o melhor acabamento entre as molduras comercializadas, e por isso, a escolhemos para fornecer as melhores molduras no mercado aos nossos clientes. Fiamon é conhecida pela garantia de qualidade e acabamento já demonstrado pelos anos de sucesso nas vendas. • Vectra G2 com ar digital: 1996 até 2005 Mantenha a originalidade e qualidade no acabamento de seu veículo, escolha Fiamon! Características Gerais do Produto: Garantia: • 3 meses', 277.9, 277.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyf-lywpgiwl79eq11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429425876%2F23993213614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18198051188', 'Kit Brinquedos Educativos Fusca + Bola | Meninos +12 meses | Acompanha 11 Formas Geométricas | Cert.INMETRO | QUEEN SHOP', 'Kit Fusca Educativo + Bola Educativa com Peças de Encaixe | QUEEN SHOP Diversão e aprendizado no mesmo kit! O Fusca Educativo e a Bola Educativa foram desenvolvidos para estimular a criatividade, a coordenação motora e o reconhecimento de cores e formas enquanto a criança brinca. O Fusca possui um design colorido e divertido, com aberturas para encaixar as peças geométricas. Além da brincadeira de empurrar e movimentar o carrinho, a criança pode identificar os formatos e encontrar o encaixe correspondente. A Bola Educativa conta com estrutura vazada e diferentes aberturas geométricas, oferecendo mais possibilidades de brincadeira e tornando o aprendizado ainda mais dinâmico. Principais benefícios Estimula a coordenação motora; Auxilia no reconhecimento de cores e formas; Desenvolve o raciocínio e a percepção espacial; Incentiva a criatividade e a autonomia; Proporciona diferentes formas de brincar; Kit colorido, educativo e divertido. Conteúdo do kit 1 Fusca Educativo; 1 Bola Educativa; 11 peças geométricas de encaixar. Medidas aproximadas Fusca: 26 x 16 x 15 cm; Bola: 10 cm de diâmetro. As cores das peças podem variar conforme a disponibilidade, sem comprometer a quantidade e a funcionalidade do produto. Uma excelente opção para presentear e proporcionar momentos de diversão, descoberta e aprendizado.', 49.9, 36.79, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820mf-mqz30vc8irk75a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F18198051188', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794791858', 'Coala Chá Branco Limpador Concentrado', 'O Limpador Perfumado Concentrado Coala Chá Branco oferece um aroma agradável e duradouro, proporcionando uma sensação prolongada de limpeza e bem-estar para todos os ambientes da sua casa. Modo de uso: dilua 8 gotas do limpador concentrado em 1 litro de água e, com um pano úmido, passe sobre a superfície desejada. Ideal para a limpeza diária de superfícies laváveis, como pisos e azulejos.', 15.99, 15.99, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260m-mj72li3jm4na12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554774%2F23794791858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
