INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694537313', 'Vitamina B12 - 30ml Morango - Ocean Drop', 'A vitamina B12 vegana da Ocean Drop está no formato de metilcobalamina, uma forma ativa do nutriente. Como Tomar Crianças de 4 a 8 anos sugere-se a ingestão de 1 gota via oral ou sublingual ao dia, maiores de 9 anos sugere-se a ingestão de 5 gotas via oral ou sublingual ao dia ou conforme recomendação profissional. Ingredientes Água purificada, metilcobala- mina (vitamina B12), agente de massa glicerina vegetal, acidulante ácido cítrico, regulador de acidez citrato de sódio, aroma idêntico ao natural de morango e conservadores: Sorbato de potássio e benzoato de sódio. NÃO CONTÉM GLÚTEN. ...', 44.05, 44.05, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-825ae-mftpyhgtxn2k2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F22694537313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
