INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994357092', 'Kit Body Cream e Body Splash Majesty Bloom Hidratação e Perfume', 'KIT BODY CREAM E BODY SPLASH MAJESTY BLOOM HIDRATAÇÃO E PERFUME O Kit Body Cream e Body Splash Majesty Bloom foi desenvolvido para proporcionar uma rotina completa de hidratação e perfumação no dia a dia. Composto por um hidratante corporal de alta performance e um body splash com fragrância refinada, o kit garante pele nutrida, macia e delicadamente perfumada por mais tempo. O Body Cream promove hidratação intensa e restauração da pele, enquanto o Body Splash complementa com uma perfumação floral elegante e marcante. A fragrância Majesty é ideal para quem busca sofisticação, feminilidade e presença. O KIT CONTÉM: -1 Body Cream Majesty Bloom 200g -1 Body Splash Majesty Bloom 200ml BENEFÍCIOS: -Hidratação intensa e duradoura -Pele macia e com toque sedoso -Perfumação floral elegante e prolongada -Combinação ideal de cuidado e fragrância -Texturas leves e de rápida absorção -Ideal para uso diário MODO DE USO: Body Cream: aplique sobre a pele limpa e seca, espalhando até completa absorção. Body Splash: borrife diretamente sobre a pele, especialmente em áreas de maior circulação como pescoço e pulsos. Utilize em conjunto para potencializar a hidratação e a fixação da fragrância. INFORMAÇÕES TÉCNICAS: Marca: Bloom Tipo: Kit hidratante corporal + body splash Uso: Corpo Indicação: Todos os tipos de pele COMPOSIÇÃO Body Cream com manteiga de karité, ureia, vitamina E e agentes emolientes Body Splash com álcool, água, fragrância e fixadores', 112.9, 89.0, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-820lq-mo5ew4v5rrb515', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609741857%2F22994357092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
