INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210405476', 'NEW SHOW Adesivo super forte Cola Para Cílios Postiços Fixação forte até À prova d’água e suor Secagem rápida', 'Descrição do produto 🌸 Cola Para Cílios Postiços New Show Bond + Seal + Remove Tenha cílios perfeitos por muito mais tempo! O kit New Show foi desenvolvido para proporcionar fixação forte, aplicação prática e acabamento natural. Ideal para uso diário, maquiagem profissional, festas, eventos e salão de beleza. ⸻ ✨ Principais Benefícios ✅ Fixação forte até Adesivo super forte Mantém os cílios firmes por mais tempo sem descolar facilmente. ✅ À prova d’água e suor Perfeito para o clima quente do Brasil. ✅ Efeito natural Não deixa resíduos brancos aparentes. ✅ Secagem rápida Facilita a aplicação mesmo para iniciantes. ✅ Removedor incluso Ajuda a retirar os cílios sem danificar os fios naturais. ⸻ 💖 Como Usar 1️⃣ Aplique o Bond nos cílios naturais 2️⃣ Coloque os cílios postiços 3️⃣ Use o Seal para aumentar a fixação 4️⃣ Para remover, aplique o Removedor delicadamente ⸻ 📦 Conteúdo da Embalagem * Capacidade: 5ml * Marca: New Show ⚠️ Cuidados * Uso externo * Evite contato direto com os olhos * Manter fora do alcance de crianças * Em caso de irritação, suspenda o uso', 70.0, 29.99, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/br-11134207-820lb-mo1ffclzl536e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1430626556%2F58210405476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
