INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206724401', 'Toalha De Praia 100% Algodão 86X150Cm Buzios Karsten', 'A Toalha Búzios une a alegria do verão ao conforto do algodão, sendo perfeita para acompanhar momentos de sol, praia e piscina. Seu corpo aveludado em jacquard oferece maciez e um visual diferenciado, ideal para quem busca estilo e bem-estar na mesma peça. Com ótima absorção e secagem rápida, ela é prática para usar entre um mergulho e outro. As cores frescas reforçam a leveza da estação, trazendo uma atmosfera descontraída e vibrante para seus dias de descanso. Produzida em 100% algodão, com fio cardado e gramatura de 430 g/m², a Toalha Búzios é pré-encolhida e possui acabamento antipilling, garantindo durabilidade e manutenção da beleza por muito mais tempo. Nas medidas de 86cm x 1,50m, oferece amplitude e conforto no uso. A tecnologia Softmax, exclusiva da Karsten, deixa o toque ainda mais macio e garante alta absorção desde o primeiro uso. Uma escolha prática, elegante e cheia de charme para aproveitar o verão com estilo e bem-estar.', 129.9, 129.9, NULL, 'Home & Living > Bathrooms > Towels & Bathrobes', 'https://cf.shopee.com.br/file/sg-11134201-8262r-mlp3hp73glj41e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F58206724401', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
