INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17117829298', 'Jogo de Talheres Jumbo p/ Churrasco 12 Peças Polywood Vermelho - Tramontina', 'Para todo bom churrasqueiro tornar o seu churrasco ainda melhor a dica é: Jogo de Talheres para Churrasco Jumbo Tramontina em Aço Inox com Cabo Castanho Polywood 12 Peças. O jogo da linha Churrasco é produzido com lâminas em aço inox, altamente durável, com cabos de madeira tratada Polywood, oferecendo resistência à impactos e altas temperaturas. A escolha ideal para quem busca por cortes de qualidade e peças com um design exclusivo, garantindo a beleza da mesa. Características: - Lâminas de aço inox - As lâminas das facas têm maior durabilidade do fio devido ao tratamento térmico - As lâminas dos garfos contam com maior espessura e uma estampagem do aço que garante maior resistência, evitando deformações - Os cabos de madeira tratada Polywood são resistentes à impactos e alta temperaturas garantindo maior resistência e durabilidade - Podem ir à máquina de lavar louças facilitando seu dia a dia', 284.19, 284.19, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/82affb30ab8311190ce3c8a0a3d1c1f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F17117829298', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
