INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597687694', 'Armário Multiuso Miriam 2 Portas 1,85m', 'Procurando por uma solução prática e elegante para organizar seus pertences? Nossa multiuso Miriam de 2 portas é a escolha ideal para maximizar o espaço de armazenamento em qualquer ambiente da sua casa.Fabricado em MDP e com materiais de alta qualidade, este armário é resistente e durável, garantindo anos de uso confiável. Pode ser usado para: Quarto: Armazene roupas, sapatos, acessórios e itens pessoais. Cozinha: Organize mantimentos, utensílios de cozinha e pequenos eletrodomésticos. Sala de Estar: Exponha livros, CDs, DVDs e decorações. Escritório: Guarde documentos, materiais de escritório e equipamentos eletrônicos. Somente com a Miriam você tem: 2 portas com dobradiças metálicas; 4 prateleiras internas; Puxadores em PVC; Suporta até 5kg nas prateleiras; Fabricado em MDP; Acabamento Touch Alto-Relevo ou Alto Brilho UV; Acompanha manual de montagem. Dimensões: Altura 185cm x Largura 56cm x Profundidade 35cm x Peso 27 kg. Medida entre as prateleiras: 33cm', 309.0, 309.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7ta2o2fzjnma6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842544500%2F21597687694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
