INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8470359346', 'Livro - A perseguição à noz maluca - Capa comum', 'POP! Uma brilhante noz marrom, de repente, apareceu no chão. Ela bamboleou e sacudiu, tremeu e se mexeu, depois ficou ali quietinha, parecendo estar deliciosa. A noz parece tão deliciosa que todos querem comê-la. O texuco decide organizar uma corrida em que o vencedor ficará com a noz. Mas a corrida não é tão simples assim, e acaba se tornando uma perseguição à noz! Editora: Ciranda Cultural Edição: 1, 2010 Autor: Kathryn White Idioma: Português Páginas: 32 Dimensões: L 26.50 x A 23.00 x E 0.50 ISBN: 9788538011200', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/7f2e1a463571e732785be855d0d57608', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8470359346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592994960', 'Creme Dental Colgate Total 12 Gengiva Reforçada 140g', 'A pasta de dente Colgate Total 12 Gengiva Reforçada, com fórmula avançada e antibacteriana, garante até 12 horas de defesa ativa que reforça sua gengiva contras as bactérias com o uso contínuo. Ajuda a prevenir o sangramento gengival* (*O uso diário do regime Colgate Total 12 (creme dental e enxaguante bucal) remove a placa para ajudar a prevenir o sangramento gengival causado pelo acúmulo de bactérias. Produto cosmético sem ação terapêutica.) Benefícios: Sua fórmula com o poder do Zinco apoia as defesas naturais da sua boca***, previne a formação de placa bacteriana e ajuda a prevenir problemas na gengiva**, criando uma barreira protetora que fortalece sua gengiva contra bactérias. Mantenha sua gengiva saudável com o creme dental Colgate Gengiva Reforçada. Tecnologia superior¹ para uma saúde bucal completa. Com o poder do Zinco, protege sua boca de bactérias para uma boa saúde dental. A tecnologia superior fortalece sua higiene bucal mesmo após a escovação.', 27.77, 27.77, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rblf-m5lwpdpzyzyv64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F22592994960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694317095', 'Mala Bordo Vinho - P', 'A Mala de Viagem Pequena Up4you ABS com Rodas Removíveis 360 e Cadeado é perfeita para quem busca praticidade, leveza e estilo em viagens de média duração, trazendo um visual moderno e sofisticado para acompanhar todos os momentos. Produzida em ABS resistente, oferece maior durabilidade contra impactos e riscos do uso diário, além de um acabamento texturizado elegante com detalhes em relevo vertical que deixam o design contemporâneo e diferenciado. O modelo possui 4 rodas duplas com giro 360°, garantindo movimentação leve, silenciosa e estável em diferentes tipos de piso. Conta também com carrinho embutido em alumínio com regulagem de altura, proporcionando mais conforto no transporte. A mala possui cadeado com segredo integrado, trazendo mais segurança para os pertences durante viagens nacionais e internacionais. Conta ainda com alça superior e lateral, facilitando o manuseio e transporte em aeroportos, hotéis e veículos. Seu interior é totalmente forrado e desenvolvido para proporcionar praticidade e melhor organização dos itens pessoais durante o uso. O modelo também possui apoio lateral para pendurar acessórios, funcionalidade prática. Mala de Viagem Pequena Up4you Modelo: MF10517UP-P Dimensão: Altura: 55 x Largura: 35 x Comprimento: 23 cm Peso: 2.7 Capacidade: Pequena Classificação: Viagem Média Material: ABS Rodas Removíveis Rodas Duplas com Giro 360° Carrinho Embutido em Alumínio Cadeado com Segredo Integrado Alça Superior e Lateral Forro Interno Apoio para Pendurar Acessórios Design Texturizado em Relevo Logo em Alto Relevo Dicas de uso: ideal para viagens de média duração, férias, viagens a trabalho e passeios com maior praticidade e organização. Dicas de limpeza: limpar com pano úmido e sabão neutro. Evitar produtos abrasivos para preservar o acabamento e a durabilidade da mala.', 271.9, 271.9, NULL, 'Travel & Luggage > Travel Bags > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258l-mqsao6v2hm2pb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251967897%2F22694317095', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
