INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17278125798', 'Kit Revisão 4 Litros de Óleo 5W20 + Filtros de Óleo e Combustível Ford Novo Ka 1.0 12V e 1.5 16V e Nova Ecosport 1.5 12V Dragon e Sigma', 'KIT TROCA DE ÓLEO 04 Litros de Óleo Texaco 5W20 100% Sintético 01 Filtro de Óleo Wega WO153 01 Filtro de Combustível Wega FCI1660 Ford Ka 1.0 12v TiVCT 2014 em Diante Ford Ka 1.5 16v Sigma 2014 em Diante Ford Ka 1.5 16v Dragon 2017 em Diante Ecosport 1.6 16v Sigma 2012 em Diante Ecosport 1.5 12v Dragon 2017 em Diante Óleo lubrificante de última geração 100% sintético para motores à gasolina, flex etanol e GNV, principalmente os de três cilindros da Ford. Pode também ser usado em outros motores inclusive os motores a diesel de veículos leves, pick-ups e SUVs. Desenvolvido para proporcionar excelente proteção contra formação de depósitos, cria um escudo que protege o motor contra o ataque abrasivo dos contaminantes resultantes da queima do combustível, oferece os seguinte benefícios: • Economia • Desempenho • Durabilidade • Proteção ao meio ambiente', 425.58, 425.58, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rce8-lrkf7r1g2m9s65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F641270782%2F17278125798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899567250', 'Organizador Viagem Mini Porta Joias Para Acessórios Pulseira Anel Colar Com Divisórias Zíper', 'Porta Joias Pvc Platina O Porta Joias é ideal para manter suas peças organizadas. Com um design sofisticado, ele oferece praticidade e proteção, além de ser um excelente item de decoração para seu quarto ou closet. Possui divisórias para organizar anéis, brincos, colares, pulseiras e outros acessórios. Características: > Material não poroso, que facilita a limpeza; > É resistente, mantendo suas peças seguras contra danos, riscos ou arranhados; > Seu design minimalista combina facilmente com qualquer estilo de decoração, sendo uma excelente opção para presentes ou uso pessoal. Especificações Técnicas: > Material: pvc; > Dimensões do produto (C x L x A): - Marca: Platina - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 29.85, 21.32, NULL, 'Home & Living > Home Organizers > Jewelry Organizers', 'https://cf.shopee.com.br/file/sg-11134201-7rffe-m3dj7op5q4kia5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F19899567250', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297093965', 'Sou péssimo em português - HarperCollins', 'Imagine-se fazendo uma prova e tendo de escolher a opção certa: A longo prazo ou em longo prazo? Assistir o ou assistir ao? Bastante ou bastantes? Ficou em dúvida? Então este livro é para você! Em Sou péssimo em português, a professora Cíntia Chagas usa histórias divertidas de sua própria vida para ensinar regras da língua portuguesa. São contos e microcontos com lições de gramática misturadas a relacionamentos, a viagens e a recordações, ensinadas de um jeito que você nunca vai esquecer. Aprenda o uso correto das palavras de forma dinâmica e divertida. Com a ajuda deste livro, as regras do português se tornarão mais memoráveis, e melhorar suas habilidades de comunicação e escrita será muito mais fácil.&#160', 48.07, 48.07, NULL, 'Books & Magazines > Books > Education & School', 'https://cf.shopee.com.br/file/sg-11134201-7r9au-ln7qjz78svp46c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22297093965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
