INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593839066', 'Kit 2 K-Othrine SC 25 Bayer - 30 mL', '- Indicado para controle de insetos; - Atua contra moscas, baratas e formigas; - Controla infestações em ambientes externos e internos; - Conta com fórmula concentrada que rende mais, - Disponível em embalagens com 30 ml e 250 ml. Detalhes O Inseticida K-Othrine SC 25 Bayer - 30 mL veio trazer mais segurança para dentro dos nossos lares é fundamental para ficarmos mais felizes e termos mais qualidade de vida. Então, para acabar com os insetos e os parasitas que possam surgir no dia a dia, conte com o K-Othrine SC 25. Dicas Especiais Com a qualidade Bayer Pet, o inseticida K-Othrine é perfeito para ajudar na eliminação de formigas, baratas e moscas. Confira abaixo alguns benefícios do produto: - É próprio para ser usado em pisos, rodapés, ralos, entre outros; - Tem fácil manuseio; - Apresenta efeito imediato e prolongado. Com o K-Othrine, sua casa ficará livre de insetos e parasitas de forma simples e prática. Composição p.a. Deltametrina 25g Veículo q.s.p. 1.000ml', 51.0, 25.99, NULL, 'Home & Living > Gardening > Others', 'https://cf.shopee.com.br/file/br-11134207-820lj-mnwyw566crgidf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F23593839066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
