INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893142452', 'Calça Jeans Wide Leg Cargo Feminina Cintura Alta Premium', 'Calça Feminina Wide Leg Cargo Pantalona Cintura Alta Você quer aquela calça que veste bem, valoriza a silhueta e ainda te deixa confortável o dia inteiro — sem aquele aperto que incomoda nem o tecido que esquenta. A Wide Leg entrega exatamente isso: o caimento moderno que está em alta. A modelagem wide leg de cintura alta alonga as pernas e marca a cintura, criando aquele visual sofisticado que combina tanto com o casual do dia a dia quanto com produções mais elegantes. É a peça curinga que resolve o look em segundos. Por que ela vai virar sua favorita: ✔️ Cintura alta — marca a cintura e alonga a silhueta ✔️ Modelagem Wide Leg — pernas amplas para o caimento moderno do momento ✔️ Bolsos traseiros funcionais — praticidade de verdade, não só enfeite ✔️ Versátil — combina com tênis, salto ou bota Detalhes do produto: Modelagem: Wide Leg Cintura: Alta Fechamento: Botão e zíper frontais Bolsos traseiros funcionais Cores disponíveis: consulte as variações ❓ DÚVIDAS FREQUENTES Como escolho meu tamanho certo? Meça uma calça que já te serve bem (cintura e quadril) e compare com a nossa tabela de medidas. Na dúvida entre dois tamanhos, considere que o algodão puro praticamente não cede. O tecido é fino ou transparente? É um jeans de algodão encorpado, resistente e nada transparente. Tem a estrutura típica do jeans, com o frescor que só o algodão puro oferece. A cor da foto é a cor real? Buscamos retratar as cores com máxima fidelidade. Pequenas variações podem ocorrer por causa da iluminação e das configurações de cada tela. Os bolsos traseiros são reais ou só desenho? São bolsos funcionais de verdade, dá para usar normalmente. Serve para quem é mais alta/baixa? A modelagem wide leg de cintura alta favorece diferentes alturas. Confira o comprimento na tabela de medidas para ver o que combina melhor com você. Pode lavar na máquina? Sim. Recomendamos lavar do avesso, com água fria e sabão neutro, para preservar a cor e o tecido por mais tempo. Qual o prazo de entrega? O prazo aparece automaticamente na página ao informar seu CEP, calculado conforme sua região. 💡 Dica: meça uma calça que já te serve bem e compare com a tabela para escolher seu tamanho ideal. Garanta a sua e monte looks cheios de personalidade. Adicione ao carrinho e aproveite! 🛒', 78.9, 73.9, NULL, 'Women Clothes > Jeans', 'https://cf.shopee.com.br/file/br-11134207-820l9-mnok9a87vric55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F439021441%2F23893142452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492997535', 'Óleo Mobil Super Moto 4T 20W50, 1L', 'Primeiro óleo do Brasil formulado especificamente para motos. Combina óleos minerais altamente refinados e aditivos para proporcionar ótima limpeza do motor, proteção contra desgaste e corrosão.', 49.0, 49.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd5g-luz8ajtzdo12d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F22492997535', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18046125986', 'Bíblia de Estudo para Mulheres | BKJ 1611 | Letra normal | Capa Luxo Rose e Preto', 'Bíblia de Estudo para Mulheres A Bíblia De Estudo Para Mulheres – Mulher Guiada Pelo Espírito – Bkj1611 É Um Devocional Escrito Por Várias Mulheres Inspiradas Que Se Propuseram A Aumentar O Desejo De Conhecer A Deus Mais Intimamente. O Cerne Dessa Obra Se Desenrola Por Suas Páginas De Encorajamento E Impacto Em Cumprir Os Planos De Deus. O Estudo Se Baseia Em Um Plano De Ação Contendo Regras As Quais Possuem A Fonte Em Uma Passagem Bíblica Específica – Preparação Para O Estudo. Conta Com Elementos Adicionais Os Quais Envolvem Instruções Específicas Na Comunhão Da Mulher Em Seus Relacionamentos Pessoais E Íntimos. Contido Nela Estão Artigos De Ensinamento Testemunhos Sobre O Poder De Deus Perfis De Mulheres Sobre O Passado E O Presente Na Caminhada De Fazer A Diferença No Reino. A Bíblia De Estudo Para Mulheres – Mulher Guiada Pelo Espírito Possui Textos Na Versão Da Bíblia King James 1611 Lançada Pela Bvbooks Que Contém A Versão Original Da Bíblia King James 1611. O Apêndice Final E A Proposta Do Estudo Em Sala Ou Em Grupo Reforçam Os Conhecimentos Dispostos E Os Princípios Que Fundamentam O Crescimento Espiritual Na Caminhada Com Deus', 199.05, 199.05, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/0ecad55095ede1db65514f1341719ad3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F18046125986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
