INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44954940307', 'Mini Borracha com Aroma Fini - Blister com 3 unidades Leo&Leo Leonora - 10347', 'A Mini Borracha Com Aroma Fini é muito mais do que apenas apagar! Cada blister vem com 3 mini borrachas com aromas diferentes, oferecendo uma experiência sensorial divertida e agradável enquanto remove traços de lápis com eficiência. Formato de Personagens Fini: Design exclusivo e divertido que encanta crianças e fãs da marca Aromas Diferenciados: Cada mini borracha possui fragrância própria para uma experiência olfativa agradável Atóxica e Segura: Produto totalmente seguro para crianças Alta Qualidade de Apagamento: Remove traços de lápis sem danificar o papel Macia e Confortável: Desliza suavemente sobre a superfície, tornando o uso agradável Ideal para Escola e Escritório: Perfeita para crianças e adultos que desejam unir funcionalidade e diversão FICHA TÉCNICA: Mini borrachas com formatos dos personagens Fini Estampa exclusiva Aroma no corpo do produto Atóxica Características: - Marca:Leonora - Modelo:10347 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - Blister com 3 unidades de mini borracha Fini', 14.0, 12.9, NULL, 'Stationery > Writing & Correction > Eraser & Correction Supplies', 'https://cf.shopee.com.br/file/sg-11134201-8261a-mjodmvoidwjr7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F44954940307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
