INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897996139', 'Lona De Polietileno Laranja 4 M X 4 M Vonder', 'Lona de polietileno laranja 4 m x 4 m, VONDER Possui cantos reforçados e fio sintético ao redor da bainha para maior resistência. Fabricada em polietileno de alta e baixa densidade, com aditivo que protege contra os raios ultravioleta. Impermeável. Possui amostra do produto fora da embalagem. Indicada para indústria, agricultura, construção civil, náutica, camping, pesca, recreação, utilidades domésticas, entre outros. Não utilizar a lona diretamente sobre superfícies aquecidas ou expostas ao sol (exemplos: veículos, peças metálicas, máquinas e equipamentos), pois a ação do calor poderá provocar manchas e danos às superfícies. Não utilizar para cobertura de cargas transportadas em caminhões, caminhonetes e automóveis. Não utilizar em contato com produtos químicos e resinas e para cobertura de peças perfurantes/cortantes. O esforço excessivo e a ação de ventos fortes podem provocar o rompimento dos ilhoses, bem como da lona. Realize a amarração da lona com cordas elásticas, dando uma maior flexibilidade ao produto. Conservação: armazenar longe de fontes de calor. Caso necessário, lavar com água e sabão neutro. Não recomendado para utilização como cobertura definitiva em telhados. Especificações Técnicas: Medida da lona: 4 m x 4 m Cor da lona: Laranja Espessura aproximada da lona de polietileno: 150 micra Distância entre ilhoses da lona: A cada 1 metro Massa aproximada (peso) (kg): 1,55 kg Conteúdo Da Embalagem: 1 Lona de polietileno.', 110.57, 85.94, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2qxel9awj5x2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22897996139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098314598', 'Cooler para Notebook Lenovo Ideapad 320-15 SERIES', 'Cooler para Notebook Lenovo Ideapad 320-15 SERIES | Interno ste é um Cooler bringIT compatível com o notebook Lenovo Ideapad 320-15 SERIES. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Informações Técnicas Quantidade de vias: 4 vias Corrente (Amperagem): 0.5A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL192-LN-0001', 52.89, 52.89, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-8258v-mq6emybxx43k66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23098314598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
