INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15406670849', 'Kit com 3 Desinfetante Pinho Sol Original 1L Cada', 'PINHO SOL® – ORIGINAL Elimina 99,9% das bactérias, germes e fungos Pinho Sol Original é um desinfetante que limpa e elimina 99,9% das bactérias/ germes e fungos*. Além disso, possui um delicioso perfume de Pinho, deixando a sua casa sempre limpa protegida e com um agradável perfume que dura por muito mais tempo. Use em todos os cômodos da casa e em diversas superfícies como: vaso sanitário, ralo, pia, tanque, azulejos e pisos. Quer saber como usar? É fácil: – Para desinfecção, utilize o produto puro e deixe-o agir em contato com a área por 30 segundos. – Para limpeza geral de superfície, dilua 2 colheres de copa (30ml) por litro de água. Seguindo essa instrução, o produto rende até 16 litros. – Para lavar roupa utilize um copo americano (200ml) de Pinho Sol com sabão ou detergente em um tanque ou máquina de lavar cheios de água. Para manchas, basta umedecer a parte suja com Pinho Sol e colocar a peça na máquina de lavar ou tanque. 1.75 L – Rende até 87 litros 1L – Rende até 50 litros. 500ml – Rende até 25 litros. Disponível nos tamanhos: 1.75L, 1L e 500ml', 63.89, 63.89, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/a13b9176c08269700c07cc22d9985ab4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F15406670849', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250097488', 'Ventilador de Teto Britânia 3 em 1 131W Cancun BVT02B 110V', 'Ventilador de Teto Britânia 3 em 1 131W Cancun BVT02B 110VO Ventilador de Teto Britânia 3 em 1 131W Cancun BVT02B é 3 em 1: funciona como ventilador, exaustor e luminária. Tudo que você precisa para ter um ambiente agradável em um único produto! Com 3 velocidades, que variam entre baixa, média e alta no modo ventilação e exaustor. Ventilador de Teto silencioso com luminária para duas lâmpadas. Oferece função reverso, que seleciona entre os modos exaustor ou ventilador. Maior eficiência, pois é de baixo consumo de energia e alta performance de vento. E para sua comodidade, acompanha controle remoto, mais prático e rápido para acionar o ventilador! - 3 Velocidades: Baixa, média e alta no modo ventilação e exaustor - Com controle remoto - Função reverso (seleciona entre os modos ventilador e exaustor) - Luminária para duas lâmpadas - 3 pás de plástico - Desmontável: facilita a limpeza - Silencioso - Potência 131W. Especificações Técnicas: Marca: Britânia Modelo: BVT02B Cor das Pás: Branco Estado: Novo Quantidade de pás: 3 Potência (W): 131 W Tipo: De teto Diâmetro (cm): 50 Função repelente: Não Material das Pás: Plástico Altura do produto: 547,5 cm Largura do produto: 1068 cm Comprimento do produto: 1068 cm Peso do produto: 4,803 kg Altura com embalagem: 17,3 cm Largura com embalagem: 51,4 cm Comprimento com embalagem: 31,7 cm Peso com embalagem: 5,611 kg Garantia (Dias): 360 Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas;', 615.9, 615.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-824hv-mf2p968xg5cd8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshope