INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793630243', 'Blusa Infantil Menina Básica Elian Verde', 'A Blusa Infantil Menina Básica Elian é confeccionada em meia malha. A escolha certa para compor looks casuais e confortáveis para as crianças. Com modelagem solta e tecido macio, oferece liberdade de movimento e bem-estar ao longo do dia. Sua cor vibrante traz alegria ao visual, sendo fácil de combinar com shorts, saias ou calças. Ideal para passeios, brincadeiras e até mesmo para a escola, garantindo estilo e conforto em todas as ocasiões.', 34.9, 34.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-825a4-mr1sry4xds0190', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23793630243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
