INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13624356956', 'Paralama Dianteiro Moto Pro Tork CRF 230 2008 á 2018', 'Paralama Dianteiro CRF 230, possui excelente acabamento, pode ser utilizado desde a CRF 230 2008 até 2018, o encaixe é perfeito, é só colocar no mesmo lugar do original. Pode adquirir e substituir a peça que está danificada ou podendo transformar sua moto alterando as cores que o fabricante disponibiliza. Fabricado com material leve e resistente que trazem flexibilidade de estilo e cor a sua moto. Especificações: - Encaixe perfeito; - Fabricação de alta qualidade; - Plástico rígido injetado com material DGP (Double Gloss Polypropylene - brilho em dobro); - Visual mais moderno e esportivo; - Maior aerodinâmica; - Não acompanha adesivos; - Marca: Pro Tork. Aplicação: - CRF 230 2008; - CRF 230 2009; - CRF 230 2010; - CRF 230 2011; - CRF 230 2012; - CRF 230 2013; - CRF 230 2014; - CRF 230 2015; - CRF 230 2016; - CRF 230 2017; - CRF 230 2018. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada; - A Sportbay não se responsabiliza pela má instalação do produto. OBS: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento de imagens e a calibração de cores da tela de seu monitor ou aparelho. Sportbay - Seu Esporte, Nossa Paixão.', 115.69, 84.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc219rbgp8zpf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F13624356956', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20162887486', 'Viseira Capacete Fechado Cristal Mixs Mx2 Gladiator Feminino Masculino Acessório Peça de Reposição', 'A Viseira Capacete Pro Tork Mixs MX2 e Gladiator Cristal é um acessório que foi fabricado para atender as exigências dos motociclistas em busca de resistência e qualidade. Apresenta alta definição Optics para eliminar a distorção, estabelece um novo padrão de durabilidade em uma viseira, protegendo os seus olhos. Especificações: - Produto original; - Modelo: Mixs MX2 e Gladiator; - Viseira Cristal; - Fabricada em policarbonato; - Acessório de reposição de fácil instalação; - Espessura de 2,0mm; - Dupla curvatura; - Marca: Mixs. Aplicações: - Mixs MX2; - Gladiator.', 84.11, 39.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/sg-11134201-22110-xe12zmcd0yjv6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F20162887486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
