INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193963164', 'Kit Pneu Michelin 80/100-18 + 100/90-18 Reinf City Extra TL', '80/100-18 Sobre o Par: Pneu que proporciona durabilidade e segurança, seja para quem está nas ruas ou nas estradas. Sua construção é reforçada, o que aumenta o tempo de vida e a resistência contra impactos das irregularidades do solo. O desenho da banda de rodagem foi pensado e produzido com tecnologia para escoar a água com mais precisão, para evitar derrapagens e situações de aquaplanagem em piso molhado. Informações Adicionais: - Marca: Michelin - Modelo: City Extra - Medida: 80/100-18 - Largura: 80mm - Perfil: 100% - Aro: 18 - Índice de peso: 47- 175 kg - Índice de velocidade: S - Tipo de montagem: Sem câmara - Posição no Veículo: Dianteiro 100/90-18 Informações Adicionais: - Marca: MICHELIN - Modelo: CITY EXTRA - Medida: 100/90-18 - Largura: 100MM - Perfil: 90% - Aro: 18 - Índice de peso: 62 - 265 KG - Índice de velocidade: S- 180 KM/H - Tipo de construção: DIAGONAL - Tipo de montagem: SEM CÂMARA - Posição no Veículo: DIANTEIRO/TRASEIRO Aplicação: - BMW: R 1200 C, R 1200 CL, R 850 C - ROYAL ENFIED: CONTINENTAL GT, CONTINENTAL GT 535, CONTINENTAL GT 650, INTERCEPTOR - YAMAHA: TDR 125R - KASINSKI: EKOPLUS 125, GF 125, GF 125 EKONÔMICA, MAGIK 125 - HONDA: CBX 200 STRADA, CBX 750 F, CBX 750 F INDY', 756.0, 756.0, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-82596-mqwd7ridnpxgf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F22193963164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
