INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7970970331', 'Chup De Leite Brigadeirão 30g C/50UN 1,5kg Biba', 'Delicie-se com o Chup de Leite Brigadeirão da Biba! Com o sabor marcante de brigadeiro e textura cremosa, esses docinhos de 30g são embalados individualmente, garantindo praticidade e frescor. A caixa contém 50 unidades, perfeita para compartilhar em festas, eventos ou para ter sempre à mão uma sobremesa deliciosa e prática. Quantidade: Caixa com 50 unidades de 30g cada (total 1,5kg). Embalagem: Doces embalados individualmente. Sabor: Brigadeirão cremoso, com um sabor intenso de chocolate e leite. Aproveite o irresistível Chup de Leite Brigadeirão da Biba e adoce seus momentos especiais! Ingredientes: Açúcar, leite in natura e/ou leite em pó, glucose, chocolate em pó, amido de milho, regulador de acidez bicarbonato de sódio e conservador sorbato de potássio. NÃO CONTÉM GLÚTEN. ALÉRGICOS: CONTÉM LEITE. CONTÉM LACTOSE Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 36.99, 36.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1zubbe733of34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F7970970331', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22630824824', 'Marshmallow Twist Recheado Rosa/Branco 220g Docile', 'O marshmallow é um produto aerado, produzido basicamente por uma mistura de gelatina, açúcar e glucose. É um dos candies mais populares e tradicionais dos Estados Unidos, sendo consumido por crianças e adultos! Ele pode ser consumido tanto puro, como tostado ou assado, acompanhando bebidas quentes e fondues. E assim vem conquistando mais fãs a cada dia! Ingredientes: Xarope de glicose, Açúcar, Água, Dextrose, Gelificante gelatina, Aromatizante, Regulador de acidez, amido de milho, corantes, e Baunilha. NÃO CONTÉM GLÚTEN. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 16.99, 16.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4er5opap8ol0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F22630824824', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792507976', 'Kit Sensodyne Branqueador Extra Fresh 50g Leve 3 Pague 2', 'O Kit Sensodyne Branqueador Extra Fresh foi especialmente desenvolvido para as pessoas que sofrem com a sensibilidade dentária, com o intuito de promover alívio e gerar conforto. Sua fórmula possui ação branqueadora que proporciona dentes brancos a cada escovação, removendo as manchas superficiais contidas nos dentes e garantindo uma boca saudável. Com uma escovação adequada e com o uso contínuo de Sensodyne Branqueador Extra Fresh seus dentes ficarão resistentes e protegidos de cáries, gengivite e da placa bacteriana, proporcionando assim um hálito puro e refrescante.', 45.89, 45.89, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-824g1-mpi23u4bb4su29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23792507976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198169688', 'Kit 2 Tintura de Cabelo Biocolor Vermelho Intenso de Arrasar 6.66', 'A nova Tintura de Cabelo Biocolor Vermelho Intenso de Arrasar 6.66 oferece uma cobertura perfeita dos fios brancos, cor intensa e durabilidade. A coloração é de fácil aplicação e age em apenas 20 minutos. Além disso, o kit promove um banho de hidratação no cabelo com o novo condicionador Hidratação Power que protege e entrega maciez aos fios. Sua composição conta com amônia e um novo aroma floral. Mude seu visual com Biocolor! *É importante que o teste de mecha seja feito antes da aplicação e não é recomendado o uso do produto caso o cabelo tenha sido colorido anteriormente com henê, coloração vegetal ou à base de sais metálicos.', 23.98, 23.98, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-825b3-mqme8f2t7tvv8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22198169688', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211754730', 'Kit Creme Dental Colgate Total 12 Whitening 180g - 3 Unidades', 'Kit Creme Dental Colgate Total 12 Whitening 180g - 3 Unidades O Creme dental Colgate Total 12 Whitening ajuda você a manter os dentes muito mais limpos e saudáveis de maneira prática e eficaz. Sua nova fórmula com arginina combate bactérias nos dentes, língua, bochechas e gengiva e oferece mais benefícios do que nunca, incluindo alívio de sensibilidade, melhor resistência ao esmalte e neutralização de odores. Benefícios: - Nova fórmula inovadora para um sorriso mais branco; - Deixa a boca limpa e fresca; - Combate bactérias nos dentes, língua, bochechas e gengivas; - Ajuda a prevenir o acúmulo de placa, cáries, gengivite e combate o tártaro; - Até 12 horas de proteção. Sobre a marca: Colgate é uma linha de produtos de higiene oral e saúde bucal, de cremes dentais, escovas de dente, enxaguatórios bucais e fio dental. É a marca líder de creme dental, que ajuda a prevenir problemas como cáries, tártaro, gengivite, placa bacteriana, manchas, gengivas frágeis, mau hálito e esmalte fraco, principalmente. É vendido em lojas de departamento, farmácias e pequenos negócios em mais de 200 países em todo o mundo.', 68.81, 56.07, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-823q1-moy7mivovjez4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F58211754730', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
