INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44604811630', 'Borracha com Lápis Ursinhos - Pote c/ 30 Unidades Leo&Leo Leonora - 10197', 'Com a Borracha com Lápis Ursinhos - Pote com 30 Unidades Leo&Leo, as crianças vão conhecer um mundo encantado, em que ursinhos fofos vivem em lindos lápis de madeira. Uma novidade para deixar a hora de escrever ou desenhar muito mais divertida. São quatro opções de borrachas colecionáveis em formato de ursinhos, disponíveis nas cores: branco, amarelo, preto e marrom. Impossível mesmo é levar um só. As borrachas ainda são acompanhadas ainda por um lápis de madeira, para o aprendizado virar um combo completo de diversão. Estes ursinhos fofos só poderiam ter surgido no Mundo Leo&Leo e agora vão virar os favoritos nos estojos das crianças. Características: - Marca:Leonora - Modelo:10197 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - BORRACHA COM LÁPIS URSINHOS - POTE C/ 30 UND LEO&LEO', 70.0, 62.9, NULL, 'Stationery > Writing & Correction > Pencils', 'https://cf.shopee.com.br/file/sg-11134201-825zr-mjjuiy57rrpd48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F44604811630', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23096973946', 'Camisa Ciclismo Ert Elite Jet Nova Tour Masculina MTB Speed Ciclista Blusa Bike Racing Laranja', 'Você está na Loja TMX Duas Rodas. A camisa Jet Nova Tuor é um produto pensado e desenvolvido para atletas profissionais. A modelagem padrão europeu garante conforto de performance nos mais altos níveis de competições. O design é mais FIT, as mangas e costas possuem bastante elastano, que modela a silhueta do corpo sem deixar sobras indesejáveis, garantindo aerodinâmica e menos atrito com o ar. FRENTE: Tecido 100% poliéster com tratamento TrueLife Dry, que transporta o suor para a camada externa da fibra potencializando a evaporação e a troca térmica. Conta também com proteção UV equivalente a um filtro solar fator 50 e tratamento bactericida à base de prata que afasta as bactérias evitando o mau cheiro. LATERAIS: Tecido 100% poliéster com tratamento TrueLife Dry e microporos que aumentam o fluxo de ar facilitando o conforto térmico. COSTAS E MANGAS: Tecido 86% microfibra de poliéster e 14% elastano com a função de moldar-se ao corpo em qualquer situação. Conta com tratamento TrueLife Dry, bactericida e proteção UV +50. ZÍPER: Zíper com grip e tecnologia STAND BY, uma trava inteligente que permite você controlar o cursor impedindo que ele abra sozinho e possibilita a abertura e fechamento com apenas uma das mãos enquanto você está em movimento. -Compra 100% Confiável!', 119.9, 61.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-7rbne-lm6do64oz38j25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F23096973946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
