INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19214849830', 'Aditivo Para Radiador Paraflu Verde Pronto Uso 3013', 'Aditivo Paraflu Verde Universal Veículos de Aplicação: UNIVERSAL UNIVERSAL - Outros Códigos/Observações Relacionadas a Este Produto: O fluido Paraflu Bio Híbrido Concentrado possui uma formulação balanceada a base de Glicol e inibidores de corrosão híbridos que foram desenvolvidos com a mais alta tecnologia para oferecer máxima proteção para o sistema de arrefecimento de motores endotérmicos de motocicletas, automóveis, utilitários, caminhões, máquinas agrícolas e motores estacionários. Paraflu Bio Híbrido possui a tecnologia Long Life HOAT (Hibrid Organic Acid Tecnology), que aumenta a vida útil do motor lubrificando a bomba d?água, a válvula termostática, evitando o ressecamento das mangueiras e protegendo contra a corrosão todos os tipos de motores. Sua formulação eleva o ponto de ebulição e reduz o ponto de congelamento, protegendo também contra o superaquecimento e o congelamento além de proteger contra a cavitação e não atacar os sensores eletrônicos. Possui propriedade antiespumante e anti-incrustante. Quando utilizado corretamente com água desmineralizada, protege por até 4 anos ou 120.000km. ASTM D1384. ? Híbrido ? Concentrado ? Produto ecologicamente correto ? Biodegradável ? Matéria prima de fontes renováveis ? Produzido com água desmineralizada ? Cor: Verde ? Diluição: 40% / 60% (água desmineralizada) OBS: Antes de realizar a compra, comparar o código que pesquisa com os códigos originais. Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 40.49, 40.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/02ada700e25bfaad837e4662daf4aaab',