INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399715576', 'Rolamento Universal 6004 RS 20x42x12 mm Vedado Borracha Aço Forjado - IR16004 RS', 'Especificações Técnicas: • Marca: IRB AUTOMOTIVE • Cód. da peça: IR16004 RS • Tipo de rolamento: Esferas Vedado Borracha Medidas: • Diâmetro Interno (mm): 20 • Diâmetro Externo (mm): 42 • Espessura (mm): 12 • Peso (g): 70 Os Rolamentos IRB são fabricados com aço GCR15, que é conhecido por sua excelente dureza, o que o torna capaz de suportar cargas pesadas e resistir ao desgaste, mesmo em condições de operação severas. Apesar de sua dureza, o aço GCR15 favorece uma boa tenacidade, o que significa que pode absorver impactos e choques sem quebrar facilmente, prolongando vida útil do rolamento. Rolamento ideal para diversas aplicações automotivas e industriais.', 19.9, 14.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9etmsfq5cle80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F21399715576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198546288', 'Kit Areia Higiênica Biodegradável Great Pets Gatos 4 Kg (2 pacotes de 2 kg) - Grãos Finos Fino Gato', 'Descrição: Contém: Kit 02 Areia Biodegradável Fina Great Pets para Gatos - 2 Kg A Areia Higiênica Great Pets Biodegradável Fina 2Kg é uma opção de areia sanitária para gatos que é produzida com materiais naturais e biodegradáveis, tornando-a uma opção mais sustentável para o meio ambiente. A sua composição é feita com grãos de origem vegetal, tais como amido de milho, mandioca e fibras de madeira, o que garante que a areia seja absorvente e eficiente na retenção de odores desagradáveis. Por ser uma areia fina, ela é suave para as patas dos gatos e ajuda a evitar que a urina e as fezes do gato se espalhem pela casa, mantendo a limpeza do ambiente. A Areia Higiênica Great Pets Biodegradável Fina 2Kg não contém produtos químicos nocivos, sendo segura para o uso dos gatos e para o contato humano. Além disso, por ser biodegradável, ela pode ser descartada no vaso sanitário, o que facilita o processo de limpeza e descarte. - Indicada para gatos de todas as raças - Biodegradável - Forma torrões firmes e flexíveis - Super absorvente - Não forma lama - Pode ser descartada no vaso sanitário ___________________________________________________________ A MANADA ANIMAL é um marketplace de produtos veterinários. É a escolha certa para tutores que prezam pela qualidade dos produtos que seu animal necessita. Tudo com o suporte de uma equipe de veterinários e gestores com mais de 10 anos de experiência no mercado. Fique tranquilo, todos os nossos produtos são originais, adquiridos através de distribuidores credenciados! Ah, e todas as vendas acompanham nota fiscal! MANADA ANIMAL, Tranquilidade pra você, cuidado para ele!', 101.65, 63.73, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7raux-mab94j0nvecnb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F23198546288', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
