INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45553032980', 'Lena Chapinha Profissional 2 Em 1 Alisador E Modelador Lilás Aquecimento Rápido 12 Níveis Bivolt', 'Chapinha de Cabelo Lena Profissional Titanium Care – Alisamento Rápido, Proteção e Brilho Intenso A Prancha Profissional LENA H1201 Titanium Care Íons+ foi criada para quem deseja desempenho profissional aliado a praticidade e cuidado diário. Com aquecimento ultrarrápido em apenas 30 segundos e ajuste digital de temperatura, ela alisa e modela com eficiência, sem danificar os fios. Suas placas de titânio garantem aquecimento uniforme, maior durabilidade e deslize suave. Já a tecnologia de íons negativos reduz o frizz, sela as cutículas e realça o brilho natural, deixando o cabelo mais alinhado e sedoso. O display LED permite visualizar a temperatura em tempo real, enquanto o sistema inteligente de proteção térmica oferece segurança total: desligamento automático, bloqueio infantil e proteção contra superaquecimento. Compacta, leve e prática, é perfeita para viagens, uso doméstico ou profissional — pronta para entregar resultados de salão onde você estiver.', 499.0, 289.0, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/br-11134207-81zue-ml3ohlwgmbk21c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F853344905%2F45553032980', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
