INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5290307572', 'kit trio brincos prata 925 coração 5mm redondo 5mm estrela 5mm', 'Itens inclusos: 3 pares de brincos nos formatos: coração, estrela e redondo. tamanho dos brincos: 5mm - 1 Termo de Garantia Esta linda peça, fabricada em Prata legítima, teor 925, além de linda trás a simplicidade e a elegância da beleza feminina. A Prata com teor 925, é o metal mais precioso, depois do ouro. Sua legitimidade pode ser confirmada através de sua marcação nas peças e pelo certificado de garantia que oferecemos. Garantimos a autenticidade de nossos produtos. Compre e tenha certeza de receber uma jóia com duração para o resto da vida. A prata 925 é um material que tem garantia e durabilidade permanente, assim como o ouro 18k. Nossas jóias tem certificado de autenticidade reconhecidos no mundo todo, você pode levar em qualquer joalheria para efetuar os testes e comprovar a autenticidade das mesmas. Havendo dúvidas, não hesite em perguntar por favor! Será um prazer atendê-lo. Acompanha certificado que garante teor 925 do produto.', 59.9, 49.99, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134211-23020-wv0i9uh3c7mva8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F5290307572', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894055593', 'Fritadeira Elétrica Air Fry Britânia 4,6 Litros Inox BFR46PI - 220 Volts', 'Fritadeira Elétrica Air Fry Britânia 4,6 Litros Inox BFR46PI - 220 Volts A Fritadeira Elétrica Air Fry Britânia 4,6 Litros Inox BFR46PI - 220 Volts com design em inox deixa a sua cozinha mais elegante e garante alimentos saborosos e saudáveis em poucos minutos, isso porque ela frita com pouquíssimo ou nenhum óleo e possui 1500W de potência, proporcionando mais agilidade e praticidade no seu dia a dia. A cuba com capacidade de 4,6L e o cesto de 3,5L permitem preparar alimentos para toda a família. Sem falar que o cesto é removível e possui revestimento antiaderente mais durável, fácil de limpar e que não deixa os alimentos grudarem. Frita com pouquíssimo ou nenhum óleo. Seletor de temperatura com ajuste de 80 a 200°C. Timer mecânico de 60 minutos. Capacidade do cesto 3,5L. Capacidade da cuba de 4, 6 litros. Luz indicadora de funcionamento/Aquecimento. Desligamento automático. Base antiderrapante. Cesto removível com revestimento antiaderente. Trava de segurança. Sistema de proteção contra superaquecimento. Acabamento em inox. Especificações técnicas: Código de Fabrica: 063802085 | Tipo do Produto: Fritadeira Eletrica Air Fry | Marca: Britania| Modelo: BFR46PI | Capacidade: 4,6 Litros| Capacidade da cuba:4,6 Litros| Cor: Preta| Potência: 1500W | Voltagem: 220 Volts| Imagem Meramente Ilustrativa.', 264.0, 264.0, NULL, 'Home Appliances > Kitchen Appliances > Deep Fryers', 'https://cf.shopee.com.br/file/sg-11134201-7rdxf-mcifo1ahw4vne9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F22894055593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
