INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44082894779', 'Cartão de Memória MicroSD/TF Classe 10, vídeo 4K HD, leitura/gravação de alta velocidade, para', 'Descrição do Produto: ✅ Cartão micro SD, plug-and-play (sem necessidade de software). ✅ Formato padrão: exFAT (4 GB–32 GB); compatível com FAT32 em capacidades menores; capacidades maiores suportam apenas exFAT. Confirme o formato e a capacidade máxima suportados pelo seu dispositivo antes da compra (alguns dispositivos podem suportar até 32 GB apenas). ✅ Observação de capacidade: 8 GB ≈ 7,4–7,6 GB; 16 GB ≈ 14,4–14,8 GB; 32 GB ≈ 28–30 GB; 64 GB ≈ 58,5–60 GB; 128 GB ≈ 110–120 GB. A capacidade exibida pode diferir da capacidade nominal devido a cálculos diferentes. ✅ Velocidade de leitura: até 80 MB/s para 16 GB; velocidades máximas declaradas pelo fabricante. A velocidade real varia conforme o dispositivo e o ambiente. ✅ A embalagem pode variar conforme a decisão do fabricante.', 46.8, 36.0, NULL, 'Mobile & Gadgets > Accessories > Memory Cards', 'https://cf.shopee.com.br/file/sg-11134253-8258m-mqxwnyc7pc0cb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F44082894779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14400518227', 'Lanterna Peugeot 206 98 99 2000 2001 2002 2003', 'Código do produto: 9430 A Lanterna traseira é uma peça essencial para sinalização e visibilidade em vias noturnas. Este item possui material de alta qualidade e resistência, composto com sua lente acrílico lisa, que suporta lâmpadas de até 55W. Compatível com: Peugeot - 206 1998 - 206 1999 - 206 2000 - 206 2001 - 206 2002 - 206 2003 Especificações Técnicas: - Lente Lisa - Material da Lente em Acrílico - Material da Carcaça em Plástico - Suporta lâmpadas de até 55W ATENÇÃO Garantia - 3 Meses O valor anunciado referente a Unidade. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 183.88, 183.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/2031e79d44e147df092cf37371e9b2e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F14400518227', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
