INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51807804146', 'Kit 10 Buffer Adesivo Feltro Protetor Espátula Poker Tool', 'Kit 10 Buffers Adesivos Preto - Poker Tool PROTEÇÃO ANTI-RISCO P/ ENVELPAMENTO, PPF E INSULFILM! Aplicado direto na espátula, o buffer cria uma camada de proteção que evita riscos, marcas e danos na película — principalmente em superfícies sensíveis como PPF e insulfilm. Formato inteligente, com base hexagonal alongada e pontas triangulares, feito pra encaixar melhor e acompanhar o movimento da aplicação. PROTEÇÃO ANTI-RISCO Evita marcar ou danificar a película MAIS CONTROLE NA APLICAÇÃO Deslize suave e preciso FORMATO ESTRATÉGICO Hexagonal alongado com pontas triangulares Melhor adaptação na espátula FÁCIL DE APLICAR E TROCAR Colou, usou. Simples assim. Enviamos bem embalado, super rápido e com garantia de originalidade. Garanta o seu e confira os outros produtos da nossa Loja Koala Parts. O que você recebe: 10. Buffers adesivo para espátula (cor preta)', 34.9, 34.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-8262h-mmbtwjffrrphf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288113309%2F51807804146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
