INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199053743', 'Oleo de Gergelim - 200ml - Santo Óleo', 'Usado para substituir óleos convencionais (óleo de soja, de girassol, etc) nas preparações.Etraído da semente do gergelim (Sesamum indicum). As sementes são pressionadas mecanicamente (prensagem a frio) com subsequente filtração. Composto em sua maior parte por ácidos graxos insaturados, especialmente o ômega 6 (ácido linoleico). Ingredientes Óleo de gergelim. NÂO CONTÉM GLÚTEN. ...', 40.55, 40.55, NULL, 'Food & Beverages > Cooking Essentials > Oil', 'https://cf.shopee.com.br/file/sg-11134201-825as-mfx5726vm7t617', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F22199053743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
