INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799040085', 'Magnésio + Inositol Relief - 300g Hortelã - PROFIT', 'O Magnésio + Inosotol Relief é um suplemento nutricional que combina magnésio, inositol, triptofano, melatonina, glicina e taurina, que oferecem uma série de benefícios para a saúde, graças às propriedades únicas de cada um desses componentes. Como Tomar Utilizar 1 medidor (10g) 30 minutos antes de dormir ou conforme indicação do seu médico ou nutricionista. Ingredientes Inositol, glicina, bisglicinato de magnésio, triptofano, taurina, melatonina, aroma sintético idêntico ao natural de hortelã, Acidulante Ácido Cítrico, edulcorante stévia e antiumectantes: Dióxido de silício e fosfato tricálcico. NÃO CONTÉM GLÚTEN. ...', 125.64, 125.64, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-8258b-mfx28vhqqfprea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F22799040085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297667174', 'Regulador Pressão Renault Scenic 2000 a 2009 - 133749 - 1183', 'Regulador Pressão Renault Scenic 2000 a 2009 133749 1183 Motor 1.6/2.0 16v Gasolina - (Pressão - 3,5 Bar) O sistema de injeção eletrônica de combustível tem por objetivo proporcionar ao motor um melhor rendimento com mais economia, em todos os regimes de funcionamento, fornecendo uma dosagem de combustível mais precisa com resposta mais rápida. Ele tem como função ajustar a pressão em toda a linha de combustível, desde a saída da bomba até os bicos injetores. O Regulador de Pressão pode estar montado em três posições. A localização depende do sistema de injeção eletrônica utilizado.', 90.98, 90.98, NULL, 'Automobiles > Automobile Spare Parts > Fuel System', 'https://cf.shopee.com.br/file/sg-11134201-7rd45-luf0t6zjnwiae6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21297667174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41220758187', 'Jogo Adaptador Soquete 3 Peças (1/4'''' - 3/8'''' - 1/2'''') - Tubarão', 'DESCRIÇÃO: O Adaptador de Soquetes 3 Peças TUBARÃO é produzido em aço de alta resistência, garantindo durabilidade e segurança em diferentes aplicações. Ideal para uso em parafusadeiras com ou sem impacto, permite a adaptação de soquetes com encaixe quadrado de 1/4" (6,3 mm), 3/8" (9,5 mm) e 1/2" (12,7 mm), proporcionando mais versatilidade e praticidade no trabalho. ESPECIFICAÇÕES TÉCNICAS: :: Marca: TUBARÃO :: Referência: Adaptador Soquete 3 Peças :: Material: aço cromo vanádio :: Acabamento: Preto fosfatizado :: Ponteira: Quadrado :: Medida do encaixe de saída: 1/4", 3/8" e 1/2" :: Haste: Sextavada 1/4" (compatível com parafusadeiras) :: Comprimento total: 50 mm cada adaptador :: Torque máximo recomendado: 71 N.m APLICAÇÃO: :: Indicado para uso em parafusadeiras elétricas ou à bateria, com ou sem impacto. :: Permite a adaptação para soquetes de diferentes medidas (1/4", 3/8" e 1/2"). :: Uso prático em oficinas, construção civil, mecânica automotiva e manutenções em geral. INCLUI: :: 1 (UN) Jogo de Adaptadores para Soquetes com 3 peças – TUBARÃO Medidas: 1/4", 3/8" e 1/2" GARANTIA::: Sem garantia. INFORMAÇÕES DE ENTREGA: :: Produtos enviados após a confirmação do pagamento. :: Compras realizadas de segunda a sexta-feira até as 12h são postadas no mesmo dia. :: Entregas via transportadora, PAC, Sedex ou frete expresso. :: Código de rastreio informado diretamente na plataforma após a postagem. :: É necessário garantir que haja alguém disponível no endereço de entrega para evitar devoluções.', 78.0, 78.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf1lqtw22qdg6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com