INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46600837051', 'Óculos de Sol Quadrado Premium Elegante Acetato Tendencia Blogueira Vintage uv400 Masculino Feminino', 'Descubra a sofisticação e o estilo incomparáveis com os Óculos de Sol Quadrado da Cacife Brand. Feitos em acetato italiano premium exclusivo, esses óculos são a combinação perfeita de elegância e durabilidade. Características Principais: Design Atemporal: O formato quadrado clássico é ideal para quem busca um visual elegante e moderno. Materiais de Alta Qualidade: Confeccionados em acetato italiano premium, proporcionando resistência e conforto excepcionais. Detalhes Exclusivos: Acabamento impecável e detalhes exclusivos da marca Cacife, garantindo um toque único e sofisticado. Lentes de Proteção UV: As lentes oferecem proteção total contra os raios UV, cuidando da sua visão com estilo. Conforto e Ajuste Perfeito: Leves e com ajuste ergonômico, são ideais para uso prolongado sem desconforto. Por Que Escolher os Óculos de Sol Cacife Brand? Os óculos de sol da Cacife Brand são mais do que um acessório – são uma declaração de estilo e personalidade. Feitos para quem não abre mão de qualidade e exclusividade, cada par reflete o compromisso da marca com a excelência em design e funcionalidade. Invista em um par de óculos que transcende tendências e se torna um clássico em sua coleção. Cacife Brand – Onde a sofisticação encontra a inovação. Especificações: Material da Armação: Acetato italiano premium Formato: Quadrado Proteção UV: 100% Dimensões: Comprimento da lente: 5,2 cm Altura da lente: 4,4 cm ponte: 1,8 cm Comprimento total: 14,0 cm haste: 15,0 cm Acompanha: Case personalizada Cacife Brand e flanela de limpeza!', 99.99, 69.99, NULL, 'Fashion Accessories > Eyewear > Sunglasses', 'https://cf.shopee.com.br/file/br-11134207-820ly-mosaotvfcikja4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1009389128%2F46600837051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
