INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699246324', 'Filtro Ar Cabine Fiat Doblo 2005 a 2011 - 179355 - AKX35293', 'Filtro Ar Cabine Fiat Doblo 2005 a 2011 179355 AKX35293 (Adventure / Cargo / ELX / HLX) - Motor 1.8 8v Flex - (Mecânico) - (Sem carvão) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 24.95, 24.95, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rauc-maoqtf5z2aub7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19699246324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492977482', 'Válvula Termostática Vw Gol 2000 a 2002 - 840720 - AVTS01003T80', 'Válvula Termostática Vw Gol 2000 a 2002 840720 AVTS01003T80 1.0 8/16v AT - 80º A válvula termostática é uma peça importantíssima do sistema de arrefecimento dos carros. Ela controla a temperatura do motor. Quando o motor está frio, ela fica fechada, fazendo com que o líquido de arrefecimento (água e aditivo) volte para o bloco do motor. A partir de uma determinada temperatura, cerca de 90 graus, ela se abre, permitindo a passagem do líquido para o radiador para que ele seja refrigerado e volte para o bloco. A manutenção preventiva a cada 30 mil km ou menos.', 36.29, 36.29, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd6u-lugwlnpjzlx01f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22492977482', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298132968', '40 Molde de Massinha Safari Animais Forminha Neon de Modelar Aniversario Infantil Lembrancinha Festa', '***ATENÇAO, NAO PERSONALIZAMOS OS PRODUTOS. TODOS VAO SORTIDOS NOS MODELOS DAS FOTOS. ESCOLHA A COR DESEJADA OU A OPÇÃO SORTIDO PARA IR CORES SORTIDAS. ***** ITEM ANUNCIADO: 40 UNIDADES DE CORTADOR DE MASSINHA - MODELO SAFARI ANIMAIS 🐘🦁🦒 coleção traz 8 modelos diferentes de animais (Os modelos se repetem dentro do pacote.) Material: Plástico resistente e seguro para crianças Tamanho: Comprimento entre 4 a 6 cm | Altura: 1,5 cm Transforme o momento da brincadeira em uma experiência educativa, divertida e cheia de criatividade com nosso kit de 40 unidades de cortadores de massinha no tema Safari Animais! ✅ Pensado especialmente para crianças Este produto foi desenvolvido com foco na segurança e na praticidade. Fabricado em plástico leve, resistente e atóxico, possui bordas suaves que não machucam as mãos, permitindo que as crianças usem os cortadores com total autonomia e segurança. O tamanho ideal para as mãozinhas pequenas garante uma pegada firme e confortável, facilitando o uso até pelos menores. Perfeito para atividades sensoriais e motoras! 🎨 Estimula a criatividade e o aprendizado Brincar com massinha é mais do que diversão — é aprendizado! Esses cortadores ajudam a desenvolver: Coordenação motora fina Reconhecimento de formas e animais Imaginação e criatividade Interação social em brincadeiras em grupo Ideal para uso em casa, em escolas, creches, brinquedotecas e em oficinas pedagógicas. Esse kit é uma ótima opção para quem quer oferecer um material educativo e lúdico com ótimo custo-benefício. Seja para presentear, usar em atividades escolares ou complementar a brincadeira com massinhas, é uma escolha certeira! Produto de qualidade, durável, divertido e seguro — feito com carinho para os pequenos artistas! QUALQUER DUVIDA ESTAMOS A DISPOSIÇÃO! ATENCIOSAMENTE, BOLINHA MÁGICA.', 23.79, 19.03, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m97pf0t0q9mh27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045133925%2F19298132968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
