INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799046996', 'Capa Proteção Correia Dentada Fiat Uno 2011 a 2016 - 843031 - 106129', 'Capa Proteção Correia Dentada Fiat Uno 2011 a 2016 843031 106129 1.4 8v - Inferior O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 43.83, 43.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbm2-ln8scrz3nwmy70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21799046996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9938403368', 'Filtro De Ar Condicionado Creta + higienizador CES2311', 'Filtro de ar condicionado creta O higienizador enviado será da marca Radnaq ou Orbi ( conforme disponibilidade no estoque ) Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar. HIGIENIZADOR O higienizador desempenha a função de filtrar as impurezas do ar e bloquear a entrada de maus odores no veículo. O higienizador enviado será da marca Radnaq ou Orbi ( conforme disponibilidade no estoque )', 39.99, 39.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lp9k8bm3zlud9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F9938403368', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
