INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15331761447', 'Furadeira De Impacto 1/2Pol. 800W WS3179 WESCO Profissional Parede Função Martelete', 'COMERCIAL VIPASA DISTRIBUIDORA. Furadeira De Impacto 1/2Pol. 800W WS3179 WESCO Profissional Parede Função Martelete Furadeira De Impacto 1/2" 800W Velocidade Variável Reversível Wesco Profissional Furadeira de Impacto 13mm – 800W - 220V – WS3174K 220V – Wesco Características do Produto: Velocidade variável Áreas emborrachadas Rotação Direita/Esquerda Botão trava Peso 1,8 Kg Especificações: Potência nominal: 800W Nenhuma velocidade de carga: 0-3000 / min Taxa de impacto: 0-48000 / min Tipo de mandril: mandril de chave de 13 mm Capacidade de perfuração máxima em aço: 13 mm Capacidade máxima de perfuração em alvenaria: 16 mm Capacidade máxima de furação em madeira: 30 mm Peso da máquina: 1.81 kg Dimensão da máquina: 300 x 98 x 250 mm Inclui: 1 Chave de mandril 1 Empunhadura auxiliar 1 Limitador de profundidade Sim, a furadeira elétrica Wesco WS3179 possui a função impacto, que é o mecanismo popularmente conhecido como "martelete" em furadeiras desse tipo. Essa função é ativada por um botão ou seletor e faz com que a broca, além de girar, também exerça golpes (impactos) frontais. Isso é essencial para perfurar materiais duros como alvenaria e concreto com mais facilidade. FURADEIRA ELETRICA DE IMPACTO 1/2POL 800W WS3179 WESCO COMERCIAL VIPASA DISTRIBUIDORA.', 314.99, 299.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-22110-qjhjjmgtqhjvde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F15331761447', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
