INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394218358', 'Furadeira Sem Impacto 3/8" 450W FSV 450 Vonder', 'PRODUTO PRONTA ENTREGA COM ENVO IMEDIATO Conteúdo da Embalagem: 1 Furadeira sem impacto. Possui estrutura compacta, ideal para trabalhos em locais de difícil acesso. Dispõe de interruptor eletrônico com pré-seleção de velocidade, que permite controlar a rotação da máquina, possibilitando iniciar um furo com uma rotação baixa e aumentar gradativamente de acordo com a necessidade de perfuração. Conta com sistema reversível, que facilita a retirada da broca caso ela trave durante a perfuração, e botão trava do interruptor para trabalhos contínuos. Conta também com encaixe para cinto, que facilita o transporte e a proximidade da ferramenta junto ao operador, e motor com dupla isolação, garantindo maior segurança. Possui ainda mandril de aperto rápido, proporcionando a troca rápida do acessório utilizado. Indicada para madeiras, metais, entre outros, deve ser utilizada com os acessórios adequados. Não indicada para concreto. Garantia legal: 90 dias + Garantia contratual: 9 meses (Para locadoras, garantia única e exclusiva de 90 dias) Detalhes Técnicos Modelo: FSV 450 Potência: 450 W Tipo de mandril: Aperto rápido Capacidade do mandril: 3/8" - 10 mm Sistema de reversão: Sim Tipo de velocidade: Variável Rotações por minuto (rpm): 0 - 2.800/min Capacidade máxima de perfuração em aço: 10,0 mm Capacidade máxima de perfuração em madeira: 20,0 mm Tensão (V): 127 V~ Frequência: 50 Hz / 60 Hz Incerteza da aceleração transmitida nas mãos - braços do operador - k: 1,5 m/s² Aceleração transmitida nas mãos - braços do operador - ah: 3,2 m/s² Segue norma: ABNT NBR IEC 60745-1 e ABNT NBR IEC 60745-2-1 Massa aproximada (peso): 1.532 kg', 279.9, 221.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdyg-mbznlrnrps0ea5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F22394218358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15693317427', 'Rodabrisa Gel "Tutti Frutti" 60g - Rodabrill', 'RODABRISA AROMA GEL (60 GR) RODABRILL O Rodabrisa Aroma Gel foi desenvolvido com tecnologia de alta performance em aromatização. Seu novo formato impede o vazamento, tornando o produto mais seguro e prático. Contém uma exclusiva e marcante fragrância que proporciona um ambiente agradável no interior do seu carro. Disponíveis nas Seguintes Fragâncias: "Tutti-Frutti" "Morango" "Marine" "Lavanda" "Citrus" "Carro Novo"', 12.51, 12.51, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/5ff37181e4d6c156b27c259cba89c51f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F15693317427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997829557', 'Babá Eletrônica Branca Sem Fio Digital Com Visão Noturna', 'Babá Eletrônica Sem Fio Digital Com Visão Noturna JORTAN Itens unitários inclusos: - 1 Monitor - 1 Camera - 1 Manual Especificações Técnicas: I. Especificações Técnicos Gerais Frequência de Transmissão: ISM 2400~2483.5 MHz Potência de Transmissão: 17dBm Alcance Efetivo: Interno 50m (160ft); Externo 260m (850ft) (em campo aberto) Tecnologia de Espectro Espalhado: AFH e TDMA Modo de Modulação: GFSK Temperatura de Operação: -10 ~ +45°C (14 ~ 113°F), extensível até -10 ~ +50°C Umidade de Operação: <85% II. Especificações do Monitor (Unidade do Responsável) Tela: 2.0" IPS LCD Resolução: 240 × 320 pixels Sensibilidade de Recepção: -90dBm Consumo de Corrente: 200 mA Bateria: Polímero de Lítio 540mAh Alimentação: 5V / 1A, Type-C Dimensões: 63 × 126 × 27 mm (L × A × P) Peso: 0.086 kg III. Especificações da Câmera (Unidade do Bebê) Sensor de Imagem: CMOS 0.3 Megapixel Total de Pixels: 640 × 480 pixels Iluminação Mínima: 0 Lux (infravermelho ativado) Alcance da Visão Noturna: 5m (15 FT) Ângulo de Visão: Diagonal 39° Consumo de Energia: 200mA (equivalente ao consumo do monitor, garantindo equilíbrio energético) Alimentação: 5V / 1A, Type-C Dimensões: 60 × 102 × 60 mm (L × A × P) Peso: 0.06 kg Destaques do Produto: Intercomunicador de Voz Bidirecional: Áudio de duas vias para falar com o bebê. Monitoramento de Temperatura: Acompanha a temperatura do quarto em tempo real. Canções de Ninar: Câmera com 8 canções de dormir integradas. Visão Noturna Automática: Ativação automática no escuro. Ativação por Voz (VOX): A tela liga automaticamente ao detectar som. Suporte Multilingue: Inglês, Francês, Espanhol, Português, Italiano, Alemão, Turco e Russo. Transmissão Segura e Sem Interferência: Conexão estável de longo alcance.', 699.99, 249.99, NULL, 'Mom & Baby > Baby Safety > Monitors', 'https://cf.shopee.com.br/file/sg-11134201-824hx-melt6dlcc7bbfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363055219%2F22997829557', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193205611', 'Colchão Solteiro Confortex D20 088x188x12 Plumatex Preto', 'Colchão Solteiro Confortex D20 088x188x12 Plumatex Preto ConfortexD20 tem 20 kg de pura espuma por m3. Colchão de conforto macio. Além disso ele pode ser utilizado dos dois lados, aumentando assim a sua durabilidade. A Plumatex tem mais de 37 anos fabricando espumas de alta qualidade. Tampo em tecido poliéster oferece alta durabilidade. Lateral em tecido jacquard, elegância e sofisticação. Para cada sonho um Plumatex. Características: Colchão Solteiro Marca: Plumatex Colchão Modelo: ConfortexD20 Colchão de Espuma Espuma D20 kg m3 de 12 cm Tecido tampo: Poliéster Lateral: Jacquard Dupla face: Uso dos dois lados Suporta até 50 kg por pessoa Dimensões: Altura: 188 cm Largura: 88 cm Profundidade: 12 cm Peso: 3,97 kg Garantia do Fornecedor: 03 mesesCor: Preto', 216.99, 216.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-lyp48o7k20x894', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23193205611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
