INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499594718', 'Bomba Dagua Sapo (1 Pol) 450w Modelo 950 Fenix', 'A Bomba D’Água Sapo (1 Pol) 450W Modelo 950 Fênix é uma excelente escolha para quem busca um equipamento potente e confiável para captação e bombeamento de água limpa. Com motor de 450W, oferece alto desempenho, sendo ideal para uso em poços, cisternas, reservatórios e abastecimento de residências, chácaras e pequenas propriedades. A Bomba D’Água Sapo (1 Pol) 450W Modelo 950 Fênix é a solução ideal para quem precisa de eficiência, força e praticidade no abastecimento de água. Vantagens: Maior potência: Motor de 450W que garante excelente vazão e pressão de água. Versatilidade de uso: Indicada para poços, cisternas, reservatórios e abastecimento geral. Durabilidade: Construída com materiais de alta qualidade, garantindo resistência e longa vida útil. Fácil instalação: Design compacto e funcional, permitindo instalação rápida e segura. Dados Técnicos: Voltagem: 127V ou 220v Potência: 450W Vazão: 2200L Max - 710L Min Diâmetro da saída: 1” polegada - 165mm Modelo: 950 Aplicação: Bombeamento de água limpa em poços, cisternas e reservatórios Garantia: Garantia de 6 meses oferecida pelo fabricante.', 553.9, 387.5, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rblq-m5yskruqnioe54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F20499594718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24245157873', 'Kit Devocional Priorize Deus 2025 + Bíblia Sagrada ACF | Leão Yeshua', 'Devocional Priorize Deus 2025 Priorize Deus é o devocional mais completo do Brasil. Esta ferramenta extraordinária disponibiliza uma série de recursos pensados para levar o leitor a um relacionamento diário com Deus, o que causará enorme impacto na sua vida prática e no entendimento da fé. Cada uma das 365 reflexões do livro é acompanhada de perguntas-chave, um plano anual de leitura bíblica e ministrações em áudio com acesso por QR Code, além de seções adicionais nas páginas finais. Tudo elaborado com extrema responsabilidade e dedicação para tornar a experiência do leitor com o Senhor impactante e transformadora. Bíblia Sagrada ACF | Leão Yeshua | Capa Dura Descubra a Bíblia Almeida Corrigida e Fiel (ACF): Fidelidade e Precisão nas Escrituras Explore a riqueza das Escrituras com a Almeida Corrigida e Fiel (ACF), uma tradução que se destaca pela fidelidade rigorosa aos textos originais em hebraico e grego. Elaborada por João Ferreira de Almeida, renomado tradutor bíblico, a ACF é a escolha ideal para quem busca uma abordagem mais literal e precisa na leitura da Palavra de Deus.', 79.9, 79.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9k4veu6iu6164', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F24245157873', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
