INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45710432865', 'Lenovo GM2 PRO Fones De Ouvido TWS Jogos Bluetooth À Prova Dwaterproof Água Estéreo Alta Fidelidade LED Luz Display Ener', 'Descrição do Produto: Dois hosts, orelhas esquerda e direita separadas, fáceis de usar Toque inteligente, pequeno e leve, adequado para o canal auditivo sem sobrecarregar Características duráveis com driver de potência de 13mm, pode realizar estéreo e interface C, carregamento rápido Chip Bluetooth 5.4, HD de baixa latência, 65MS sem atraso, jogo legal, redução de ruído físico. Captura precisa, chamada binaural, melhora o som. Chip personalizado para jogos, conexão de 8-10 metros é ininterrupta, forte anti-interferência, No modo de jogo, o sinal é mais concentrado. Especificações do Produto: Versão BT: BT5.4 Peso: 77g Protocolo de transmissão de áudio: SBC, AAC Porta de carregamento: Tipo-C Método de operação: toque Faixa de resposta de frequência: 2.402-2.480kHz Sensibilidade do microfone: -42dB+3dB Impedância do alto-falante: 32Q±15% Relação sinal-ruído: 90db Interface de carregamento: Type-c Distância de comunicação: 10m (sem obstáculos) Fones de ouvido: 40mah Estojo de carregamento: 350mah Produtos Incluídos: 1 * Par de fones de ouvido sem fio 1 * Estojo de carregamento 1 * Cabo de carregamento 1*Manual do Usuário Como usar: Após remover os fones de ouvido do compartimento de carregamento ao mesmo tempo, os fones de ouvido esquerdo e direito ligarão automaticamente e emparelharão (após o emparelhamento dos chips dos dois fones de ouvido: a luz do fone de ouvido principal está acesa, a luz do fone de ouvido secundário está apagada), então ligue o Bluetooth do telefone celular e clique em conectar ~ ps: Você precisa conectar manualmente na primeira vez, depois retire os fones de ouvido para conectar automaticamente ~', 71.9, 57.8, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134201-823p2-mp7yeoxzkwel79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F45710432865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
