INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993100209', 'Máscara Peel Off Asepxia Carvão Detox 30g', 'O peso líquido do conteúdo é de 30g. O Asepxia Máscara Peel Off remove cravos e o excesso de oleosidade, além de desobstruir os poros. Peel Off Carvão Detox deixa a sua pele mais saudável e bonita todos os dias. Feito para pele mista ou oleosa, A Máscara Peel Off é o complemento ideal para sua rotina de limpeza, conhecido pelo seu poder de remoção de impurezas e absorção da oleosidade. Nossa fórmula é enriquecida com o carvão ativado, um poderoso ingrediente de origem natural, deixando a pele mais lisa e sequinha. Asepxia Máscara Peel Off é perfeito para uma limpeza de pele profunda. Promove a extração dos cravos com uma simples aplicação. Modo de Uso: Limpe e seque completamente o rosto. Aplique uma leve camada sobre o rosto, evitando olhos, sobrancelhas, lábios e a raiz dos cabelos. Deixe o produto agir sobre a pele até que seque completamente, formando uma camada uniforme (aproximadamente 30-40 min). Retire a máscara com cuidado, de cima para baixo. Lave bem o rosto com água morna. Repita a aplicação uma vez por semana.', 27.48, 22.9, NULL, 'Beauty > Skincare > Face Mask & Packs', 'https://cf.shopee.com.br/file/sg-11134201-7rd4u-lwq7kyvihumra7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1284050214%2F22993100209', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
