INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297920645', 'Boneco Gamer Articulado Turma Do Problems Stick Youtuber 25cm Algazarra', 'Transforme seu mundo com este incrível boneco articulado de 25cm! Feito de plástico durável, este boneco é perfeito para fãs de todas as idades que desejam trazer a magia do jogo para o mundo real. Características do produto: - Altura: 25cm - Material: Plástico de alta qualidade - Articulação: 5 pontos de articulação para poses dinâmicas e realistas Com os bonecos da linha Algazarra, as horas de diversão são garantidas. Este boneco articulado é ideal tanto para brincar quanto para colecionar. Seja você um aventureiro em busca de ação ou um colecionador apaixonado.', 80.9, 74.9, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m13azrui5oybb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314314958%2F21297920645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263581871', 'Isotônico Sorox Zero Tangerina 550ml', 'Isotônico Sorox Zero Tangerina Bebida refrescante e saborosa, desenvolvida especialmente para auxiliar na hidratação diária. Livre de açúcares e com menos de 10 calorias, seu consumo ajuda a recuperar de forma rápida os 8 minerais importantes que perdemos ao longo do dia, além de auxiliar o funcionamento do sistema imune. O SoroX Sabor Tangerina serve para repor os líquidos e eletrólitos perdidos durante a prática de atividades físicas intensas ou em situações de desidratação. Ele é especialmente indicado para evitar a desidratação, melhorar o desempenho esportivo, prevenir câimbras musculares e promover a recuperação muscular mais rápida após o exercício. Bebida não alcoólica. Contém 550ml. Isotônico nacional.', 11.1, 10.54, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/sg-11134201-824g2-mpt3mbf502yza1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1788137634%2F58263581871', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20199544841', 'Mola Aérea Para Porta Branca Potência 3 Vonder', 'Mola Aérea Para Porta, Branca, Potência 3, Vonder Possui corpo em alumínio e duas válvulas para controle de fechamento, permitindo amortecimento. Para instalação em portas abrindo à direita e à esquerda (ângulo de abertura de 0° a 150°). Indicada para fechamento automático de portas de até 95 cm, com massa de 45 kg a 65 kg, acompanha manual de instalação. Especificações Técnicas: Potencia da mola aérea: Potência 3 Cor: Branca Largura das portas: Até 95 cm Massa aproximada (peso) (kg): 1,35 kg Conteúdo da Embalagem: 1 Mola aérea para porta.', 129.18, 97.39, NULL, 'Home & Living > Safety & Security > Door Hardware & Locks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m29phebj5hm903', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F20199544841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399580968', 'Filtro Ar Cabine Fiat Fastback 2022 a 2025 - 1353548 - AKX35323', 'Filtro Ar Cabine Fiat Fastback 2022 a 2025 1353548 AKX35323 (T200 / Audace / Impetus) - 1.0 Turbo Flex - Automático - (Sem carvão) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 28.46, 28.46, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rasi-maovso5dv4o346', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21399580968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22095811972', 'Porta Objetos 1 Din Expex Universal 603 Curto Para Carros Solução Prática Para Organizar Cor Preta', '#Auto Equip# Bem-vindo(a)!! Descrição Porta Objetos 1 DIN EPX 603: Porta Objeto Universal é projetado para espaços 1 DIN isso significa que ele pode ser instalado em qualquer carro que possua esse tipo de espaço disponível. Ele preenche espaços vazios onde não há aparelho de som instalado, proporcionando uma solução prática para organizar objetos. Atenção: A diferença entre o EXPEX 551 e o EXPEX 603, é o tamanho o modelo 603 é com a traseira curta, ambos são porta objetos universais. Especificações técnicas: - Material: Plástico - Cor: Preta - Modelo: EPX 603 Curto - 1 DIN - Fixação Firme e Encaixe Perfeito - Universal Conteúdo da embalagem: 01 Porta Objetos 1 DIN EPX 603 Preto IMPORTANTE: Garantia de 3 meses Enviamos em até 24h úteis Pedidos aprovados até 12h00 de segunda a sexta será enviado no mesmo dia Utilize o campo de “Perguntas e respostas” e esclareça suas dúvidas com nosso suporte técnico.', 39.0, 39.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Cup Holder and Organizers', 'https://cf.shopee.com.br/file/sg-11134201-7qvfa-lh7xvxu6ld3470', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402093902%2F22095811972', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
