INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204806247', 'Cooler Rise Mode Galaxy 120mm Led 1500RPM Branco', 'O Cooler Fan Galaxy Rise Mode é a escolha ideal para quem busca resfriamento eficiente, baixo nível de ruído e um visual clean e moderno para o setup. Projetado para atender desde computadores de uso diário até PCs gamers bem ventilados, este fan de 120mm entrega um equilíbrio inteligente entre desempenho térmico e estética, elevando tanto a funcionalidade quanto o visual do gabinete. Com fluxo de ar de 50 CFM, o Galaxy garante a circulação constante de ar dentro do gabinete, ajudando a reduzir o acúmulo de calor em componentes críticos como processador, placa de vídeo e armazenamento. Na prática, isso significa maior estabilidade do sistema, melhor desempenho em tarefas prolongadas e maior vida útil do hardware, mesmo em ambientes mais quentes. Especificações Técnicas Dimensões do Fan: 120mm x 120mm x 25mm Cor do Led: Branco Fluxo de ar do Fan: 50 CFM Nível sonoro: 28 dBA Velocidade: 1500 Rpm Conector: 3 pin ou Molex', 21.9, 21.9, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mke4tahwmnere5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1668186272%2F58204806247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
