INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398798029', 'Armadilha Elétrica para Mosquito 80W Mata Insetos Luminária Led com Suporte para Parede', '🦟 Mosquiteiro Elétrico Profissional – 80W – Bivolt – Eliminação Eficiente de Insetos 🦟 Mantenha sua casa, comércio ou ambiente de trabalho livre de mosquitos e insetos voadores de forma eficaz, higiênica e sem produtos químicos! Com LED UV de comprimento de onda duplo e malha elétrica densa, o Mosquiteiro Elétrico Profissional atrai e elimina mosquitos, moscas e outros insetos, garantindo mais conforto e segurança para sua família ou clientes. ✅ Vantagens e Benefícios: 🌟 Eliminação eficaz: Luz UV atrai e a grade elétrica interna elimina os insetos rapidamente. 🧼 Higiênico e seguro: Sem odores, fumaça ou produtos químicos nocivos. 🧩 Design moderno e discreto: Perfeito para qualquer ambiente. ♻️ Fácil de limpar: Estrutura desmontável para higienização rápida. 🔋 Funcionamento contínuo: Pode ser usado dia e noite. 🏠 Ideal para: ✔ Residências ✔ Frutarias ✔ Supermercados ✔ Restaurantes ✔ Hotéis ✔ Depósitos ✔ Estábulos e celeiros ⚙ Especificações Técnicas: Modelo: Armadilha para mosquitos Voltagem: Bivolt (110V-220V) Potência: 80W Área de atuação: 60 m² a 80 m² Material: Alumínio + ABS Cor: Prata e Preto Grade de proteção: Sim Tipo de luz: LED UV de comprimento de onda duplo Medidas: 46CM x 22,3CM 📦 Conteúdo da Embalagem: 1x Mosquiteiro Elétrico Profissional 1x Manual de uso 💡 Diga adeus aos insetos hoje mesmo! Adquira já o seu e garanta noites mais tranquilas e um ambiente livre de pragas.', 200.0, 129.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-823p8-mopmya7z1zb4d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F23398798029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893580975', 'Cilindro Roda Gm Corsa 1994 a 2012 - 120967 - CCR9290', 'Cilindro Roda Gm Corsa 1994 a 2012 120967 CCR9290 1.0 / 1.4 / 1.6 / 1.8 (8V) - TRASEIRO ESQ/DIR (3/4" OU 19,05mm - SISTEMA VARGA)O Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 54.13, 54.13, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd4z-m7t8r6s18vgdfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22893580975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999164836', 'Travesseiro 50x70cm Soft Touch Altenburg', 'Travesseiro Altenburg Soft Touch 50x70 cm – Maciez, suporte e conforto duradouro O Travesseiro Altenburg Soft Touch 50x70 cm foi desenvolvido para oferecer o equilíbrio ideal entre conforto, sustentação e durabilidade. Com enchimento em 100% fibra de poliéster siliconizada, proporciona toque macio, volume uniforme e excelente resiliência, mantendo o formato original por muito mais tempo. Seu nível de suporte médio é indicado para quem dorme de costas ou de lado, garantindo apoio correto para cabeça, pescoço e ombros e contribuindo para um alinhamento postural saudável. O Travesseiro Soft Touch Altenburg é inodoro, antialérgico e de fácil manutenção, ideal para quem busca um sono tranquilo e higiênico. Pode ser lavado e seco em máquina, mantendo sempre a aparência de novo e a sensação aconchegante de um travesseiro recém-adquirido. Destaques do produto: Tamanho: 50x70 cm Enchimento: 100% Fibra de Poliéster Siliconizada Suporte médio: ideal para quem dorme de costas ou de lado Toque macio e confortável com excelente resiliência Antialérgico, inodoro e lavável em máquina Alta durabilidade e fácil manutenção Produto com a qualidade e confiança Altenburg O Travesseiro Altenburg Soft Touch é a escolha perfeita para quem busca maciez, conforto e suporte equilibrado em todas as noites de sono.', 39.9, 39.9, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/sg-11134201-821e7-mgrxn8kha80fce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F22999164836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792529250', 'Rotor Distribuidor Gm Corsa 1994 a 2002 - 106553 - 21677', 'Rotor Distribuidor Gm Corsa 1994 a 2002 106553 21677 CLASSIC MOTOR 1.0/1.6 EFI COM DISTRIBUIDOR BOSCH (INJEÇÃO ELETRÔNICA) O rotor é um dispositivo do sistema de ignição que tem por finalidade, distribuir as centelhas de alta tensão para cada um dos pólos da tampa do distribuidor. Alguns rotores possuem uma resistência entre seu contato central e sua extremidade. Essa resistência serve para atenuar as interferências eletromagnéticas provocadas pela alta tensão do sistema.', 37.26, 37.26, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-8258g-mq55ltb3fi181c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22792529250', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
