INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699391798', 'Bola Volêi Mormaii Quadra Jogo Indoor Competição', 'Domine as quadras com a Bola Volêi Mormaii Quadra. Desenvolvida para atletas que buscam a união perfeita entre precisão e conforto, esta bola é a escolha ideal para quem vive a energia do vôlei de quadra com intensidade. DIFERENCIAIS: - Soft Touch (Toque Suave): A combinação de TPU e EVA proporciona conforto superior, evitando desconforto nos braços mesmo em jogos longos. - Voo Preciso: Câmara revestida com manta de nylon para maior estabilidade de trajetória e retenção de ar. - Padrão Oficial: Tamanho 5 e peso (260-280g) seguindo as especificações profissionais das federações. ESPECIFICAÇÕES: - Marca: Mormaii - Material: TPU com EVA (Camada externa macia) - Construção: 18 painéis costurados - Tamanho: 5 - Peso: 280g Sobre nós: A Mormaii vai muito além do surf. Somos uma marca multiesportiva que respira aventura e liberdade. Com um portfólio que une design moderno e resistência, nossos acessórios e equipamentos são feitos para quem busca viver com intensidade, seja na quadra, na praia ou na rotina urbana.', 229.99, 229.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-81zve-mmw2pvz7z56s1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1344241719%2F23699391798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
