INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23338323200', 'Microfone Gooseneck de Mesa com Base Dylan DG-10', 'Microfone Gooseneck de Mesa com Base Dylan DG-10 O Microfone Gooseneck de Mesa com Base Dylan DG-10 é um microfone condensador de qualidade profissional projetado para ser usado em uma mesa ou superfície plana. Ele apresenta um pescoço flexível (gooseneck) que permite ajustar o ângulo e a altura do microfone para uma captação de som mais precisa. O DG-10 é compatível com uma ampla variedade de aplicações, incluindo salas de conferência, salas de aula, estúdios de gravação e transmissão, entre outras. O microfone apresenta uma resposta de frequência ampla e uma sensibilidade de -46dB ± 2dB, o que significa que ele é capaz de captar uma ampla gama de sons, desde o mais suave até o mais alto. Especificações: Tipo: Microfone condensador de mesa com pescoço de ganso (gooseneck) Elemento: Condensador electret Padrão Polar: Cardioide Resposta de frequência: 80Hz - 11kHz Sensibilidade: -46dB ± 2dB (0dB = 1V/Pa @ 1kHz) Impedância de saída: 680 ohms Relação Sinal-Ruído: > 60dB Máximo SPL: 125dB Alimentação: Phantom power 9-52V DC Conexão de saída: XLR de 3 pinos Comprimento do cabo: 3 metros Botão de silenciamento: (mute) do microfone na base Dimensões da base: 125 x 95 x 32 mm Peso do microfone: 426g', 154.99, 154.99, NULL, 'Audio > Microphones', 'https://cf.shopee.com.br/file/sg-11134201-7qvcu-lfilh6rnzzhjd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F23338323200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
