INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46655431008', 'Boneco Funko Pop! Harry Potter 8 - Aberforth Dumbledore', 'Ilumine sua coleção do Mundo Bruxo com o Boneco Funko Pop! Aberforth Dumbledore. Inspirado em Relíquias da Morte: Parte 2, o irmão de Alvo Dumbledore aparece em sua versão marcante, pronto para enfrentar as forças das trevas. Com cerca de 10 centímetros, essa figura de vinil combina detalhes fiéis, acabamento premium e o estilo inconfundível Funko. Perfeito para fãs que buscam tornar sua coleção ainda mais épica e completa.', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-82608-mjzrw51bzcap51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F46655431008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798839278', 'Capa case capinha para iPhone 17 Pro - Magsafe Wave Fumê - Preta - Gshield', 'LEIA ANTES DE COMPRAR Os fabricantes de smartphones e smartwatches possuem variações de tamanho para cada tipo de produto, geralmente as mudanças de dimensões são acompanhadas pelo tamanho em polegadas ou pelas palavras: PLUS, +, PRO, PLAY, LITE, SE, MM, entre outras, confira antes da compra se seu dispositivo é compatível com o produto anunciado e evite transtornos em sua compra. Qualquer dúvida utilize o campo de perguntas no final da página ou leia as avaliações de outros consumidores. A Capa MagSafe Wave Fumê da Gshield é a união ideal de proteção, estilo e praticidade para o seu iPhone. Produzida com traseira em policarbonato rígido fumê e laterais em TPU macio com textura antiderrapante Wave Grip, ela oferece resistência contra impactos, riscos e desgastes do uso diário, sem abrir mão de um design moderno e sofisticado. Com compatibilidade total com a tecnologia MagSafe, a capa conta com anel magnético integrado, garantindo encaixe seguro com carregadores e acessórios magnéticos, além de permitir recarga prática sem a necessidade de removê-la. O interior possui acabamento delicado com toque suave e microtextura que evita riscos no aparelho, enquanto as bordas elevadas protegem a tela e as lentes da câmera em superfícies planas. Outro grande diferencial é a furação para cordão já integrada ao design da capa, acompanhada de um cordão incluso, que proporciona ainda mais praticidade e segurança no transporte. Essa função extra é ideal para quem busca mobilidade, mantendo o iPhone sempre à mão e reduzindo os riscos de quedas acidentais. Combinando proteção 360°, conforto, estilo premium e funcionalidades extras, a Capa MagSafe Wave Fumê da Gshield é perfeita para clientes exigentes que não abrem mão de qualidade e praticidade no dia a dia. ESPECIFICAÇÕES Marca: Gshield Material: TPU + Policarbonato Dimensões: Dimensões exatas do aparelho Cor: Preta COMPATIBILIDADE iPhone 17 Pro ITENS INCLUSOS 1x Capa protetora GARANTIA 3 meses contra defeitos de fabricação + Garantia Vitalícia Co-Participativa Com decorrer do uso a capa pode apresentar arranhões pelo contato diário com superficies SEGURO Aconselhamos para uma proteção completa a compra dos planos de coberturas contra roubo, furto e danos da Gshield, conheça nossos planos', 107.77, 107.77, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rdvn-mdsio208i1n8f6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23798839278', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698468672', '1~6 BANDEJA FESTA JUNINA BANDEIRINHA 19CM PINK FESTA JUNINA (CHOCO)', 'BANDEJA FESTA JUNINA BANDEIRINHA 19CM ROSA/PINK EM PLÁSTICO FESTA JUNINA 2025 🎉 DÊ UM TOQUE CHARMOSO E COLORIDO AO SEU ARRAIÁ DE 2025 COM ESSA BANDEJA BANDEIRINHA ROSA/PINK! PERFEITA PARA SERVIR DOCINHOS, SALGADOS E PETISCOS COM MUITO ESTILO JUNINO. 📏 DIMENSÕES: 19 CM (APROXIMADAMENTE) 🎨 COR: ROSA/PINK VIBRANTE 🚩 TEMA: BANDEIRINHA - UM SÍMBOLO ALEGRE E TRADICIONAL DA FESTA JUNINA! IDEAL PARA: ✔️ SERVIR GULOSEIMAS TÍPICAS COMO BRIGADEIROS, BEIJINHOS, MINI PÃO DE QUEIJO E MUITO MAIS! ✔️ COMPOR A DECORAÇÃO DA MESA PRINCIPAL OU MESAS DE CONVIDADOS COM UM TOQUE FESTIVO. ✔️ ADICIONAR UM ELEMENTO DECORATIVO TEMÁTICO E CHEIO DE COR AO SEU ARRAIÁ. 🇧🇷 PREPARE-SE PARA UM ARRAIÁ INESQUECÍVEL EM 2025 COM DETALHES QUE CELEBRAM A TRADIÇÃO! ESSA BANDEJA BANDEIRINHA ROSA/PINK É UM TOQUE DE ALEGRIA E ESTILO QUE SEUS CONVIDADOS VÃO ADORAR. 🛒 GARANTA JÁ A SUA BANDEJA BANDEIRINHA ROSA/PINK EM PLÁSTICO PARA A FESTA JUNINA 2025 E ARRASE NA DECORAÇÃO! IMPORTANTE: VERIFIQUE OS PRAZOS DE ENTREGA E O VALOR DO FRETE PARA SUA REGIÃO DURANTE A SIMULAÇÃO DA COMPRA.', 12.85, 12.85, NULL, 'Home & Living > Party Supplies > Disposable Tableware', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9rde3fo7x2x97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23698468672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197634538', 'Capa Case Capinha MagSafe Glitter p/ iPhone 13 Pro Max Gshield – Brilho, Proteção e Tecnologia', 'A Capa Magsafe Glitter da Gshield é a fusão perfeita de elegância e proteção para o seu {model}. A capa não é apenas um acessório, é uma afirmação de estilo! Seu acabamento de glitter não só adiciona um toque de glamour, mas também oferece uma camada robusta de proteção para o seu iPhone. Fabricada com materiais de alta qualidade, a capa foi projetada para resistir a arranhões, impactos e desgaste diário, mantendo o seu iPhone 13 Pro Max seguro e impecável em todas as situações. Graças à sua tecnologia MagSafe, você pode desfrutar de uma conexão magnética instantânea e segura com uma variedade de acessórios compatíveis, incluindo carregadores sem fio, carteiras e suportes para carro. A conexão magnética perfeita significa que seu dispositivo se alinha automaticamente com carregadores sem fio compatíveis, proporcionando uma experiência de carregamento sem esforço toda vez. Além disso, a Capa Magsafe Glitter da Gshield possui protetor de lente, para garantir que a câmera do seu iPhone 13 Pro Max permaneça protegida contra danos e arranhões. Assim, você pode capturar momentos preciosos com total confiança. Eleve o estilo e a segurança do seu iPhone 13 Pro Max com a Capa Magsafe Glitter da Gshield! ESPECIFICAÇÕES Marca: Gshield Material: Polipropileno de alta densidade Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos Certificações: US Military COMPATIBILIDADE iPhone 13 Pro Max ITENS INCLUSOS 1x Capa protetora GARANTIA 3 meses contra defeitos de fabricação', 164.97, 164.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rdy6-lxcj65rj8cwwe8', 'https://shope.ee/an_redir?origin_link=htt