INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17728890686', 'Livro - Lidere sua mente', 'Você é protagonista da sua história ou prefere se render à fragilidade? Você ocupa o centro do palco ou prefere ficar na plateia? Os sentimentos negativos têm destaque principal em sua vida? A partir dessas premissas, o autor desvenda os segredos para que cada um de nós seja o líder de sua própria mente, nos orienta sobre como ter uma mente saudável e mostra que a verdadeira mudança é conquistada dia a dia._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2022_x000D_ Autor: Augusto Cury_x000D_ Idioma: Português_x000D_ Páginas: 64_x000D_ Dimensões: L 15.50 x A 22.60 x E 0.50_x000D_ ISBN: 9786555527322', 19.9, 19.9, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/98b21a54b7e8f76f21b32d997c4a6454', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F17728890686', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
