INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22105040021', 'Junta Cabeçote Motor Corsa Hatch 1.4 8v 2008 A 2012 Fibra', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação CHEVROLET CORSA HAT. MAXX 1.4 8V ECONOFLEX 5P 2008 até 2012 CORSA HAT. PREMIUM 1.4 8V ECONOFLEX 5P 2008 até 2010 Conteúdo Da Embalagem 1 Junta do Cabeçote Tipo de Veículo para Carros Marca Criatividade, qualidade e inovação são os pilares da Tecnologia do Grupo SABÓ. Como um dos líderes mundiais no desenvolvimento de soluções em vedação e condução para a Indústria Automobilística Mundial, é uma Multinacional brasileira com plantas e escritórios distribuídos estrategicamente juntos aos principais Centros de desenvolvimento de tecnologia e um dos maiores fornecedores de vedação para as mais importantes montadoras do mundo, exportando seus produtos para mais de 40 países. O Produto A junta do cabeçote é uma peça fundamental para o funcionamento do motor do seu veículo. Ela é responsável pela união do cárter com o cabeçote, ou seja, é essa junta que une as partes metálicas fazendo com que o metal não se degrade e nem empene com o tempo. Ela é constituída de borracha e sua qualidade dependerá muito disso. Se a borracha for de qualidade ruim, será mais suscetível às altas temperaturas e poderá se romper com o calor provocado pelo motor. Os superaquecimentos são os maiores responsáveis pelos danos às juntas, que ao se romperem, causam problemas de vedação no motor como perda de compressão, mistura de líquido de arrefecimento e óleo e empenos das partes metálicas. Uma vez queimada a junta do cabeçote, o motor precisará ser aberto para substituição e realinhamento dos compartimentos metálicos. Importante • Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses por defeito de Fabricação • Valor Unitário • Imagem meramente ilustrativa EAN 7891252822334 Código do Fabricante 82233 Combustível Álcool Flex Gasolina Tipo de Junta Cabeçote', 125.19, 125.19, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbl9-lm4v9gavf97d52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F22105040021', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21361904076', 'Filtro Combustível L200 Hr Tracker Besta 80 A 2013 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação Besta 2.7 8V GS/ EST/ FULL 2004 até 2005 Besta 3.0 8V 2004 até 2005 Galant 2.3 1980 até 1984 L200 2.5 2001 até 2009 L300 2.5 1983 até 1986 Pajero 2.3 1982 até 1986 Pajero 2.5 2011 até 2013 Pajero 2.8 1992 até 2002 Pajero Sport 2.5 2006 até 2012 Tracker 2.0 8V 2001 até 2004 H100 2.5 1995 até 2004 HR 2.5 2005 até 2006 Porter 2.5 2003 até 2004 Conteúdo Da Embalagem 1 Filtro Combustível Tipo de Veículo para SUV''s e Caminhonetes Marca Quase 50 anos após sua fundação, a empresa familiar tornou-se uma empresa industrial, comercial e exportadora que investe no país criando oportunidades no presente e continuidade para as gerações futuras. A WEGA possui o mais completo catálogo de filtros, e antecipa as necessidades do mercado de reposição, diferencia-se pela rápida incorporação de novos desenvolvimentos, oferecendo lançamentos mensais de produtos que atendem aos requisitos dos diferentes mercados-alvo e expandem continuamente as opções disponíveis. Importante Tempo de garantia: 4 meses. Valor unitário. Imagem meramente ilustrativa. Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. Código do Fabricante JFC901 >', 54.92, 54.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rble-lluj8hu6dz9s92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F21361904076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
