INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197497967', 'Chumbinho Thunder 25.30gr 5.5mm 200un. - Rifle', 'Uma das partes primordiais para se atingir um bom desempenho em práticas de tiro esportivo é a qualidade do equipamento utilizado, o atirador precisa mais do que uma boa arma. Em disparos focados em precisão, chumbinhos de qualidade fazem toda a diferença. Pensando em quem deseja obter os melhores e mais precisos disparos nós da Dispropil estamos trazendo o Chumbinho Thunder 25.30gr 5.5mm 200un, esse chumbinho faz parte da série Premium da renomada Rifle, uma das fabricantes de chumbinhos mais conhecidas no mercado. O chumbinho Thunder foi projetado para aliar precisão e poder de impacto. Isso é possível graças as tecnologias de fabricação e rigoroso controle de qualidade que a Rifle possui. O processo de fabricação desse modelo é feito com materiais de alta qualidade como ligas de chumbo premium e ligas de antimônio O Chumbinho Thunder do calibre 5.5mm vem em uma resistente embalagem de lata, com sua tampa rosqueável impedindo a abertura acidental durante o transporte. Cada embalagem possui 200 chumbinhos do calibre 5.5mm (.22). Cada chumbinho Thunder pesa 1.64g (25.30gr). Produzidos em território nacional os Chumbinhos da Rifle contam com qualidade e experiência de uma empresa que está há mais de 30 anos no mercado. Não perca seu tempo e adquira o Chumbinho Thunder 25.30gr 5.5mm 200un da Rifle e tenha disparos mais precisos. Qualidade assim você só encontra aqui na Dispropil. Especificações Técnicas: - Marca: Rifle - Origem: Brasil - Referência fabricante: 1330 - Modelo: Chumbinho Thunder 25.30gr 5.5mm 200un. - Rifle - Material: Chumbo - Quantidade por lata: 200un - Saia: Lisa - Cor: Cinza - Calibre: 5.5mm (.22) - Compatibilidade: Carabina de Pressão 5.5mm - Comprimento unitário: 8mm - Peso unitário: 1.64g - Peso embalagem: 360g - Dimensões Aproximadas ( A x L x C ): 2,5cm X 7,5cm X 7,5cm Itens Inclusos: - 01 Chumbinho Thunder 25.30gr 5.5mm 200un. - Rifle', 172.18, 172.18, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rbmu-lo5pi2hi31kgbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063297286%2F19197497967', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
