INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097366779', 'Comentário do Novo Testamento | Romanos | William Hendriksen', 'Em sua última contribuição para a série de comentários do NT, William Hendriksen forneceu aos estudiosos da Bíblia muitas notas úteis sobre a linguagem do texto e o seu significado, com especial cuidado em relação a passagens controvertidas. O resultado é um comentário que combina piedade com erudição, uma ferramenta de grande valor para pastores e estudantes da Bíblia em geral. William Hendriksen, Th.D., graduou-se pelo Princeton Theological Seminary e por dez anos foi professor de Novo Testamento no Calvin Seminary. Iniciou a sua série de comentários em 1953. Desde a sua morte, em 1982, seu trabalho foi continuado e completado pelo Dr. Simon Kistemaker, professor de Novo Testamento no Reformed Theological Seminary. 14x21cm 672 Páginas', 98.9, 94.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rblv-llebkwun4o5089', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20097366779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
