INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999003959', 'Filtro Ar Vw Up 2014 a 2017 - 190468 - FAP3288', 'Filtro Ar Vw Up 2014 a 2017 190468 FAP3288 (Take/Move/High/Black) - Motor 1.0 12v Flex - (Mecânico) Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 43.95, 43.95, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbl9-lmqg3smimlrd3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20999003959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
