INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499324760', 'Carenagem Bico Frontal Pro Tork Biz 125 Ks/es 2006 2007 2008 2009 2010', 'O Bico Frontal Biz 125 Pro Tork é fabricado em Termoplástico de alta resistência com pigmentos a prova de raios uv. Confeccionado em plástico rígido fruto de materiais de extrema qualidade, é também muito leve._x000D_ _x000D_ Especificações:_x000D_ _x000D_ - Design personalizado e mais resistente que os plásticos originais;_x000D_ - Mesmo molde do modelo original, não necessita adaptações;_x000D_ - Peça pintada e envernizada;_x000D_ - Sem adesivo;_x000D_ - Marca: Pro Tork._x000D_ _x000D_ Aplicações:_x000D_ _x000D_ - Amarelo Topázio = Biz 125 KS ES 2008 e 2009 e Biz+ 125 2007;_x000D_ - Azul Saira Metálico = Biz 125 KS ES 2006;_x000D_ - Azul Twister Perolizado = Biz 125 KS ES 2007;_x000D_ - Bege Cítrico Metálico = Biz 125 KS ES 2010;_x000D_ - Prata Appaloosa Metálico = Biz 125 KS ES 2006 e 2007;_x000D_ - Prata Lumiar Metálico = Biz 125 KS ES 2008 e 2009;_x000D_ - Preto = Biz 125 KS ES 2006 a 2010 e Biz+ 125 2006 e 2007;_x000D_ - Rosa Ágata Perolizado = Biz 125 KS ES 2010;_x000D_ - Vermelho Cardeal = Biz 125 KS ES 2009;_x000D_ - Vermelho Caruaru = Biz 125 KS ES 2006;_x000D_ - Vermelho Guarau = Biz 125 KS ES 2007 e 2008._x000D_ _x000D_ Instalação:_x000D_ _x000D_ - A instalação deve ser feita por um profissional especializado. A LOJA não se responsabiliza por instalação mal realizada.', 96.9, 96.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-82613-mk45wxb9plvs9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F959561362%2F23499324760', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
