INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498798790', 'Jogo de 4 Canecas 380ml Oxford Ryo White', 'O wabi-sabi é um conceito japonês que valoriza o imperfeito, do processo de criação até o seu acabamento. Exaltar o irregular, o impermanente e o incompleto é uma homenagem da linha Ryo à esta sabedoria japonesa. A coleção Ryo Maresia traz uma composição que valoriza a beleza das praias, o toque da areia e o frescor do mar. As peças Ryo Maresia recebem aplicação de esmalte com pigmentação e de um filete reagente aplicado de forma manual garantindo a unicidade de cada peça. Conteúdo da embalagem: 4 Canecas 380Ml - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Tipo da embalagem: Papelão pardo - Material: Porcelana - Cor: Branco - Forma: Redondo - Tipo: Canecas - Linha: Ryo - Modelo: White - Unidades por kit: 4 - É apto para lava-louças: Sim - É Apto para microondas: Sim - Formato de venda: Kit - Utilizações Seguras: Resistente ao micro-ondas, Resistente a lava-louças - Condição do item: Novo - Unidades por kit: 4 - Tipo de garantia: Garantia do fabricante - País de origem: Brasil - Duração de garantia: 3 meses ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 153.56, 153.56, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7rdx9-md50babd9074b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1075271269%2F22498798790', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
