INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21357604970', 'Cama Solteiro Madeira Maciça para Colchão 78/88 x 188cm Madri Multimóveis CR4141 Imbuia', 'A Cama Solteiro Madeira Maciça para Colchão 78/88 x 188cm Madri Multimóveis é produzida 100% em madeira maciça de pinus proveniente de reflorestamento. Com dupla furação (pode ser utilizada para colchão de 78 ou 88cm) possui barras reforçadas e suporta até 110kg. Não acompanha colchão. Conteúdo da Embalagem: 1 (uma) Cama Manual de Montagem Kit Ferragem Dimensões do produto montado: Altura: 90cm | Largura: 195cm | Profundidade: 94cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. Disponível nas cores: Branco - Preto - Imbuia *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 659.99, 549.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me7jh520eadf9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F21357604970', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
