INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298143145', 'Tênis Democrata Couro Denim Drake Pulse + Cinto Dupla Face', 'Aproveite esse kit exclusivo Color Sports! O Tênis Democrata Denim Drake traz liberdade para você sair do trabalho para um happy hour com estilo e elegância. Feito em couro, ele possui fechamento em cadarço, colarinho e lingueta acolchoados, bico arredondado e detalhes de micro furos na lateral. O forro em tecido auxilia na ventilação interna. Conta com uma palmilha macia em P.U. e o solado é fabricado em TPU na tecnologia Pulse - sistema de amortecimento em que o impacto retorna como energia, se tornando um impulso repleto de leveza. Vista um visual contemporâneo, leve e confortável com Democrata. O kit acompanha 1 cinto para maior praticidade no seu dia a dia. ATENÇÃO: FORMA GRANDE. Sugerimos que compre 1 número menor.', 389.89, 389.89, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra2w-m4tbjw2rwaj2fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F22298143145', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
