INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097297164', 'Cabo Adaptador Conversor Usb Mini Sata Knup Kp-hd822', 'Desbloqueie o potencial do seu Mini SATA com o nosso Conversor USB 2.0, uma solução versátil que permite conectar facilmente unidades Mini SATA a dispositivos USB. Ideal para transferência de dados rápida e eficiente, este conversor é a ponte perfeita entre a sua unidade de armazenamento e a conveniência da tecnologia USB. Caracteristicas: - Converte o padrão USB 2.0 em Mini Sata; - Suporta CD/DVD Rom Sata de 7 + 6 pinos; - Compatível com USB 2.0 e USB 1.1 velocidade de 480Mbps e 12 Mpbs; - Plug an Play. Especificações: - Compatibilidade: Win XP ou superiores, Mac OS 10.X com superiores; - Velocidade de transferência de dados: 480Mbps Máx; - Conexão USB: Tipo A; - Conexão Mini Sata: 7 + 6 pinos.', 45.0, 26.68, NULL, 'Computers & Accessories > Peripherals & Accessories > USB Hubs & Card Readers', 'https://cf.shopee.com.br/file/sg-11134201-7rbni-lqku0fznlbt37e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F23097297164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41302993107', 'Escova Elétrica de Limpeza Recarregável 3 Escovas USB Oásis OIH-2901', 'Escova Elétrica Multifuncional Oásis OIH-2901 é a solução prática e eficiente para tarefas de limpeza do dia a dia. Leve e compacta, com apenas 210g, possui design ergonômico que se ajusta à estrutura do corpo, proporcionando maior conforto durante o uso. Com potência de 4W e alimentada por uma bateria de 800mAh, oferece autonomia e praticidade para diversas superfícies. Fabricada em ABS e nylon, conta com cabeça de escova, esponja de limpeza, lã de carneiro e acessórios variados que garantem uma limpeza completa. A instalação é punch-free, com fixação por gancho, ideal para quem busca funcionalidade sem complicações. ESPECIFICAÇÕES: - Modelo: OIH-2901 - Tamanho: 200x110mm - Peso: 210g - Voltagem: 3.7V - Potência: 4W - Capacidade da bateria: 800mAh - Material: ABS + Nylon CONTEÚDO: 1 Escova elétrica multifuncional 1 Cabeça de escova 1 Esponja de limpeza 1 Lã de carneiro 1 Gancho 1 Adesivo de parede 1 Cabo de carregamento 1 Manual de instruções', 48.9, 34.2, NULL, 'Home & Living > Home Care Supplies > Sponges & Scouring Pads', 'https://cf.shopee.com.br/file/sg-11134201-7rasy-mairq3wdhswg1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F41302993107', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394303961', 'Blusa Feminina Infinita Cor Azul', 'A Blusa Feminina Infinita Cor, desenvolvida em Viscose Khyara, é uma peça confortável e estilosa, perfeita para o dia a dia. Esta blusa possui manga curta e decote redondo, oferecendo um visual clássico e versátil. A modelagem soltinha proporciona um caimento leve e descontraído, ideal para compor looks casuais e elegantes. Feita com material de alta qualidade, esta blusa garante durabilidade e conforto durante o uso.', 99.99, 99.99, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-825a1-mr0jmpkcnbwne2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F23394303961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41831030840', 'Microfone Sem Fio Duplo Recarregável VHF Tipo C Karaokê Eventos Profissional ON-MC837', 'MICROFONE SEM FIO DUPLO RECARREGÁVEL O microfone sem fio duplo recarregável oferece excelente desempenho para apresentações, eventos, gravações, karaokê, palestras e uso profissional. Conta com transmissão estável, ótima qualidade sonora e longa duração de bateria, proporcionando praticidade e liberdade de movimento durante o uso. Possui conexão sem fio VHF, display de frequência e carregamento Tipo C, garantindo mais comodidade e eficiência no dia a dia. O receptor compacto facilita o transporte e a instalação, enquanto os microfones oferecem pegada confortável e funcionamento confiável. ESPECIFICAÇÕES GERAIS: - Tipo de banda: VHF - Display de frequência: 00 MHZ - Faixa de frequência: 174-216 MHz - Relação sinal-ruído (S/N): 96 dB - Faixa de resposta em frequência: 40 HZ - 18 KHZ - Porta de carregamento: Tipo C - Distância de transmissão: até 40 m - Tempo de carregamento: 5 h - Tempo de uso: 7 a 8 h - Fonte de alimentação do receptor: 5 Vdc / 1 A - Nível máximo de saída de recepção: 300 mv ±50 mv (-7 dB) ESPECIFICAÇÕES DO RECEPTOR: - Entrada do receptor: plugue de áudio 6,35 mm - Bateria do receptor: lítio 18650 - 3,7 Vdc/800 mA - Dimensões do receptor: 115 X 34 X 24 mm ESPECIFICAÇÕES DOS MICROFONES: - Potência de transmissão do transmissor: ≤ 10 mW - Bateria do microfone: lítio 18650 - 3,7 Vdc/800 mA - Dimensões do microfone: 253 X 50 mm CONTEÚDO DA EMBALAGEM: - 02 Microfones sem fio - 01 Receptor', 187.5, 128.37, NULL, 'Audio > Microphones', 'https://cf.shopee.com.br/file/sg-11134201-822x1-mofuv87wbh8va8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F41831030840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
