INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398800699', 'Camisa Infantil Masculina Trick Nick Verde', 'A Camisa Infantil Masculina Trick Nick é confeccionada em viscose slub, um tecido que proporciona leveza e um toque suave. O fechamento em botões permite um ajuste prático e confortável, enquanto a estampa rotativa adiciona um visual moderno e dinâmico à peça. Ideal para diversas ocasiões, a camisa une estilo e funcionalidade, mantendo os pequenos elegantes e à vontade. Perfeita para criar looks casuais e descontraídos com um toque de sofisticação.', 149.99, 119.99, NULL, 'Men Clothes > Tops > Shirts', 'https://cf.shopee.com.br/file/sg-11134201-8259j-mr0bk2nd8dn0f4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F23398800699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298974158', 'Faca Elétrica Mondial Preto 100W FA-01', 'Com a Faca Elétrica da Mondial você ganha mais tempo na cozinha, ao cortar pães, carnes, aves, frutas ou legumes. Com 100W de potência, possui alto poder de corte, lâminas duplas removíveis que garantem mais agilidade e trava de segurança para mais proteção durante o manuseio. Saiba mais sobre a FA-01 da Mondial: POTÊNCIA DE 100W: Alto poder de corte e mais agilidade nos preparos do dia a dia. LÂMINAS DUPLAS REMOVÍVEIS: As lâminas duplas garantem mais agilidade e corte com precisão. VERSATILIDADE NA COZINHA: A faca elétrica Mondial fatia carnes, aves, pães, frutas e muito mais. TRAVA DE SEGURANÇA: Assegura mais proteção durante o manuseio da faca. SISTEMA DE LIBERAÇÃO: As lâminas se soltam facilmente ao pressionar o botão, auxiliando na limpeza do produto. CABO ERGONÔMICO: Por ter um melhor encaixe nas mãos, permite mais flexibilidade ao utilizar o produto. FIO ELÉTRICO COM 1,2 METROS: Permite maior alcance e autonomia nos movimentos. UM ANO DE GARANTIA MONDIAL: A Mondial é a escolha de milhões de consumidores. Mondial, a escolha inteligente!', 199.9, 199.9, NULL, 'Home & Living > Kitchenware > Knives & Kitchen Scissors', 'https://cf.shopee.com.br/file/sg-11134201-824gl-mfcx87ahaj2jd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F991382718%2F23298974158', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398273567', 'Fresa Paralela 6 mm x 8 mm x 57,4 mm x 25,4 mm Makita', 'Fresa Paralela Dupla Makita Haste 6 mm x 57.4 mm D-67745 A Fresa Paralela Dupla Makita D-67745 é a ferramenta ideal para quem busca cortes precisos e eficientes em madeira. Projetada para marcenaria de alto desempenho, essa fresa garante resultados impecáveis, proporcionando cortes uniformes e um acabamento refinado. Seu design robusto e materiais de alta qualidade fazem dela uma excelente escolha para profissionais e entusiastas que exigem precisão e durabilidade em seus projetos. Fabricada com lâmina de metal duro, essa fresa oferece excelente resistência ao desgaste, permitindo maior vida útil e desempenho consistente mesmo após diversos usos. Seu diâmetro de 6 mm e altura de corte de 25,4 mm garantem cortes rápidos e eficientes, ideais para encaixes, canaletas e ajustes estruturais em peças de madeira. A haste de 6 mm proporciona um encaixe firme e seguro na tupia, reduzindo vibrações e garantindo um controle superior durante o manuseio. Isso significa cortes mais limpos e precisos, reduzindo a necessidade de acabamentos adicionais e otimizando o tempo de trabalho. Além disso, por ser uma fresa paralela dupla, possibilita cortes simétricos, essenciais para a construção de móveis, painéis e estruturas de madeira com encaixes perfeitos. Especificações - D: 6 - A1: 8 - L1: 57,4 - L2: 25,4 - Aplicações: Madeira - Segmentos: Marcenaria Itens inclusos - Fresa Paralela Dupla Makita D-67745 Garantia - 03 meses com o Fabricante', 53.9, 53.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdyw-mdc5odsmra6m56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F21398273567', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
