INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258299318', 'Camiseta Tommy Hilfiger Original Masculina Brand Love Small Logo Preta', 'Camiseta Tommy Hilfiger Masculina Regular Brand Love Small Logo Preta Camiseta estampada Tommy Hilfiger na cor preta. Gola redonda com acabamento canelado. Estampa tipográfica frontal HILFIGER EST. 1985 NEW YORK no lado esquerdo do peito. Possui a clássica bandeira da marca bordada na manga esquerda. Camiseta ideal para uma composição básica ou com mais presença, possibilitando um estilo flexível, que irá atender as necessidades de qualquer ocasião. Tommy Hilfiger é uma das marcas de lifestyle mais famosas do mundo sendo reconhecida internacionalmente por celebrar a essência do estilo cool clássico americano. Composição: 100% Algodão. Ref.: THMW0MW32312', 229.99, 149.99, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-81ztv-mmqh8e59twqs64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760398124%2F58258299318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
