INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257065368', 'Combo Licor Baileys 750 ML - 2 Unidades', 'Baileys é uma típica combinação irlandesa, feita a partir de leite fresco, whisky irlandês, cacau, baunilha, açúcar e destilado neutro. Uma bebida versátil, delicada e doce, que pode ser combinada com uma infinidade de outros ingredientes para criar drinks e receitas saborosas que aguçam todos os sentidos. Um ícone. Combo contém 2 garrafas de Licor Baileys 750ml, em vidro. Aprecie com moderação. Não compartilhe com menores de 18 anos.', 292.02, 292.02, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134275-820ld-mlw9zdv9nsao0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1759813503%2F58257065368', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
