INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44004050328', 'Kit 2 Mini Bonecos Youtubers Maria Clara & JP 13cm - Novabrink 1058', 'Os irmãos mais queridos da internet agora vêm juntinhos em uma versão superfofa! Com 13 cm de altura, os bonecos Maria Clara e JP são perfeitos para levar diversão, carinho e imaginação para todos os cantinhos da casa. Agora a dupla vem unida para brincar, encantar e conquistar ainda mais os pequenos fãs. Ideais para crianças a partir de 3 anos, são companheiros perfeitos para criar histórias e aventuras em miniatura!', 115.99, 115.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mau82x34iaofbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F44004050328', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899386029', 'Cueca Slip Microfibra Lupo', 'A Slip Lupo em Microfibra Sem Costura foi desenvolvida para quem busca máximo conforto, ajuste perfeito e um visual moderno no dia a dia. Produzida com Tecnologia Seamless, a peça elimina costuras laterais, reduzindo atritos e proporcionando uma sensação extremamente suave sobre a pele. Seu design anatômico garante melhor adaptação ao corpo, oferecendo conforto e liberdade de movimento durante todo o uso. O punho confortável se ajusta ao corpo sem apertar, enquanto o acabamento com costura entre pernas e elástico rebatido proporciona sustentação na medida certa sem marcar sob a roupa. Confeccionada em microfibra de alta qualidade, a slip é resistente, flexível e possui secagem rápida, além de apresentar toque macio e sedoso, ideal para uso prolongado com total bem-estar. Características Medidas de Cintura P (38 a 40): 70 cm M (42 a 44): 80 cm G (46 a 48): 90 cm GG (50 a 52): 100 cm Medidas de Quadril P (38 a 40): 88 cm M (42 a 44): 94 cm G (46 a 48): 100 cm GG (50 a 52): 110 cm Composição 93% Poliamida 4% Elastano 3% Poliéster Atenção As cores do produto podem apresentar variações sutis de acordo com o lote de fabricação e/ou configurações de tela.', 38.9, 38.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-8262o-mlrxn475oef4dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F22899386029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209454708', 'Ferrero Rocher', 'Ferrero Rocher oferece uma experiência de sabor incomparável de contraste de camadas: uma avelã inteira no meio, um delicioso recheio cremoso de avelã, um wafer crocante coberto com chocolate e pedacinhos de avelã. Cada embalagem contém 3 unidades com 37.5g. E graças à embalagem dourada, Ferrero Rocher é ainda mais único e especial. A embalagem de Ferrero Rocher é uma ótima opção para presentear quem você ama em datas especiais. Compartilhe os momentos especiais com Ferrero Rocher.', 13.49, 13.49, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-825a2-mqnel6l5cdfx4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555102%2F58209454708', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
