INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899617264', 'COIFA DA CX DIREÇÃO ESCORT 1993 1994 1995 1996 - 99255 - 123702', 'COIFA DA CX DIREÇÃO ESCORT 1993 1994 1995 1996 Função: Manter a lubrificações dos componentes por ela envolvidos Funcionamento: A Coifa é fixada através de abraçadeiras, por isso consegue vedar o componente envolvido por ela, e consequentemente proteger o componente de quaisquer impurezas que possam danificar esse componente.', 19.71, 19.71, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd3o-m6u9339de8b6b8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18899617264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20398090486', 'Pré Filtro Combustível Peugeot 408 2011 a 2016 - 1354856 - T040210', 'Pré Filtro Combustível Peugeot 408 2011 a 2016 1354856 T040210 2.0 16v Flex - Sistema Bosch - filtro externo e internoO pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 46.64, 46.64, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6f-m7bmz17fppi026', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20398090486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793069525', 'Pré Treino 4B - 300g - Nutrata', 'Suplemento alimentar pré-treino de alta qualidade, cuja composição favorece a prática de exercícios de alta intensidade. Sua Eficácia está associada ao retardo da fadiga muscular e maior performance intra treino. Diferenciais: Formulação a base de creatina, beta alanina, arginina, taurina e cafeína; Complementa os estoques endógenos de creatina', 85.9, 85.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvtabozfw6r0a9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1160496125%2F22793069525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692533308', 'Capa Proteção Correia Dentada Fiat Elba 1985 a 1996 - 184593 - 2181', 'Capa Proteção Correia Dentada Fiat Elba 1985 a 1996 184593 2181 MOTOR 1.3/1.5 (EXTERNA) O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 36.14, 36.14, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmu-lmtev4v17rc3f8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22692533308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497676319', 'Bóia Tanque Sensor Nível Gm Astra 1998 a 2001 - 511553 - 2332', 'Bóia Tanque Sensor Nível Gm Astra 1998 a 2001 511553 2332 Motor 1.8 8v Álcool O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 111.93, 111.93, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd6y-lugvg6axepk585', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18497676319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498020438', 'Episol Intense Hydra Spray FPS50 | 200mL', 'Protetor Solar Episol Hydra Spray é um protetor solar corporal bifásico com Ácido Hialurônico que, além de oferecer alta proteção contra os raios UVA e UVB, possui alto poder hidratante. Preserva o colágeno através de uma tecnologia inovadora que minimiza os danos mais profundos na pele causados pelos raios infravermelhos, devido à ação antioxidante do produto. O uso regular auxilia na prevenção do câncer de pele e de outros efeitos danosos causados pelo sol, como o envelhecimento precoce. Sua textura ultraleve é fácil de espalhar e rapidamente absorvida pela pele sem deixar resíduos e sensação de pegajosidade. Oferece proteção imediata e pode ser aplicado ainda com a pele molhada, sendo resistente à água e ao suor. É não comedogênico (não provoca cravos) e dermatologicamente testado.', 129.9, 99.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-8260m-mmahurgmt5ov3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1392870796%2F22498020438', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53909188600', 'Pneu Schwalbe Rocket Ron Performance 29x2.25 Tubeless', '===================== SOBRE O VENDEDOR ===================== Presentes no mundo do ciclismo há 25 anos, 15 deles em competições esportivas e 10 como lojista, temos um grupo composto por 4 lojas físicas, Bike Shop Avelar Drumond, BH Concept, Mundo da Bike e Bike Light, localizadas em Conselheiro Lafaiete/MG e Belo Horizonte/MG. Somos representantes das principais marcas de ciclismo do mercado e enviamos para todo o Brasil. Nossos envios acompanham nota fiscal e nossos produtos têm as devidas garantias asseguradas com os fornecedores/distribuidores oficiais das marcas. Além das lojas de Bicicletas, temos a empresa Avelar Sports, uma das lideres do país em locação de estruturas e organização de eventos. Vencedora do prêmio Guidom de Ouro 2019 com o evento "Internacional Chaoyang Estrada Real". ========================= DESCRIÇÃO DO PRODUTO ========================= Schwalbe Rocket Ron Performance, o foguete de cross-country combina velocidade e controle no nível mais alto possível. Um excelente round-rounder para pistas de corrida. Aderência incrível, baixa resistência de rolamento e excelente auto-limpeza. O mesmo desenho já consagrado foi mantido, porém agora conta com o novo composto ADDIX e específico para uso TUBELESS.TwinSkin - Camadas extras de borracha nas laterais, dando maior proteção contra cortes. ADDIX - o novo composto também para os pneus da linha performance, mais aderência, mais velocidade, mais quilometragem. A Schwalbe conseguiu isso através de um novo processo de mistura no qual os componentes para a preparação do composto da borracha, para atingir um nível de maior qualidade e desempenho.ESPECIFICAÇÕESMarca Schwalbe;Modelo: Rocket Ron;Tubless Ready TLR - Aceita uso com selante e sem câmara (Tubeless);Dobrável com composto de Kevlar;TwinSkin - Um revestimento de borracha adicionais na lateral para proteger contra cortes;Composto ADDIX PERFORMANCE (sem listra) - Nova combinação de materiais, aprimorando o produto no equilíbrio entre aderência, resistência e desgaste;TPI: 67 - 3 camadas;Calibragem recomendada: 26-54 PSI;Peso aproximado 780g; OBSERVAÇÃO: As especificações estão sujeitas a alterações sem aviso prévio, podendo variar com base na disponibilidade de componentes e outros fatores. ==================== ENVIO DO PRODUTO ==================== Seu produto será enviado em ATÉ 24 horas úteis após a confirmação do pagamento. ============= NOTA FISCAL ============= Todos os nossos produtos são enviados com nota-fiscal em seu nome e via transportadoras parceiras. ==== SAC ==== O suporte ao cliente é um dos nossos compromissos! Após a aprovação da compra você terá acesso aos nossos contatos, e poderá contar com todo o apoio da nossa equipe de atendimento.', 359.0, 295.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-820mp-mnae257bw07c30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1640908297%2F53909188600', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098589494', 'Pneu Bike Aro 16x1.75 Infantil Paco Kinder Bicicleta', 'O pneu Paco modelo Kinder é perfeito para bicicletas com aro de 16 polegadas. Com uma cor preta elegante, estes pneus são certificados pelo Inmetro, garantindo a sua segurança e qualidade. A medida de 16x1.75 (44-305mm) é ideal para bicicletas infantis, proporcionando uma condução suave e confortável. A pressão recomendada para estes pneus é de 35-65 libras (psi), permitindo uma ótima performance em diferentes condições de terreno. A estrutura em nylon 22tpi oferece durabilidade e resistência, enquanto o peso aproximado de 367 gramas garante que não adicionará muito peso à sua bicicleta. A composição destes pneus inclui elastômero, tecido sintético e arame de aço, materiais de alta qualidade que garantem a longevidade do produto. A marca Paco é conhecida pela sua confiabilidade e compromisso com a qualidade, tornando estes pneus uma excelente escolha para a sua bicicleta.', 33.16, 33.16, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rasi-mam1o7ipwr9fd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22098589494', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
