INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18198086152', 'Aspirador de Pó e Água Profissional 1000W Função Soprador Com Rodas APV 1010 Vonder', 'Aspira sólidos e líquidos, indicado para uso profissional: limpeza de pisos, carpetes, móveis, veículos, entre outros. Possui a função soprar e reservatório com encaixe fácil, que garante maior praticidade na abertura e fechamento. Conta ainda com clipe de apoio para acessórios e alça para transporte. Conteúdo da Embalagem: 1 Aspirador de pó. Acompanha: 1 mangueira flexível de sucção, 3 tubos extensores, 1 bocal cantos/escova, 1 bocal multiuso, 1 saco coletor de pó de pano (lavável), 4 rodízios, 1 filtro esponja e 1 filtro HEPA (Alta Eficiência em Retenção de Partículas). Detalhes técnicos: • Modelo: APV 1010 • Linha:Profissional • Potência:1.000 W • Capacidade do reservatório:10 L • Tipo de aspiração do aspirador de pó:Sólidos e líquidos • Comprimento do cordão elétrico do aspirador de pó:4,3 m • Dimensões (C x L x A):245 mm x 260 mm x 430 mm • Nível de ruído:95 dB(A) • Vácuo:Aproximadamente 15 kPa - 150 mbar • Segue norma:IEC 60335-1 e IEC 60335-2-2 • Frequência:60 Hz • Peso: 2,70 kg', 462.0, 279.9, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/br-11134207-820m5-mozo7tv9kz5s9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F18198086152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
