INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698018942', 'Kit Cilindro KMP Pistão Anéis Juntas Kit-a Cg 150 Titan Bros 150 2006 EM DIANTE', 'KIT KMP COMPLETO COM CILINDRO, PISTÃO, ANEL E JUNTA KIT-A KMP CG 150 2006 BROS 150 2006 O Kit KMP com Cilindro é composto por um cilindro de motor na medida STD. Compatível com: - HONDA CG 150 - 2006 EM DIANTE - HONDA BROS 150 - 2006 EM DIANTE A melhor performance para o motor de sua moto é com um Kit Cilindro Completo com Pistão, Anel e Juntas KIT A KMP! Itens Inclusos: - PISTÃO - PINO - TRAVAS DE PISTÇAO - ANÉIS DE SEGUIMENTO - JUNTAS SUPERIORES >ATENÇÃO Garantia de 3 Meses. Imagens Meramente Ilustrativas. Recomendamos que a instalação seja feita por profissional', 411.07, 411.07, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5eu1y0dn54i84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F937893879%2F20698018942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
