INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203002549', 'Sachê - Máscara de Hidratação Biomask', 'Tratamento Nutritivo para Cabelos Secos e Danificados A Máscara de Hidratação Biomask foi desenvolvida para recuperar e hidratar profundamente cabelos secos e danificados, proporcionando um tratamento altamente nutritivo com ação rejuvenescedora. Sua fórmula avançada, enriquecida com óleos vegetais, vitaminas e proteínas, restaura a hidratação natural dos fios, devolvendo maciez, brilho intenso e vitalidade. Ideal para a etapa de hidratação do cronograma capilar, a Biomask transforma a saúde e a aparência dos cabelos desde a primeira aplicação. Principais Benefícios Hidratação profunda e nutrição intensiva. Recuperação dos fios secos e danificados. Brilho intenso e toque macio. Rejuvenescimento capilar, restaurando a elasticidade e resistência. Dose concentrada para resultados imediatos. Ativos Poderosos e Suas Funções Óleos Vegetais Promovem hidratação intensa e retenção de umidade. Nutrem profundamente os fios, reduzindo o ressecamento. Blend de Proteínas Fortalece e reestrutura a fibra capilar. Restaura a elasticidade e resistência dos fios fragilizados. Indicação de Uso A Máscara de Hidratação Biomask e indicada para todos os tipos de cabelo, especialmente fios secos, ressecados ou danificados que necessitam de uma hidratação intensa e restauração da maciez e brilho. Modo de Uso Após lavar os cabelos, retire o excesso de água com uma toalha. Aplique a Máscara Biomask no comprimento e pontas, evitando a raiz. Massageie mecha por mecha, garantindo a distribuição uniforme do produto. Deixe agir por 5 a 10 minutos. Enxágue completamente e finalize como desejar. Especificações Produto de uso profissional e dose concentrada. Indicado para cronograma capilar e cuidados pós-química. Precauções Uso externo. Mantenha fora do alcance de crianças. Armazene em local fresco e ao abrigo da luz e calor. Suspenda o uso em caso de irritação e procure orientação medica. Evite contato com os olhos. Caso isso ocorra, enxágue abundantemente com água.', 19.9, 19.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-820m6-mp86mmd62v431e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703142099%2F58203002549', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22696529368', 'Shampoo Energizante Urban Style 1L', 'Produto de uso profissional.Para o público Masculino.Possui uma combinação de ativos especiais que refresca, estimula e revigora o couro cabeludo, cabelos e barba, removendo as impurezas sem ressecar. Indicado para o público masculino. AÇÃO Possui uma combinação de ativos especiais que refresca, estimula e revigora o couro cabeludo, cabelos e barba, removendo as impurezas sem ressecar. ATIVOS Com H-VIT e Biotaurina BENEFÍCIOS Refrescante e transparente; Ajuda a evitar a irritação; Protege a pele; RESULTADO Elimina impurezas e oleosidades excessiva dos cabelos e barba.', 99.99, 99.99, NULL, 'Beauty > Men''s Care > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-7qvdq-lk5r7i18933y71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719923009%2F22696529368', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
