INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260999709', 'Encaixe Vareta Capô Fiat Fiat Argo Cronos Grand Siena Marea Palio Pulse Siena Strada 46836020', 'Feito sob medida para o seu Fiat, o Amortecedor do Capô com encaixe da vareta é essencial para manter o capô do veículo aberto com segurança e praticidade. Com fácil instalação e alta durabilidade, este amortecedor proporciona mais comodidade ao realizar a manutenção do motor, verificação de fluidos ou simplesmente ao acessar o compartimento do motor. Além de facilitar o seu dia a dia, este amortecedor ajuda a prevenir acidentes, evitando que o capô se feche inesperadamente, protegendo você e seu veículo de possíveis danos. Compatível com o código 46836020, garante encaixe perfeito e funcionamento correto, garantindo a qualidade e segurança que seu Fiat merece. Invista em praticidade e segurança com este Amortecedor do Capô original Fiat.', 8.9, 8.46, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-822xi-mog5xvl3db0tec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1675755316%2F58260999709', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
