INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293884132', 'Joico K-Pak Repair Demage Shampoo Reconstrutor 1L', 'Shampoo para cabelos danificados. Joico K-PAK Shampoo To Repair Damage limpa gentilmente e restaura a força e a elasticidade da fibra capilar. Joico K-PAK Shampoo To Repair Damage proporciona toda a maciez após a retirada das impurezas. Sua característica reconstrutiva, melhora a estrutura de dentro do fio, a partir da formulação com o Complexo Quadramine - uma mistura exclusiva de proteínas com baixo peso molecular. Esta fórmula, equilibrada de 19 aminoácidos essenciais, os componentes básicos do cabelo, adere-se de forma eficaz, para garantir a máxima limpeza e reconstrução do cabelo, desde a cutícula até as pontas. Conselho de Aplicação Aplique nos cabelos umedecidos, até que haja a formação de espuma. Enxágue completamente e, se necessário, repita a aplicação.', 443.99, 443.99, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7renb-m8ak6b3wt7rla6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23293884132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
