INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7964920828', 'Copo De Treinamento Antivazamento Magia Dino 207ml Lillo', 'Copo Caneca De Treinamento Antivazamento 207ml Lillo A Caneca Antivazamento Disney Lillo é recomendada para a criança que começa a ingerir líquidos de forma independente. Colabora para que o processo de transição da mamadeira para a caneca ocorra naturalmente. O bebedor possui válvula com sistema antivazamento que impede que o líquido saia sem que a criança sugue, proporcionando a deglutição segura. Alças fáceis de segurar e em material macio que garantem a criança maior segurança ao segurar a caneca. "O Ministério da Saúde adverte: A criança que mama no peito não necessita de mamadeira, bico ou chupeta. O uso de mamadeira, bico ou chupeta prejudica o aleitamento materno." Principais Características: - Idade Recomendada: Acima de 6 meses - Válvula Antivazamento - Com alças - Cores vibrantes e estampa divertida - Modelo: Disney - Capacidade em volume: 207 mL - É antivazamento: Sim Especificações Técnicas: - Conteúdo da Embalagem: 1 Copo de Transição Antivazamento - Garantia: 30 Dias Contra Defeitos de fabricação pelo fabricante - Referência do Fabricante: 624521 - Código EAN: 7896033231084 - Marca: Lillo Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante', 39.9, 35.9, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwwwtdbg5ewvfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340054154%2F7964920828', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23596751960', 'Máscara Curl Expression Riche Rich 250ml - L''Oréal Professionnel', 'Máscara Curl Expression Riche Rich 250ml - L''Oréal Professionnel Você está comprando em uma loja Autorizada L''oréal Professionnel. Sobre o Produto: Máscara de tratamento para cabelos cacheados e crespos. Controla o frizz e proporciona fios 2x mais hidratados. A Máscara de Tratamento L''Oréal Professionnel Serie Expert Curl Expression Rich confere cabelos intensamente hidratados e desembaraçados. Sua fórmula conta com Glicerina 3% e Urea H que que auxiliam na retenção de hidratação nos cabelos, e Semente de Hibisco, uma fonte de aminoácidos e vitaminas que irão revitalizar e proteger os fios. AÇÃO: Glicerina 3%: umectante à base de plantas, mantém a água nos fios para uma hidratação de longa duração. Urea H: possui dupla ação de reter a hidratação e reforçar a barreira hidrolipídica. Semente de Hibisco: extraída do coração da flor de hibisco, é uma fonte natural rica em aminoácidos e vitaminas de alto grau. MODO DE USO: Após o shampoo, aplique a máscara nos cabelos levemente secos com toalha, e deixe agir de 2 a 10 minutos. Em seguida, enxágue bem.', 376.99, 376.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-ll0ybkos9v8o5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F23596751960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
