INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28834619840', 'Refos Derme 30 Comp', 'Somos revendedores Autorizados do Laboratório. Produto Original, Lacrado, Com nota fiscal e validade longa. Refos Derme é um suplemento alimentar em forma de comprimidos desenvolvido para cães e gatos. Cada embalagem contém 30 comprimidos, formulados com ingredientes específicos para promover a saúde da pele e pelagem dos animais de estimação. Este suplemento alimentar contém uma combinação de nutrientes essenciais, como ácidos graxos ômega-3 e ômega-6, biotina, zinco e vitaminas do complexo B. Esses nutrientes desempenham um papel importante na manutenção da integridade da pele, fortalecimento dos pelos e promoção de uma pelagem saudável. O Refos Derme auxilia no combate a problemas dermatológicos, como coceira, ressecamento da pele, descamação e queda excessiva de pelos. Além disso, contribui para o fortalecimento do sistema imunológico e possui propriedades antioxidantes, que ajudam a proteger as células da pele contra danos causados pelos radicais livres. Os comprimidos são palatáveis e podem ser administrados por via oral. A dosagem recomendada varia de acordo com o peso do animal e a orientação do médico veterinário. É importante seguir as instruções de uso e fornecer o suplemento de forma regular para obter melhores resultados. Lembre-se de sempre consultar um médico veterinário antes de administrar qualquer suplemento alimentar em seu animal de estimação. O Refos Derme é uma opção confiável para melhorar a saúde da pele e pelagem de cães e gatos, ajudando a mantê-los com uma aparência saudável e proporcionando maior conforto e bem-estar.', 119.9, 99.9, NULL, 'Pets > Pet Grooming > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7reqb-m8xf6m6cyqxzad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F28834619840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21299674415', 'Processador Crossover Digital Stetsom Stx2436bt Equalizador', 'O Processador Crossover Digital Stetsom Stx2436bt Equalizador é um processador de áudio digital que oferece uma variedade de ajustes e configurações de alta precisão para melhorar o desempenho do seu sistema de áudio. Através da comunicação Bluetooth, as informações do processador podem ser visualizadas e configuradas remotamente, utilizando smartphones com sistema Android ou iOS. Aplicativo disponível em sua loja de aplicativos gratuitamente. Seu processador de sinais digitais (DSP) permite modificações em tempo real de equalizações, filtros de crossover, alinhamento, controle de ganho, inversão de fase, limiter, roteamento digital de entradas e saídas, entre outros tratamentos. Seu recurso exclusivo de sequenciador (SEQUENCER) possibilita configurar o acionamento e desligamento programado de até três produtos a partir da conexões de acionamento remoto (S1, S2 e S3). Especificações Técnicas: • Equalizador gráfico de entrada (15 bandas e predefinições de equalização) • Equalizador paramétrico de entrada (frequência, ganho, fator Q) • Equalizador paramétrico por saída (frequência, ganho, fator Q) • Roteamento entre entradas e saídas • Crossover de alta precisão com filtros Butterworth e Linkwitz Riley e atenuações até 36 dB 8 • Alinhamento/atraso de alta precisão; • Inversão de fase • Limiter com ajuste de Threshold, Attack e Release • Ganho independente, mute por saída e volume master • Memória de trabalho com salvamento automático das configurações • Permite salvar e carregar os ajustes feitos pelo usuário • Senha de segurança para bloquear modificação dos parâmetros • Gerador de frequência, varredura de frequência e ruído rosa • Saídas para acionamento remoto com intervalo configurável • Monitoramento da bateria • Monitoramento da atuação do limiter • Atualização OAD', 329.0, 204.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8aubwz4eioh17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229977598%2F21299674415', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
