INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26492487943', 'Piscina Infantil Inflável 1000 Litros Retangular Resistente Portátil Verão Camping Jardim Mor', '🏊 Piscina Infantil Mor 1000L – Diversão e Praticidade ✅ Ideal para espaços pequenos ou viagens – leve e compacta ✅ Montagem simples com sistema de encaixe nos tubos ✅ Embalagem compacta – ocupa até 50% menos espaço ✅ Capacidade de 1000 litros – perfeita para refrescar a criançada ⚠️ Atenção: nunca deixe crianças sozinhas na água sem supervisão de um adulto. 📐 Dimensões e Peso Comprimento: 1,89 m Largura: 1,26 m Altura: 42 cm Peso: 5,2 kg Capacidade: 1000 litros 🔧 Composição Estrutura: Aço com pintura epóxi branca (mais resistência e durabilidade) Lona: PVC de alta qualidade Peças plásticas: Polipropileno 🌟 Diferenciais Desmontável e fácil de transportar Válvula de deságue para esvaziamento rápido Ótima para férias, finais de semana e áreas externas 💡 Dicas de Uso e Conservação Para manter a água limpa, utilize cloro líquido: 15 ml de cloro líquido (hipoclorito de sódio) a cada 1000L por dia Ou 60 ml de água sanitária por 1000L/dia Aplique sempre após o último banho do dia e aguarde 10 horas para reutilizar ❌ Não utilize cloro sólido ou pastilhas – eles danificam a lona 👉 Produto original Mor, qualidade reconhecida em piscinas desmontáveis.', 299.98, 199.99, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfb8xgvbe13b90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F601021305%2F26492487943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
