INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797907954', 'Kit 50 Disco de Corte Inox 115mm 13300 RPM 2 Telas Fibra de Vidro Heavy Duty', 'O Kit com 50 Discos de Corte Ecoinox é ideal para quem busca rendimento, precisão e ótimo custo-benefício no corte de aço inox, aço carbono e metais. Com reforço de 2 telas, proporciona corte rápido, estável, com menor geração de calor, pouca rebarba e ótimo acabamento. Aplicações Recomendadas Corte de aço inox e aço carbono Corte de chapas, perfis e tubos metálicos Uso em esmerilhadeiras compatíveis Trabalhos em metais não ferrosos e galvanizados Serviços que exigem corte rápido e bom acabamento Especificações Técnicas Produto: Kit com 50 discos de corte Marca: Ecoinox Tipo: Disco de corte abrasivo Quantidade: 50 unidades Indicação: Corte de aço inox, aço carbono e metais Compatibilidade: Esmerilhadeira Reforço: 2 telas de fibra de vidro Normas: ABNT NBR 15230 e EN 12413 Aplicação: Corte a seco Diâmetro - mm (pol): 115 (4-1/2) Espessura (mm): 1,0 Furo (mm): 22,2 Velocidade máxima permitida: 13300 Rotações por min ou 80 m/s Benefícios: Corte rápido, estável e com baixa geração de calor Acabamento: Pouca formação de rebarbas Uso indicado: Folhas metálicas, chapas, perfis, tubos, calhas, cabos de aço e dutos de ar Restrição de uso: Não indicado para desbaste Ângulo recomendado de uso: 90° Armazenamento recomendado: Temperatura entre 5°C e 45°C Umidade relativa recomendada: Entre 45% e 65% Validade do disco abrasivo: 3 anos a partir da data de fabricação Segurança: Utilizar EPIs como máscara, luvas e óculos de proteção SKU: LUCAS0187 Garantia: 90 dias contra defeitos de fabricação (concedida pelo fabricante).', 99.9, 59.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825av-mqz6wl3qlngk05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F22797907954', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
