INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28281187756', 'Sabonete Liquido Patchouli Com Tangerina 500ml Coala - Mãos, Corpo e Rosto', 'O Sabonete Líquido 500ml Patchouli com Tangerina Coala combina suavidade e eficácia, oferecendo uma limpeza delicada e uma fragrância única de patchouli com tangerina. Sua fórmula equilibrada é ideal para todos os tipos de pele, proporcionando hidratação e um toque de frescor duradouro. Com um design prático e moderno, é perfeito para uso diário, seja em casa, no escritório ou em qualquer lugar onde o cuidado e o bem-estar sejam prioridade. Experimente e transforme seu dia a dia com mais cuidado e trazendo um momento de prazer e relaxamento. Aguardamos sua compra e estamos à disposição!', 23.99, 23.99, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rd5k-m7w7zyxuv3112d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683952730%2F28281187756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799605160', 'Raio Dianteiro Inox Com Niples Honda Titan /99 (tambor)', 'Raio Dianteiro Inox Com Niples Honda Titan /99 (tambor) Material: Raio feito de aço inoxidável de alta qualidade, proporcionando maior resistência à corrosão e durabilidade. Compatibilidade: Projetado especificamente para a Honda Titan /99 com sistema de freio a tambor na dianteira. Função: Utilizado para manter a integridade da roda dianteira, garantindo a fixação segura do aro ao cubo da roda. Design: Raio com acabamento polido e brilho, destacando-se pela aparência estética e resistência. Niples: Acompanha niples para ajustar a tensão dos raios e garantir que a roda tenha um bom desempenho e estabilidade. Durabilidade: O material inox garante que o raio tenha uma vida útil longa, resistente a oxidação e desgaste devido ao uso contínuo. Aplicação: Ideal para moto Honda Titan /99, substituindo raios danificados ou desgastados. Facilidade de Manutenção: Maior facilidade de manutenção e limpeza devido à resistência do inox. Tamanho/Quantidades: Normalmente, o conjunto inclui raios na quantidade necessária para completar a roda dianteira, geralmente 36 ou 40 raios, dependendo do modelo da moto.', 158.48, 158.48, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rd5q-m6pfalr1d0dl68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1423437167%2F21799605160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
