INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992183653', 'Par Palheta Bosch Aerotwin Peugeot 408 Limited 2.0 2011-2016', 'Par de palhetas para o limpador do para-brisa dianteiro, específicas para o Citroen C4 Lounge do ano 2017 ao ano 2019. Bem-vindo(a) à nossa loja! Itens Inclusos: Par Palheta Limpador Parabrisa Original Bosch Aerotwin Silicone • Nesse anuncio temos palhetas com encaixe Click. • CARACTERÍSTICAS: - Fácil Montagem; - Maior estabilidade; - Limpeza silenciosa; - Longa vida útil; - Sem partes metálicas (livre de corrosão); - Tipo Click. • COMPATÍVEL COM: CITROEN DS4 - 2013 a 2016 C4 - 2014 a 2019 C4 Lounge - 2017 a 2019 PEUGEOT 308 - 2012 a 2016 408 - 2011 a 2016 • GARANTIA Colocamos à disposição sua equipe para informar as etapas corretas de entrada no processo de garantia de acordo com as recomendações do fabricante. • 100% Original com nota fiscal. • Recomendamos sempre que toda e qualquer instalação seja realizada por profissionais especializados para evitar problemas futuros, pois não somos responsáveis pela má instalação ou mau uso do produto.', 258.89, 258.89, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-820lf-mmhtw5lljq4kb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816129267%2F22992183653', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
