INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203841323', 'Carenagem Capa Do Farol Biz 125 Ano 2006 2007 2008 2009 2010 Preto Vermelho Prata Rosa Varoas Cores', 'A Carenagem do Farol Biz 125 2006/10 Pro Tork é pintada e envernizada na cor compatível ao padrão original. Com encaixe e acabamento perfeito, sua aplicação se encontra no interior da peça. Especificações: - Fabricada em matéria-prima de alta qualidade; - Marca: Pro Tork. Aplicação: - Biz 125 2006 2010 Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada. Querido cliente, tudo o que fazemos é pensando em você e na sua realização. Você é a motivação do nosso trabalho! Qualquer dúvida estaremos sempre à sua disposição. Garantia de 3 Meses Contra Defeito de Fabricação.', 64.9, 58.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-820ll-mr1lnwmgpfra4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1421013142%2F58203841323', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892975713', 'Shampoo Pro-V Miracles Pantene Equilíbrio Raiz e Pontas Frasco 300ml', 'Você sente que tem dois cabelos em um? Já tentou de tudo para remover a oleosidade e resíduos da raiz dos seus cabelos sem deixar as pontas ainda mais secas? Então o Shampoo Pantene da coleção Equilíbrio Raiz e Pontas com óleo de baobá e algas marinhas é ideal para você. Seu complexo Pro-V Miracle penetra profundamente nos fios equilibrando os cabelos mistos, com pontas ressecadas ou espigadas, purificando as raízes oleosas e eliminando as impurezas e resíduos de produtos. Além disso, sua fórmula com ingredientes hidratantes e purificantes é segura para cabelos com luzes, pois limpa suavemente, equilibrando a oleosidade da raiz para cabelos mais soltinhos, frescos e brilhosos. Mergulhe nas sensações de exuberância, pureza e leveza de coração com a fragrância repleta de notas alegres de laranja, toranja e groselha e notas florais com uma pitada de água de coco que vão transportar você para uma experiencia inesquecível. A coleção Pantene Equilíbrio Raiz e Pontas elimina a oleosidade da raiz e hidrata as pontas.', 35.99, 33.08, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rd63-luksflfvxhvxe8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1231988992%2F22892975713', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697131870', 'Escada Banqueta 3 Degraus Reforçada Alumínio Azul Mor', 'Escada Banqueta 3 Degraus Reforçada Alumínio Azul Mor A Escada Banqueta Alumínio da Mor vem para facilitar as tarefas do seu dia a dia. Em casa ou no trabalho ficará mais fácil alcançar lugares mais altos como armários, balcões e prateleiras sem muito esforço. Dobrável, ela facilita o seu trabalho além de ser fácil de carregar, já que possui prática alça de transporte. Apesar de sua estrutura compacta, a Escada Banqueta suporta até 120 Kg e se encaixa em qualquer espaço que você precisar. Leve, prática e funcional, além de escada de 3 degraus pode ser utilizada como uma confortável banqueta. É produzida com estrutura em tubo e chapas de alumínio em conjunto com peças plásticas de polipropileno, materiais de altíssima resistência que garantem segurança e estabilidade ao utilizá-la. Como se não bastasse todas essas vantagens, ainda são fabricadas de acordo com a portaria do INMETRO N° 219, de 06 de maio de 2021, o que garante a certeza de um excelente produto! Descrição do produto Marca: Mor Material: Alumínio Capacidade: 120 kg Certificação: As Escadas da Metalúrgica Mor são fabricadas de acordo com a nova portaria do INMETRO N° 219, de 06 de maio de 2021 Altura: 65 cm Largura: 42 cm Comprimento: 59 cm Peso: 2,4 kg Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 290.0, 171.81, NULL, 'Home & Living > Tools & Home Improvement > Ladders', 'https://cf.shopee.com.br/file/sg-11134201-7rd6w-lx05d0cssr1l0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F22697131870', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594208579', 'Pneu Traseiro 120/80-18 Tornado Xtz XRE Xr', 'Pneu Moto Traseiro 120/80-18 Pneu ecológico Compatibilidade: Tornado Xtz XRE Xr Aproveite a oportunidade de adquirir um pneu de alta qualidade, na medida 120/80-18 ideal para a roda Traseira. Detalhes do Produto: Medida: 120/80-18 Montagem: Compatível com câmara ou sem câmara (câmara não incluída) Desempenho Superior: Proporciona excelente aderência e estabilidade em diversas condições de estrada. Durabilidade: Fabricado com materiais de alta qualidade, garantindo maior resistência ao desgaste. Este pneu é perfeito oferecendo uma condução segura e confortável. Obs: Trabalhamos com pneus multimarcas. O produto será enviado conforme a disponibilidade em estoque. Compromisso com o Cliente: A satisfação do cliente é nossa prioridade. Escolha um pneu confiável e eleve sua experiência de pilotagem! Garantia: 3 Meses Contra Defeito de Fabricação', 199.9, 199.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbzcqk855m7bd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F695489389%2F23594208579', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
