INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26944129847', 'Porta Mantimento com Tampa Lyor Preto de Vidro e Metal 800ml', 'Porta Mantimento com Tampa Lyor Preto de Vidro e Metal 800ml O Porta Mantimento de Vidro com Tampa em Metal Vegas Preta de 800ml da Lyor é a solução perfeita para armazenar seus mantimentos com elegância e praticidade. Material de Alta QualidadeFabricado em vidro de alta qualidade, o porta mantimento preserva a frescura e a qualidade dos alimentos, garantindo durabilidade e segurança. Tampa em Metal Vegas PretaA tampa com design Vegas em metal preto oferece vedação hermética, mantendo os mantimentos frescos por mais tempo e adicionando um toque moderno e sofisticado ao conjunto. Capacidade de 800mlCom uma capacidade adequada de 800ml, o porta mantimento é ideal para armazenar porções médias de mantimentos, como grãos, massas, arroz, entre outros. Design EleganteO design elegante do porta mantimento confere um toque refinado à sua cozinha, tornando-o uma peça versátil para diferentes estilos de decoração. O Porta Mantimento de Vidro com Tampa em Metal Vegas Preta de 800ml da Lyor é uma adição funcional e estilosa à sua cozinha, proporcionando um armazenamento seguro e elegante para seus mantimentos. Lyor - Soluções completas para o seu Lar. Contém: 1 Pote Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 12,50cm x Largura 11,00cm x Comprimento 11,00cm Peso: 0,48Kg Cor: Colorido Material: Vidro Lavar com detergente neutro, esponja macia e secar imediatamente. Não lavar em máquinas, não utilizar produtos químico.', 36.0, 25.99, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-8262h-mk148t2x8n44f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F26944129847', NULL, NULL, '2