INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14510491814', 'Eleição | Charles Spurgeon', 'Neste sermão, C. H. Spurgeon, o príncipe dos pregadores afirma: Não estou pregando aqui nenhuma novidade; nenhuma doutrina nova. Gosto muito de anunciar essas antigas doutrinas que foram também anunciadas pelo Senhor Jesus Cristo. Por meio da doutrina da eleição, viajo ao passado e contemplo os pais da igreja, os mártires, os reformadores levantando-se e apertando minha mão. Essas antigas verdades são o padrão de minha fé e nelas contemplo a pátria de antigos cristãos; multidões que confessavam as mesmas verdades que defendo e que reconheceram que essa é a religião da própria igreja de Deus. 64 Páginas 12x18cm', 19.1, 18.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/a2cf25a02a041f97c955101c3e11eb02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F14510491814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204794939', 'Creme de Pentear, Gelatina Explosão de Hialurônico, Óleo de Jojoba e Argan 55ml bn.Cachos', '✨ Kit Explosão de Hialurônico + Óleo Argan & Jojoba O Kit Explosão de Hialurônico + Óleo Argan & Jojoba é ideal para cabelos cacheados, crespos e ondulados, oferecendo hidratação profunda, definição, brilho e controle do frizz no dia a dia. 💧 Creme de Pentear Explosão de Hialurônico – 1kg Promove hidratação profunda com multibenefícios, ajudando a selar a fibra capilar e combater o ressecamento. Possui ação antifrizz, proteção e efeito condicionante, deixando os fios macios, alinhados e com brilho. O cuidado queridinho da pele, agora também nos cabelos. ✨ Gelatina Explosão de Hialurônico Formulada com nanopartículas de Ácido Hialurônico, age dentro do fio promovendo hidratação duradoura. Garante máxima definição, controle do frizz e ação antirressecamento, deixando cachos e crespos macios e com brilho intenso. 🌿 Explosão de Óleos Argan + Jojoba Revitaliza e ajuda a reparar os fios sem pesar, proporcionando brilho, maciez e aparência saudável. Possui proteção térmica, ação condicionante e fragrância envolvente, além de proteger a fibra capilar dos danos diários e do calor. 📦 Conteúdo do Kit ✔ 1 Creme de Pentear Explosão de Hialurônico – 1kg ✔ 1 Gelatina Explosão de Hialurônico ✔ 1 Óleo Explosão Argan + Jojoba', 122.99, 86.09, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mke37kvuy48wd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F58204794939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
