INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51013827302', 'Fracasso Pastoral | Charles Bridges', 'Esta edição apresenta ao leitor uma seleção do clássico O ministério cristão: uma investigação das causas de sua ineficácia, de Charles Bridges ― um dos tratados mais respeitados e duradouros sobre o ministério pastoral. Aqui, você encontrará a essência de uma obra que, por gerações, tem despertado pastores para a grandeza, seriedade e responsabilidade sagrada de seu chamado. Bridges nos conduz a contemplar a origem divina do ministério, sua dignidade incomparável e o peso eterno de cuidar de almas, ao mesmo tempo que expõe, com franqueza e sensibilidade pastoral, as causas mais profundas do fracasso ministerial. Você será encorajado a perseverar, alertado contra perigos sutis do coração e inspirado a exercer um ministério mais fiel, humilde e frutífero ― para a glória de Deus e o bem eterno do seu rebanho. 23x16 cm 261 Páginas', 54.9, 49.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-825ao-mqjdpn69nlzje7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F51013827302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
