INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7658665822', 'Shampoo Automotivo 5l Wurth Com Cera De Carnauba Shw2', 'Limpeza Automotiva Shampoo Detergente Com Cera Shw 2 Wurth Descrição do Produto O SHW 2 é um detergente concentrado para lavagem de veículos. O produto foi formulado com tensoativos e matérias primas especiais para obter um alto poder de limpeza sem agredir superfícies pintadas. Possui cera em sua composição, o que gera não só a limpeza do veículo como sua proteção contra radiação solar e brilho sem polimento. Por serem concentrados, possuem alto rendimento, podendo gerar até 101L de produto final pronto para uso. PRINCIPAIS VANTAGENS Limpa mais com menos produto. Produto solúvel em água. Economia de tempo na aplicação, utilizando um produto para três finalidades (limpeza, proteção e brilho – SHW 2). Alto rendimento. Características : SHW 2: Produto com tripla-ação: limpa, protege e dá brilho. Alto poder de limpeza. Não possui solvente. Produto concentrado. Pode ser utilizado em lavadores de alta pressão. Aplicação Lavagem de veículos em geral, grande e pequeno porte. Restrições de uso Aplique à sombra, sobre o abrigo do sol. Nunca aplicar sobre superfície aquecida. Modo de usar Dilua o produto em água, conforme indicação da tabela. Faça a aplicação ao abrigo do sol, com a superfície fria. Lave o veículo com água para retirar a sujeira mais pesada. Aplique o produto sob pressão ou manualmente, utilizando uma luva lava-auto, esponja macia ou flanela. Não deixe o produto secar sobre o veículo. Enxague com água em abundância até remover todo o produto. Seque com um pano limpo e macio.', 129.89, 129.89, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/d8bc886bb2d3ef3a77cfade1c984c7c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F295637446%2F7658665822', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
