INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20878584870', 'Conjunto Assador Churrasco Faca, Chaira e Garfo Profissional Kit 3 Peças', 'Conjunto Assador Faca Garfo e Amolador - Em aço inoxidável da conceituada Marca MOR O cuidado com as facas é essencial, elas devem estar sempre afiadas para facilitar o corte do churrasco, facilitando na hora de servir seus convidados. Pensando nisso a Mor criou esse Kit do Assador! Ele acompanha uma faca, um garfo e uma chaira produzidos em aço inoxidável, que confere durabilidade e resistência às lâminas, e cabo preto em polipropileno que facilitam a higiene e dão firmeza durante o manuseio. Indispensável para a hora de servir um delicioso churrasco, esse kit é perfeito para os churrasqueiros mais requintados até os assadores de fim de semana! 01 Faca 9" - 36,3 cm x 5,2 cm x 2 cm 01 Garfo - 30 cm x 2,5 cm 01 Amolador - 32,5 cm x 4,5 cm x 3 cm ESPECIFICAÇÕES: Marca: Mor Dimensões: 16,5x44x3,1 cm (Largura x Comprimento x Altura) Peso do produto: 0,39 kg Ítens inclusos: 01 Faca 09 Polegadas; 01 Garfo 30cm X 2,5xm; 01 Chaira 31,5cm X 4,5cm X 3cm Materiais: Lâminas: Aço Inoxidável; Cabos: Polipropileno', 39.9, 35.9, NULL, 'Home & Living > Kitchenware > Knives & Kitchen Scissors', 'https://cf.shopee.com.br/file/sg-11134201-7qvdt-lfpoma1ackmfca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415129379%2F20878584870', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
