INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22607234153', 'Eudora Siáge Cauterização dos Fios 4D Shampoo 250ml', 'Shampoo Siàge Cauterização dos Fios possui espuma cremosa que limpa sem ressecar e purifica profundamente os fios sem retirar seus nutrientes. Desenvolvido para cabelos danificados, ajudando a preencher as áreas fragilizadas enquanto limpa delicadamente, sem retirar seus nutrientes, fórmula enriquecida com colágeno vegetal e aminoácidos, que restauram enquanto protegem o fio. * RESULTADO: Brilho Maciez * SUGESTÕES DE USO: 1.Aplique o shampoo no cabelo molhado; 2.Massageie suavemente; 3.Enxague; 4.Repita a operação se necessário. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 Eudora Siáge Cauterização dos Fios 4D Shampoo 250ml', 52.9, 41.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-22110-qn97icyhr9jvb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F22607234153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
