INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393537878', 'A Saga Wingfeather: O Guardião e o Rei Lobo | Andrew Peterson', 'UMA JORNADA ÉPICA RUMO À BATALHA FINAL PELA ILHA BRILHANTE! O inverno chegou ao fim, mas a luta pela liberdade de Vales Verdes apenas começou. Janner, Kalmar e Leeli ― o Guardião do Trono, o Rei Lobo e a Donzela da Canção de Anniera ― treinaram incansavelmente para enfrentar Gnag, o Sem-Nome, e seus terríveis Fangs de Dang. Porém, quando os Fangs atacam Ban Rona, a família é cruelmente separada. Janner vaga perdido pelos vales sombrios; Leeli combate bravamente na cidade sitiada; e Kalmar carrega um segredo sombrio rumo às profundezas de Throg, onde dragões-marinhos espreitam em águas turbulentas. Enquanto isso, em Skree, Sara e Maraly cuidam do estilhaçado Artham Wingfeather, o último obstáculo para os Fangs dominarem o Grande Rio Blapp. Não perca a conclusão arrebatadora da aclamada Saga Wingfeather! Uma aventura repleta de sacrifícios heroicos, coragem incomparável e o constante deslumbramento do desconhecido. Marginais perversos, corre-cristas, trolls e incontáveis outros perigos separam as crianças Igiby de sua única esperança de vitória. Prepare-se para uma terrível jornada rumo à batalha definitiva pela Ilha Brilhante! 16x23cm 512 Páginas', 72.9, 72.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7reo9-m2mzscsc5b0m17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23393537878', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
