INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14433814148', 'Enciclopédia de Bíblia, teologia e filosofia: 6 Volumes', 'Enciclopédia de Bíblia, Teologia e Filosofia Abrangente, informativa, indispensável Desde 1991, nunca se viu no mercado editorial uma obra de referência e consulta dessa amplitude e envergadura. A Enciclopédia de Bíblia, Teologia e Filosofia é uma produção literária sui generis, isto é, única do seu gênero. Enquanto algumas obras expõem apenas um certo domínio de conhecimento — por exemplo, há enciclopédias tão somente de Bíblia, outras abarcam unicamente o campo da Teologia e outras ainda se ocupam exclusivamente da Filosofia —, a Enciclopédia de Bíblia, Teologia e Filosofia reúne o conjunto de todos esses conhecimentos humanos, numa relação de intertextualidade e interdiscursividade. Essa obra abrangente, informativa e indispensável expõe uma soma considerável de saberes de forma ordenada, metódica, seguindo um critério de apresentação alfabética. Os números impressionam: • 15.210 verbetes distribuídos em 6 volumes. • Mais de 5.200 páginas. • Mais 730 fotos e ilustrações. • Mais de 80 outros recursos como diagramas, tabelas e mapas. Por que comprar três obras distintas se você pode ter em uma única obra os três pilares do conhecimento humano, uma enciclopédia três em um? A Enciclopédia de Bíblia, Teologia e Filosofia cumpre com maestria seu papel de informar, instruir e capacitar intelectualmente o leitor desejoso de conhecer esses ramos do saber universal.', 694.99, 694.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/15d0479ee49230acda54705ed14773cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F14433814148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492588264', 'Criado para ser Eterno | 40 dias descobrindo o seu propósito | Kennedy Carvalho', 'Criado para Ser Eterno" nos convida a uma jornada de exploração profunda sobre o propósito da vida humana e nossa busca por significado em um mundo em constante mudança. Escrito por Kennedy Carvalho, este livro oferece uma perspectiva espiritual e reflexiva sobre a natureza da existência, a busca por significado e o destino eterno que todos nós enfrentamos. Através de uma combinação de insights bíblicos, filosóficos e experiências pessoais, o autor nos guia através dos desafios e questionamentos que muitas vezes surgem em nossa jornada pela vida. Ele examina as verdades intemporais sobre a vida, a morte e o além, explorando como podemos encontrar um sentido duradouro em meio às complexidades da existência. "Criado para Ser Eterno" não apenas nos convida a refletir sobre o propósito da vida, mas também perspectivas práticas sobre como viver uma vida oferece plena e significativa. O livro aborda temas como identidade, espiritualidade, relacionamentos e anseios humanos por eternidade, fornecendo orientações para nos conectarmos com nosso verdadeiro propósito. Por meio de histórias tocantes, exemplos inspiradores e uma abordagem acessível, Kennedy Carvalho nos lembra que criamos para algo maior do que as circunstâncias passageiras deste mundo. Ele nos desafia o olhar além do presente e abraça a perspectiva de uma eternidade significativa, moldando assim nossas escolhas e ações no presente. "Criado para Ser Eterno" é um convite para explorar a interrupção de nossa existência e descobrir como viver uma vida concedida com o propósito divino que nos aguarda além desta vida terrena. O livro inspira os leitores a contemplarem a vida sob uma nova luz e abraçarem a jornada em direção a uma eternidade com significado e esperança. 112 Páginas 14x21cm', 20.9, 20.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbk2-lnax3ml87kre49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22492588264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193007583', 'O Grande Exército de Deus | Spurgeon: 10 Sermões sobre Anjos | Capa Dura', 'O grande exército de Deus: 10 sermões sobre anjos - Charles H. Spurgeon Em "O grande exército de Deus", Charles H. Spurgeon, aclamado como “o príncipe dos pregadores”, nos conduz por um fascinante mergulho no mundo angelical. Os anjos, essas magníficas criaturas que habitam na presença majestosa do Todo-poderoso, sempre exerceram uma profunda fascinação sobre as pessoas. Spurgeon explora sua importância, seu papel na obra divina e sua interação contínua com o povo de Deus. Neste conjunto de dez sermões criteriosamente selecionados, Spurgeon revela diversos aspectos dos anjos, desde o seu interesse pelo evangelho até seu ministério protetor e assistencial em favor dos crentes. Ele nos convida a refletir profundamente sobre a influência desses seres celestiais em nossa vida e na história da salvação. Ao explorar a conexão entre os reinos espiritual e físico, Spurgeon desafia seus leitores a viverem de forma digna do escrutínio angelical, aproveitando a assistência sobrenatural disponível para os seguidores de Cristo. Estes sermões, que encantaram os ouvintes de Spurgeon no século 19, continuam a ressoar como uma fonte de inspiração e edificação para os amantes das Escrituras na atualidade. "O grande exército de Deus" é mais do que apenas uma exploração teológica sobre os anjos; é um convite para que os leitores transformem sua compreensão da obra divina e fortaleçam sua confiança no grandioso exército de Deus que nos envolve e nos protege. 16x23cm 208 Páginas', 40.9, 34.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd6o-lv6qldzcwa8n8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23193007583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998270284', 'Livro de Atividades Completando a Cena com Adesivos Turminha Paraiso: Na floresta com Jubão', 'Completando a Cena oferece uma experiência única e interativa, combinando uma história incrível com atividades que tornam o momento da leitura divertido e envolvente. Isso mesmo, complete as páginas com a cartela de adesivos que acompanha o livro. A diversão é aqui, com a Bicho Esperto!', 16.9, 16.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdy1-mcm3td1e3k8s83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F20998270284', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
