INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898423151', 'Beleza Brasileira Esfrega Bumbum 50g', 'O Esfrega da Beleza Brasileira foi especialmente desenvolvido para limpar e esfoliar a pele, sem agredir, deixando sua pele macia e hidratada, além de auxiliar na prevenção de estrias e celulite. Formulado com associação de Algas Fucus e extratos de plantas ricas em elementos fitodrenantes, Pró Vitamina B5 e exclusivas Perolas de Ceras de Farelo de Arroz e Microgranulos de Sílica. O que só ele faz: • Previne estrias e celulite; • Deixa a pele macia e livre de impurezas; • Remove células mortas e promove renovação celular; • Hidrata e auxilia na firmeza da pele; Itens Inclusos: 1-Beleza Brasileira Esfrega Bumbum 50g.', 50.0, 20.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/br-11134201-820m7-mqycvlnv2f471f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F23898423151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
