INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4776457031', 'Chocolate Prestigio Dark C/30un 33gr - Nestlé', 'Chocolate Prestigio Dark Marca: Nestlé Quantidade: 30un Peso Unitário: 33gr Bombom recheado com coco coberto com chocolate meio amargo Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor. Dúvidas: Tire todas as suas dúvidas antes de realizar a compra, iremos responder o mais rápido possível. Se a dúvida for de prazo de validade também deverá ser feita no campo de perguntas abaixo. Diversas variações (cores, sabores, modelo): Quando o produto tiver variações para escolher por favor nos notificar no campo de pergunta abaixo ou após a compra nas mensagens. Estoque: Todos os produtos anunciados estão em estoque e serão enviados no prazo. Caso ocorra a falta, será enviado acrescentando 1 dia útil. Envio: Compras feitas até as 12:00h, de segunda a sexta será enviada no mesmo dia e compras feitas após 12:00 serão enviados no próximo dia útil. Prazo de Entrega: O prazo é estipulado pelo o junto com o Correio. Normalmente chegam os pedidos nas datas corretas que são disponibilizadas no calculador de frete, porém podem acontecer atrasos por erro do Correio, principalmente se o frete não for o modo expresso. Embalagens: Todos nossos produtos são muito bem embalados para não chegarem danificados. Não se preocupe, os chocolates chegam em perfeito estado, não derretem no transporte.', 109.39, 109.39, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/8fc52bc94590cf41475bb1574fe01d06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.co