INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593692781', 'Kit 2 Chumbinhos Naja Max 5.5mm 200pcs/pot - Votex + Alvo Javali', 'Chumbinho Naja Max 5.5mm 200pcs/pot - Votex Os chumbinhos Naja Max 5.5mm da Votex são a escolha perfeita para entusiastas de tiro esportivo que buscam desempenho e precisão superiores. Com um peso de 1,401g (21,622gr), esses chumbinhos proporcionam um voo estável e uma trajetória previsível, resultando em disparos mais precisos e consistentes. Fabricados com uma liga de chumbo de alta qualidade, os chumbinhos Naja Max oferecem uma combinação ideal de penetração e energia de impacto. Sua construção sólida e design aerodinâmico garantem uma estabilidade excepcional durante o voo. Cada embalagem contém 200 chumbinhos, fornecendo um suprimento adequado para suas sessões de tiro. A embalagem em formato de pote permite um armazenamento conveniente e protege os chumbinhos contra danos e umidade, garantindo que eles estejam sempre em perfeitas condições de uso. Os chumbinhos Naja Max são compatíveis com armas de calibre 5.5mm, como carabinas de pressão, proporcionando resultados consistentes e satisfatórios em cada disparo. Especificações Marca: Votex Modelo: Naja Max Calibre: 5.5mm Peso: 1,401g (21,622gr) Material: Liga de chumbo Quantidade: 200 chumbinhos por embalagem Utilização: Tiro esportivo, tiro ao alvo, prática de tiro Contém: 02 Embalagens de Chumbinho Naja 5.5mm com 200 cada 01 Alvo Javali de Metal ATENÇÃO: "O uso do produto exige treinamento e equilíbrio emocional." "Deverá ser guardado em lugar seguro e fora do alcance de terceiros."', 99.9, 99.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rbms-m5u1df9rxt1q02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567374315%2F22593692781', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20096973176', 'Pantufa Star Infantil Sullivan Monstros SA – Disney', 'Em dúvida se vai de tênis ou pantufa? A gente te Ajuda! Com a Pantufa All Star, seus problemas acabaram! É a companhia perfeita para os dias em que a previsão é de série e muita preguiça, possui uma sola emborrachada para você não escorregar nas corridas da sala para o quarto ou cozinha! Não importa o clima, com essa pantufa o seu pé está sempre quentinho! O produto é importado, com detalhes incríveis que vão fazer você e seu filho se apaixonarem! Se você já teve um dia de dúvidas entre deixar o seu filho de pantufa ou tênis, seus problemas acabaram! Feita em malha fleece, para garantir o conforto térmico durante as brincadeiras! Com a sola produzida em 3 camadas em EPE/EVA e uma borracha antiderrapante, para ninguém escorregar nos dias de correria! Não importa se é na rua ou em casa, essa pantufa te acompanha em todos os lugares! Comprimento X Largura X Altura: Infantil - Unissex Tamanho P: Calça 26 - 28 Tamanho M: Calça 29 - 31 Cuidados e recomendações de uso: Lavar a mão com água fria. Não usar alvejante. Secar na horizontal. Secagem natural. Não passar e limpar a seco.', 64.9, 64.9, NULL, 'Men Shoes > Sandals & Flip Flops > Indoor Slippers', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mg5dh8kc43rj1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F20096973176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
