INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18998322388', 'Filtro de Óleo Blindado Bosch 0986B00014', 'Os filtros de óleo Bosch são projetados para remover impurezas e partículas indesejadas do óleo do motor, garantindo uma lubrificação adequada e prolongando a vida útil do motor. Eles são fabricados com materiais duráveis e utilizam tecnologia avançada para filtrar eficientemente o óleo. Especificações Técnicas: - Marca: Bosch; - Código do fabricante: 0986B00014; - Inclui válvula alívio: Sim; - Modelo: Blindado; - Parada de retorno da pressão de abertura: 0,12 Bar; - Tipo de rosca unificada: 3/4"16UNF; - Válvula de bypass da pressão de abertura: 0,4 Bar. Aplicações: Para verificar se a peça é compatível com o seu veículo, recomendamos entrar em contato conosco para mais informações. Conteúdo da embalagem: - 1x filtro de óleo Bosch. Observações: - A Autorama comercializa somente peças originais fornecidas direto dos fabricantes. - Recomendamos que, antes da compra, verifique junto a um profissional do ramo se a peça desejada é a correta. A Autorama não se responsabiliza pelo mau uso do produto.', 58.39, 58.39, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-mbpr40w6dpng1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F18998322388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
