INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208131212', 'Par Aros Alumínio Three Heads Preto Ambos Na Medida 18x1.60', 'Par de Aros Three Heads Alumínio Preto Esse anúncio contém: 01 par de aros Three Heads na cor preta (ambos na medida 18x1.60 - medida personalizada) Especificações dos aros: Marca: Three Heads Cor: Preto Brilhante Material: Liga de alumínio 6063 - oferece leveza, ótima resistência estrutural e excelente vida útil. Medida personalizada: 18x1.60 (dianteiro e traseiro) Características: - Liga de alumínio 6063 proporciona excelente desempenho estrutural, sem comprometer a leveza - Aros com acabamento preto moderno, ideal para personalizações ou upgrades visuais - Kit ideal para montagem sob medida de rodas aro 18x1.60, tanto dianteira quanto traseira Instalação e envio: Produto não vai montado - os componentes são enviados separadamente para montagem de acordo com o projeto da moto Recomendado que a montagem e alinhamento sejam feitos por profissional especializado Envio rápido, seguro e monitorado. Sobre a marca Three Heads: A Three Heads vem se consolidando no mercado de motopeças como uma marca moderna e confiável. Seus aros de alumínio são fabricados com padrão de excelência, combinando durabilidade, leveza e acabamento de alto nível, perfeitos para quem valoriza estética e performance. Benefícios para você nosso cliente: - Aros em alumínio 6063 - alta durabilidade e resistência com leveza - Visual esportivo com aros pretos personalizados - Qualidade premium Three heads. Garantia de 3 Meses Contra Defeito de Fabricação', 469.9, 422.91, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/sg-11134201-81zuv-mmkfirq3vbpf36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F652972169%2F58208131212', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209450930', 'Atum Ralado em Óleo Gomes da Costa', 'O Atum Ralado Gomes da Costa é a escolha perfeita para quem busca praticidade e sabor na cozinha. Já vem ralado, pronto para ser utilizado em diversas receitas, como patês, sanduíches, saladas e omeletes. Rico em ômega 3 e fonte de proteínas, o Atum Ralado Gomes da Costa é uma opção saudável e versátil para o seu dia a dia. Após aberto, retire o produto da lata e conserve em embalagem fechada, sob refrigeração.', 10.99, 10.99, NULL, 'Food & Beverages > Food Staples > Canned Food', 'https://cf.shopee.com.br/file/sg-11134201-825b1-mqnel4hut4we92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302938%2F58209450930', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259458419', 'Água Sanitária Super Cândida', 'Super Cândida é a água sanitária ideal para a limpeza e desinfecção da sua casa, eliminando germes e bactérias. * Alvejamento de roupas: adicione 1 copo (200ml) para cada 20 litros de água, deixando de molho por 30 minutos. * Limpeza geral: adicione 1 copo (200ml) para cada 5 litros de água em banheiros, cozinhas, pisos, pias, azulejos e paredes. Enxágue após 10 minutos. * Desinfecção de frutas, verduras e legumes: misture 1 colher de sopa (15ml) em 1 litro de água. Deixe de molho por 10 minutos e enxágue. * Combate a larva do mosquito Aedes Aegypti: misture 2ml em 1 litro de água e despeje nos locais que reservam água parada.', 7.99, 7.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-825a4-mqnem3p80f0h6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554958%2F58259458419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
