INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997446589', 'Coti Massa Tutti Frutti Kit Festa - Cotiplás', 'Coti Massa Tutti Frutti Kit Festa - Cotiplás Divirta-se criando incríveis esculturas com a Coti Massa Tutti Frutti Kit Festa da Cotiplás! A Coti Massa Tutti Frutti Kit Festa é perfeita para estimular a criatividade e coordenação motora das crianças. Com essa massa de modelar, as possibilidades são infinitas: podem criar frutas, animais, personagens e tudo mais que a imaginação permitir. Além disso, a textura macia e maleável da massa torna a modelagem mais fácil e prazerosa. Idade recomendada: A partir de 3 anos. Selo Inmetro: CE-BRI/IQB 0228 IQB-OCP 010. Diferenciais: Conteúdo do Kit: massa de modelar Tutti Frutti em diversas cores vibrantes. Ideal para festinhas e momentos de diversão em família. Produto atóxico e seguro para crianças. Marca renomada e de confiança no mercado de brinquedos infantis. Mais sobre o Produto: Estimula a criatividade. Desenvolve a coordenação motora. Possibilita a criação de diversas formas e figuras. Produto seguro e atóxico, ideal para crianças. Dicas de Uso: Separe as massas por cores. Utilize ferramentas de modelagem para criar detalhes nas esculturas. Guarde a massa sempre bem fechada após o uso para manter a textura. Ficha técnica: Marca: Cotiplás; Nome do produto: Coti Massa Tutti Frutti Kit Festa; Idade recomendada: A partir de 3 anos; Selo Inmetro: CE-BRI/IQB 0228 IQB-OCP 010; Contém: 5 potinhos de massa de modelar em diferentes cores.', 28.99, 28.99, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7rcct-ltv6bdij9sfw8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F23997446589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198377354', 'Baby Alive Festa de Aniversário Berry Boo - Hasbro', 'Baby Alive Festa de Aniversário Berry Boo - HasbroDivirta-se com a Boneca Baby Alive na Festa de Aniversário Berry Boo! Com a Baby Alive Festa de Aniversário Berry Boo da Hasbro, sua criança poderá entrar no mundo da imaginação e celebrar festinhas sem fim! Esta boneca incrível vem equipada com acessórios para a festa, como um chapéu de aniversário e um cupcake fake, para que os pequenos possam fingir soprar a velinha. Além disso, ao dar água para a boneca beber na mamadeira, ela vai molhar a fralda, proporcionando uma experiência interativa e realista. Diferenciais:Estimula a criatividade e a imaginação das crianças. Proporciona momentos de diversão e interação. Acessórios para festa incluídos: chapéu de festa e cupcake fake. Boneca que molha a fralda ao beber água na mamadeira. Mais sobre o Produto:O Baby Alive Festa de Aniversário Berry Boo - Hasbro é ideal para crianças a partir de 3 anos que adoram brincar de faz de conta e organizar festinhas. Com esse brinquedo, os pequenos podem criar diferentes momentos de celebração e desenvolver habilidades sociais de forma lúdica e divertida. Dicas de Uso:Para uma experiência completa e divertida, estimule a criatividade da criança ao encenar festas de aniversário com a Boneca Baby Alive. Deixe-a escolher os convidados, preparar os quitutes de mentirinha e cantar os parabéns! Ficha Técnica:Marca: Hasbro Selo Inmetro: 002515/2021', 240.99, 240.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7reqb-m8c2hhiov09h5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F23198377354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
