INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599388261', 'Blocos de Montar 110 Peças Blocolândia - Dismat', 'Blocos de Montar 110 Peças Blocolândia - Dismat Libere a criatividade dos seus pequenos com o MK381 Blocos de Montar Infantil Educativo 110 Peças da linha Blocolândia da Dismat. Este conjunto vibrante e colorido é perfeito para crianças que amam explorar novas formas e ideias. As 110 peças foram projetadas para serem facilmente manuseadas por mãos pequenas, com encaixes simples que são ideais para o desenvolvimento da coordenação motora e do raciocínio lógico. Os blocos permitem que as crianças se expressem criativamente enquanto constroem tudo, desde simples figuras até estruturas complexas. Este brinquedo não é apenas uma fonte de diversão, mas uma ferramenta educativa que promove a inteligência e a imaginação das crianças. O uso de material de alta qualidade assegura que os blocos podem suportar o uso intensivo por crianças energéticas, fazendo deste conjunto uma excelente adição à sala de jogos de qualquer criança. Idade recomendada: A partir de 18 meses. Selo Inmetro: Isento', 129.99, 129.99, NULL, 'Mom & Baby > Toys > Block Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdvo-m0amfk1jiu8l52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F18599388261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
