INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22591415383', 'Martelo Bola Com Cabo de Fibra 450g (706163) - Onsite', 'O Martelo Bola Com Cabo de Fibra 450g (706163) - Onsite, é a ferramenta perfeita para qualquer trabalho que exija força e precisão; Este martelo é ideal para tarefas de construção, reparação e manutenção. Sua cabeça de bola permite uma distribuição uniforme da força, evitando danos indesejado, mas ainda assim resistente o bastante para suportar o uso diário. O cabo em fibra de vidro proporciona uma aderência firme e confortável, reduzindo a fadiga durante o trabalho. Características: - Tipo de martelo: Bola. - Possui cabo em Fibra de Vidro. - Tamanho: 450g. - Modelo: Martelo bola Com Cabo em Fibra de Vidro. Código: 706163. Marca: Onsite. Tamanho: 450g (16 oz). Material do Cabo: Fibra de Vidro. Ean: 6942629201977.', 38.55, 38.55, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvd4-lhndx0ytm3t9b2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22591415383', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697678779', 'Defletor de Ar Esmerilhadeira e Lixadeira (F000604017) Bosch', 'O Defletor (F000604017) - Bosch é um componente projetado para desempenhar um papel crucial no controle do fluxo de ar e detritos. Construído com materiais resistentes, o defletor é projetado para suportar as condições adversas do ambiente de trabalho, proporcionando durabilidade e desempenho confiável. • Voltagem: 127v/220v • Dimensões: 5x10x10 cm • Quantidade: 1 unidade • Modelos compatíveis: GWS 22 U - GWS 22-180 - GWS 22-230 - GWS 24-180 - GWS 24-230 - GWS 26-230 - GWS 26-180 Referência: F000604017 Marca: - Bosch O Defletor (F000604017) - Bosch é um componente projetado para desempenhar um papel crucial no controle do fluxo de ar e detritos. Construído com materiais resistentes, o defletor é projetado para suportar as condições adversas do ambiente de trabalho, proporcionando durabilidade e desempenho confiável.', 18.99, 18.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd57-lv99bk7pje5610', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F19697678779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10118618211', 'Roupão de Microfibra Plush Aveludado Adulto Toque Macio Grosso Masculino e Feminino TAMANHO UNICO', 'O Roupão de Banho é uma peça essencial para tornar o nosso dia a dia ainda mais prático, ele vai aquecer você em dias mais frios. Pensando no seu bem estar, trazemos para você o Roupão em Plush. Confeccionado em tecido 100% poliéster, o roupão é super macio e com um toque bem aconchegante, além disso suas mangas são longas. São várias cores que vão das mais vivas até as mais neutras. Modelo em Kimono. Fique aquecido e à vontade no aconchego da sua casa com o Roupão de Banho em Plush. Ótima opção para presentear! INFORMAÇÕES ADICIONAIS: Roupão Microfibra Tamanho Único Medidas Aproximadas: Gramatura do tecido: 200 g/m² Busto: 60cm Comprimento da Manga: 40CM Comprimento das Costas: 1M Composição: 100% Poliéster Tags: Roupao, roupao de microfibra, roupao de banho, roupao aveludado, roupao cores, roupa de banho, enxoval, promocao, oferta, oferta em roupa de banho, oferta em roupao de banho, oferta em jogo de banho, promocao em roupao,', 84.9, 49.9, NULL, 'Home & Living > Bathrooms > Towels & Bathrobes', 'https://cf.shopee.com.br/file/br-11134207-81ztz-mknorazym8sge0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356841149%2F10118618211', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693490466', 'Colher de Pedreiro 7'''' (390,0001) - Noll', 'A Colher de Pedreiro 7'''' (390,0001) - Noll, é uma ferramenta manual utilizada principalmente na área da construção civil, especialmente por pedreiros e profissionais da alvenaria. Consiste em uma lâmina metálica estreita e plana, com uma extremidade em formato de ponta e a outra em formato de colher. A extremidade pontiaguda é utilizada para cortar, raspar ou picar materiais como argamassa, cimento e gesso, enquanto a extremidade parecida com uma colher é utilizada para espalhar esses materiais sobre superfícies como tijolos, blocos ou paredes. A colher de pedreiro é uma ferramenta versátil e essencial em muitos projetos de construção, permitindo um trabalho preciso e eficiente na manipulação de materiais na área da alvenaria. Descrição do Produto: • Fabricada com Uma base reta e plana em Aço. • Material do Cabo: Madeira. • Bitola: 7''''. • Indicada para uso na construção civil. Referência: 390,0001. Cód. de Fábrica: 390,0001. Marca: Noll.', 16.3, 16.3, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdhf9i8o20mxcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22693490466', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204154046', 'Chinelo Piccadilly EVA Marshmallow C224 Nude Claro - Feminino', 'Conforto leve e seguro para todos os momentos do seu dia! Chinelo Piccadilly EVA Marshmallow C224 Nude Claro - Feminino Parte superior do formulário Ficha Técnica: Marca: Piccadilly Gênero: Feminino Cor: Nude claro Material: EVA 100% reciclável Indicação: Dia a dia, home office e momentos de descanso Palmilha: Anatômica e macia com absorção de impacto Solado: Antiderrapante, flexível e com alta durabilidade Detalhes específicos: Controle de umidade e temperatura, ultraleve, seguro para uso interno ou externo; logotipo da marca na palmilha Cansada de calçados que incomodam ou escorregam nos momentos em que você mais precisa de descanso e segurança? O Chinelo Piccadilly Marshmallow C224 é a solução perfeita! Por que investir? Feito em EVA reciclável, ele é ultraleve, flexível e possui absorção de impacto para maior conforto. O solado antiderrapante garante segurança e estabilidade em cada passo, dentro ou fora de casa. Ideal para o dia a dia, momentos de autocuidado ou para quem passa muitas horas em pé. Seu design moderno e funcional completa a experiência. Conteúdo da embalagem: 1 par de Chinelo Piccadilly EVA Marshmallow C224 Nude Claro - FemininoParte superior do formulário', 99.99, 56.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-8261p-mjzvmq5x1af73a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1614877278%2F58204154046', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262845058', 'Tênis Fila Comet Preto Rose e Cinza - Feminino', 'Mais estilo, mais impulso, mais conforto nos seus treinos! Tênis Fila Comet Preto Rose e Cinza - Feminino Parte superior do formulário Ficha Técnica: Marca: Fila Cor: Preto com detalhes em rose e cinza Gênero: Feminino Indicado: Corrida, treinos e caminhadas Nível de Corrida: Iniciantes e Intermediários – 5 a 10km Cabedal: Mesh respirável com reforços sintéticos aplicados Palmilha: Têxtil Sola: EVA com ponteiras em TPU Fechamento: Cadarço personalizado Amortecimento: Macio com entressola em EVA Estabilidade: Neutro Tecnologias: Entressola em EVA para amortecimento suave e ponteiras em TPU para maior aderência e tração Drop: Não informado Entressola: EVA de alta absorção de impacto Detalhes: Puxador traseiro, grafismos geométricos e design maximalista Ideal para quem está em movimento constante, o Fila Comet une performance e estilo com máxima leveza. Porque investir: A combinação do cabedal respirável com a entressola em EVA oferece conforto prolongado e maciez para corridas de até 10 km. O solado com ponteiras em TPU garante estabilidade e aderência em qualquer ritmo. Seu design moderno em preto com rose traz elegância para o treino e para o dia a dia. Conteúdo da embalagem: 1 par de Tênis Fila Comet Preto Rose e Cinza - FemininoParte superior do formulário Parte superior do formulário Parte superior do formulário Parte superior do formulário Parte superior do formulário Parte superior do formulário', 399.99, 252.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824gq-mpnsdz7di6177d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1614877278%2F58262845058', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
