INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494398493', 'Aspirador Vertical Electrolux Com Fio Stk15 127V Urban Grey', 'Aspirador Vertical 2 em 1 Electrolux STK15 - Limpeza Poderosa e Prática! Transforme suas tarefas de limpeza com o Aspirador de Pó Electrolux STK15. Com potência de 1300W, este aspirador combina a função de um aparelho vertical para pisos e a versatilidade de um dispositivo de mão, perfeito para estofados e cantos. Seu filtro HEPA Allergy Protect devolve um ar mais puro ao ambiente, sendo ideal para lares com pessoas alérgicas. Versatilidade 2 em 1: Utilize em modo vertical para limpeza rápida de pisos e desacople a unidade de mão para alcançar áreas menores, como sofás e carros. Alto Poder de Sucção: Com 1300W de potência, remove sujeira de forma eficiente. O bocal com tecnologia 180° Easy Steer facilita a limpeza ao redor de móveis. Filtro HEPA Allergy Protect: Retém até 99,9% de ácaros, fungos e bactérias, purificando o ar durante a limpeza. Praticidade no Uso: O cabo de 6 metros proporciona grande autonomia e o reservatório de 1,6L é de fácil esvaziamento. O design permite armazenamento vertical em qualquer lugar.', 299.0, 149.0, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-824i3-mptch5j78a2qc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1509845472%2F22494398493', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
