INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593257926', 'Caixa C/6 Fita Isolante 3m 33+ Scotch 19mmx5m Alta Temperatura', 'Fita Isolante Profissional Scotch 3M 33+ de alta qualidade, protege a sua instalação elétrica com proteção Classe A e certificada a 105 graus. A marca 3M é mundialmente conhecida por seus padrões de qualidade e passa pelos mais rígidos padrões de qualidade para oferecer a você o melhor produto e a melhor proteção para o seu investimento. Aplicação: Utilizada para isolação de fios e cabos em instalações elétricas de baixa tensão (até 750V) e também como cobertura final em emendas e terminações. Instruções de uso:Na aplicação, estique a fita e garanta a sobreposição de 50% entre camadas para assegurar isolamento elétrico adequado. Em caso de vibrações, aplique uma camada extra de fita para obter melhor proteção contra abrasão e choques mecânicos.', 141.47, 99.03, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rdvg-lzt1qlu8p74yf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F23593257926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
