INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198946573', 'Piscina Inflável Retangular 200x150x50cm 747L', 'Piscina Inflável Retangular 200x150x50cm 747L Sunclub Curta o verão com a Piscina Inflável Retangular 200x150x50cm 747L da Sunclub. Feita para garantir lazer em família, ela une praticidade, resistência e um design que se adapta a quintais, varandas e áreas externas. Fácil de montar, desmontar e armazenar, você enche, usa e guarda sem complicações. Ideal para se refrescar nos dias quentes, com espaço para adultos e crianças*. Atenção: Nunca deixe crianças sem supervisão de um adulto responsável. Benefícios do produto Montagem rápida: encha, nivele e aproveite em poucos minutos. Fácil de limpar: superfície lisa e resistente, manutenção simples. Conforto e segurança: bordas infláveis macias e altura de 50 cm. Versatilidade de uso: perfeita para quintal, churrasco, festas e férias. Custo-benefício: diversão de piscina sem obras nem altos gastos. Design retangular otimiza espaço e circulação dentro da piscina. Desafios do produto / Soluções “A água suja rápido.”', 160.0, 160.0, NULL, 'Home & Living > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gr-mf9vsnbe6m88c6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F23198946573', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
