INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797383490', 'Cartão de Memória Micro Sd Sandisk 512gb MicroSd 200Mbs+Adp', 'Sandisk Cartão de Memória Micro Sd 512gb e Adaptador MicroSd Extreme Pro Velocidade de Leitura de Até 200Mbs Certificação A2 Classe Velocidad de Vídeo V30 Foto e Vídeo 4k Full HD Barramento Uhs-I U3 Projetado para durar, proteger dados e expandir a capacidade de armazenamento do seu dispositivo, o Micro sdxc Extreme Pro da Sandisk permite que você salve arquivos de maneira simples, segura, eficaz, otimize o espaço e minimize o seu tempo de espera; Para isso, conta com velocidade de leitura de dados de até 200Mbs, o que permite a transferência de dados de forma rápida e segura para economizar seu tempo, conta com velocidade de escrita de até 140 Mbs para uma performance de alto desempenho; bem como permite que você salve seus vídeos com resolução máxima graças a sua tecnologia avançada, possibilitando vídeos resolução 4k Ultra HD para captura de imagens, além de certificação A2 para melhor desempenho na execução de aplicativos; Marca: Sandisk Cor produto: Preto Vermelho Nome do modelo: Micro Sd Extreme Pro Certificação A2 para execução de aplicativo Velocidade de leitura sequencial: até 200Mbs Classificação de velocidade de vídeo: V30 Referência: SDSQXCD-512G-GN6MA Dimensões: 15,3 x 10,2 x 1,0 cm Peso: 0,012 Itens inclusos 1x Cartão Micro Sdxc 512gb 1x Adaptador Micro Sd para Sd Garantia: 90 dias', 1879.9, 1879.9, NULL, 'Mobile & Gadgets > Accessories > Memory Cards', 'https://cf.shopee.com.br/file/br-11134201-7r98o-maehosbc3rm79f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163364765%2F22797383490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
