INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899597823', 'Refil p/ Filtro de Piscina - 3600L por hora MOR 001499', 'Esse Refil é compatível para filtros Mor dos códigos 001513 e 001514.Garanta uma piscina com água limpa e de qualidade utilizando o Refil para Filtro da Mor. Ele é compatível com filtros de vazão 3.600 litros por hora, sendo perfeito para a manutenção e o bom funcionamento do filtro da sua piscina. A recomendação é que seu refil seja trocado a cada três meses quando usado constantemente. Quando o filtro estiver sujo, basta lavá-lo com pressão da água de uma mangueira que ele estará pronto para ser reutilizado. Características: - Marca: Mor - Modelo: 001499 Imagens meramente ilustrativas Ficha Técnica: Material: Polipropileno Altura: 19,00 Centímetros Largura: 10,50 Centímetros Comprimento: 10,50 Centímetros Peso: 102,00 Gramas Conteúdo da Embalagem: - 1x Refil p/ Filtro de Piscina - 3600L por hora MOR', 45.39, 40.85, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-7rbkz-m5lxbkg74r9z1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F21899597823', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
