INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193256390', 'Reinforce - 60 Cápsulas', 'Equaliv Reinforce é um suplemento vitamínico com minerais quelatos e alto conteúdo de biotina e ácido pantotênico, que auxilia no fortalecimento dos cabelos e unhas.Equaliv Reinforce contém minerais quelatos. A característica quelato confere ao mineral uma configuração neutra e bem melhor para absorção. Resultado? Minerais com melhor biodisponibilidade. Reinforce ainda conta com 100% do IDR (Índice Diário Recomendado) de vitaminas A, C, E, complexo B, zinco, magnésio, ferro e biotina. Modo de uso: Consumir 1 (uma) cápsula ao dia. USO ADULTO. Contém 60 cápsulas. Ingredientes: Óleo de soja (Glycine maxL.Merr), óxido de magnésio, bisglicinato de magnésio, ascorbato de cálcio, nicotinamida, acetato de racealfatocoferol, bisglicinato de zinco, ferro carbonila, D-pantotenato de cálcio, bisglicinato ferroso, palmitato de retinol, cloridrato de piridoxina, tiamina mononitrato, riboflavina, ácido fólico, D- biotina, cianocobalamina, (acidulante) ácido cítrico, (emulsificante) lecitina de soja e (antiumectante) dióxido de silício. Cápsula: água purificada, (gelificante) gelatina, (umectante) glicerol, (glaceante) cera de abelha e (corantes) óxido de ferro preto e óxido de ferro vermelho. “NÃO CONTÉM GLÚTEN.” “ALÉRGICOS CONTÉM DERIVADOS DE SOJA E AMENDOIM E PODE CONTER DERIVADOS DE PEIXE.”', 139.9, 139.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rfgs-m9zw3pr36dg1e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F994595343%2F22193256390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
