INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41260191920', 'Livro Cartonado Aprendendo a Lição', 'Pablo é um hipopótamo que gosta de contar vantagem sobre coisas que ele não sabe. Só que, às vezes, isso pode colocá-lo em perigo. Embarque nesta história para saber o que Pablo aprontou._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Ciranda Cultural _x000D_ Idioma: Português_x000D_ Páginas: 10_x000D_ Dimensões: L 20.00 x A 20.00 x E 1.00_x000D_ ISBN: 9786526116555_x000D_ Coleção: Livro com patinhas_x000D_ Linha Editorial: Ciranda Cultural - Trade_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Amizade, Diversão, Aprendizado, Vaidade, Orgulho_x000D_ BISAC: Literatura Infantil / Literatura Infantil / Temas Sociais / Emoções e Sentimentos_x000D_ Linha de Produto: Cartonado_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Laminação fosca_x000D_ Material: Cartonado', 29.9, 29.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdws-mcl3lyknfy9se3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F41260191920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
