INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42427127906', 'Farol Milha Hb20 Hb20S 2012 2013 2014 2015', 'Código do produto: 9144 O farol de milha é uma peça essencial para visibilidade em vias noturnas ou em dias de neblina. Eles devem estar sempre em bom estado para maior segurança do motorista e seus ocupantes. Este item possui material de alta qualidade e resistência, composto com sua lente em vidro que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Hyundai - Hb20 2012 - Hb20s 2012 - Hb20 2013 - Hb20s 2013 - Hb20 2014 - Hb20s 2014 - Hb20 2015 - Hb20s 2015 Especificações Técnicas: - Lente Lisa - Material da Lente em Vidro - Material da Carcaça em Plástico - Encaixe de lâmpada H8 ATENÇÃO Garantia - 3 Meses O valor anunciado referente a Unidade. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 95.9, 95.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-822zd-mi2mwjh6tr0j73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F42427127906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
