INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250712893', 'CHAVE EM L PARA SOQUETE, 300/75 MM, ENCAIXE 1/2, CROMO VANADIO, CROMO FOSCO // DENZEL', 'Chave em Formato L Denzel (Alto Torque) Ferramenta profissional de alta resistência, ideal para aplicações que demandam alto torque e alavancagem, com design otimizado para acesso a pontos de fixação complexos. Especificações Técnicas e Vantagens: Design e Ergonometria: Formato em "L" para máxima aplicação de força (alavancagem) e facilidade de operação em áreas restritas. Composição/Material: Construída em Aço Cromo-Vanádio (CrV), garantindo robustez e durabilidade superiores. Acabamento/Proteção: Acabamento em cromo fosco para proteção eficaz contra corrosão e resistência ao desgaste em ambientes de trabalho rigorosos. Conexão/Encaixe: Encaixe quadrado de 1/2 polegada, proporcionando compatibilidade universal com soquetes e acessórios de alto torque. Dimensões: Dimensões de 300 mm x 75 mm, oferecendo uma alavanca estendida para facilitar o afrouxamento e aperto de fixadores mais resistentes.', 43.95, 43.95, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821fk-mh7s07ok0weg85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F58250712893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22917828498', 'Vnox Brinco De Tarraxa De Morango Arco-Íris , 14K Banhado A Ouro Hipoalergênico Para Meninas Pequeno De Sonho', 'Aço inoxidável de alta qualidade Estilo da TRENDY Cor da Caixa: Dourado Tamanho: 8MM*7MM Presente de presente para: Amigos, amantes, família.Dia dos Namorados. Aniversário de aniversário de aniversário Ocasião: Desgaste diário/Festa/Presente/Engajamento/Aniversário/Casamento Padrão ambiental padrão: chumbo, níquel, sem cádmio Encomenda em massa/encomenda em massa: Sim Dropshipping Global disponível: Sem logotipo, sem recibo, sem anúncios Manutenção de joias: Evite produtos químicos/evite suor/evite queimaduras/ limpe com pano macio/economize bem/desgaste de sustitutos', 30.5, 15.25, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/sg-11134201-23010-3mpsuzj6h7lve5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F239158067%2F22917828498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493840515', 'A SUTIL ARTE DE LIGAR O F*DA SE UMA ESTRATÉGIA INUSITADA PARA UMA VIDA MELHOR', 'A SUTIL ARTE DE LIGAR O F*DA SE UMA ESTRATÉGIA INUSITADA PARA UMA VIDA MELHOR Chega de tentar buscar um sucesso que só existe na sua cabeça. Chega de se torturar para pensar positivo enquanto sua vida vai ladeira abaixo. Chega de se sentir inferior por não ver o lado bom de estar no fundo do poço.Coaching, autoajuda, desenvolvimento pessoal, mentalização positiva sem querer desprezar o valor de nada disso, a grande verdade é que às vezes nos sentimos quase sufocados diante da pressão infinita por parecermos otimistas o tempo todo. É um pecado social se deixar abater quando as coisas não vão bem. Ninguém pode fracassar simplesmente, sem aprender nada com isso. Não dá mais. É insuportável. E é aí que entra a revolucionária e sutil arte de ligar o foda se.Mark Manson usa toda a sua sagacidade de escritor e seu olhar crítico para propor um novo caminho rumo a uma vida melhor, mais coerente com a realidade e consciente dos nossos limites. E ele faz isso da melhor maneira. Como um verdadeiro amigo, Mark se senta ao seu lado e diz, olhando nos seus olhos você não é tão especial. Ele conta umas piadas aqui, dá uns exemplos inusitados ali, joga umas verdades na sua cara e pronto, você já se sente muito mais alerta e capaz de enfrentar esse mundo cão.Para os céticos e os descrentes, mas também para os amantes do gênero, enfim uma abordagem franca e inteligente que vai ajudar você a descobrir o que é realmente importante na sua vida, e fda se o resto. Livre se agora da felicidade maquiada e superficial e abrace esta arte verdadeiramente transformadora.. Informações Adicionais Autor: MANSON, MARK Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: A SUTIL ARTE DE LIGAR O F*DA SE UMA ESTRATÉGIA INUSITADA PARA UMA VIDA MELHOR Idioma: PORTUGUES Páginas: 224 Edição: 1 ISBN-13: 9788551002490 ISBN-10: 855100249X', 59.9, 59.9, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/sg-11134201-7rd5p-lx2zi1jqns22d5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23493840515', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998370911', 'FOFURAS PARA RELAXAR – LIVRO DE COLORIR FLUFFY TIMES – LIVRO 3', 'FOFURAS PARA RELAXAR – LIVRO DE COLORIR FLUFFY TIMES – LIVRO 3 Mergulhe no mundo mágico dos livros de colorir da coleção Fluffy Times, uma celebração dos momentos de conforto do dia a dia.Você vai encontrar fofuras reconfortantes como um tapa olhos de gatinho, uma lareira superagradável e um dia de outono pela janela, tudo sempre com muitos detalhes delicados e uma atmosfera repleta de ternura.Cada cena foi pensada para transmitir um forte senso de comunidade, alegria e aconchego, e são ideais para você relaxar, apreciar a beleza que existe nas pequenas coisas e se deleitar com os prazeres mais simples.Para que sua experiência seja ainda mais reconfortante, este livro inclui folha de acetato para proteger as páginas 40 ilustrações originais com verso em branco (não se esqueça de colocar o acetato por baixo!) gabarito para testar cores e texturas gramatura adequada para evitar manchas de tinta no verso e danos ao papel. Informações Adicionais Autor: PLUMS, DIDI Data Publicação: 03/05/2025 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: FOFURAS PARA RELAXAR – LIVRO DE COLORIR FLUFFY TIMES – LIVRO 3 Idioma: INDEFINIDO Páginas: 84 Edição: 1 ISBN-13: 9788543110516 ISBN-10: 8543110513', 49.9, 49.9, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7reo3-m8alighe868n22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23998370911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
