INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299195208', 'BROCA PARA MADEIRA AJUSTAVEL 30-120MM, 1PC // MTX', 'Broca Ajustável para Madeira MTX 704979 – Diâmetro de 30 a 120 mm A Broca Ajustável MTX 704979, também conhecida como "Balerina", é uma solução prática e inteligente para quem precisa realizar furos em madeira com diferentes diâmetros utilizando uma única ferramenta. Ideal para profissionais da marcenaria, montagem de móveis e também para uso doméstico, ela alia versatilidade, precisão e robustez em um único produto. Principais Vantagens: Durabilidade superior com aço 45 Fabricada em aço de alta resistência, a broca oferece excelente durabilidade mesmo sob uso frequente e intenso em madeira, MDF e aglomerado. Pastilhas de metal duro VK8 As lâminas de corte com pastilhas em VK8 garantem alta resistência ao desgaste e cortes limpos, com excelente acabamento e menor necessidade de reposição. Ajuste de diâmetro rápido e preciso Com a chave hexagonal inclusa, é possível ajustar o diâmetro da broca entre 30 e 120 mm com facilidade, tornando o processo mais prático e eliminando a necessidade de múltiplas brocas. Perfuração centrada com broca guia A broca central mantém a estabilidade durante a operação, garantindo furos bem alinhados, sem desvios, mesmo em peças grandes ou materiais delicados. Conteúdo do kit: Broca ajustável com haste cilíndrica Chave hexagonal para regulagem Broca guia central Aplicações recomendadas: Perfuração em madeira, MDF e aglomerado Instalação de fechaduras, tomadas ou dutos Montagem de móveis sob medida Trabalhos de marcenaria e carpintaria Diâmetro ajustável: de 30 mm a 120 mm', 37.26, 37.26, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821ge-mgxol6mpc0so59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F22299195208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
