INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594539807', 'Fogão Brastemp 5 Bocas Cor Branca com Botões Removíveis e Exclusivo Aro Protetor - BFS5NDB', 'Esse fogão Brastemp 5 bocas é ideal para quem busca segurança e praticidade. Com botões removíveis, a limpeza se torna simples e rápida. O exclusivo aro protetor evita que panelas deslizem durante o preparo, garantindo maior estabilidade e segurança. As cinco bocas permitem cozinhar múltiplos pratos simultaneamente, atendendo bem famílias grandes ou quem gosta de receber convidados. O design moderno e funcional transforma a cozinha em um espaço eficiente, confortável e elegante, valorizando tanto a estética quanto a praticidade do dia a dia.', 1919.0, 1919.0, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gq-mpwcw1265gcs31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1648122739%2F23594539807', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
