INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599565395', 'Kit 2 Creme Dental Sensodyne Sensibilidade & Esmalte Branqueador 100g', 'O Creme Dental Sensodyne Sensibilidade & Esmalte Branqueador foi desenvolvido para quem busca uma solução eficaz e de uso diário para o fortalecimento do esmalte dentário e alívio da sensibilidade. Clinicamente comprovado, este creme dental ajuda a proteger os dentes contra os desgastes ácidos, tornando-os 3x mais resistentes à erosão ácida, além de proporcionar um sorriso naturalmente mais branco. Recomendado por dentistas, sua fórmula avançada atua suavemente sobre o esmalte dos dentes, promovendo proteção contínua contra a sensibilidade enquanto restaura a força dos dentes. Ideal para quem deseja proteção completa com ação branqueadora.', 52.38, 52.38, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-823qu-moobzt5wwi6a6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21599565395', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20199245437', 'Kit 1 Protetor Solar Episol Sec OC FPS 60 60ml', 'Protetor Solar Episol Sec OC FPS 60 Episol Sec OC é uma linha de protetor solar indicada para pele oleosa. Devido a sua tecnologia Skin Self Control com ativos que agem diretamente na glândula sebácea. Episol Sec OC controla a oleosidade da pele por 12h, reduz os poros e proporciona sensação de pele limpa com toque seco e efeito matificante. Oferece alta proteção contra dos danos solares causados pelos raios UVA/UVB e Infravermelho A. Tecnologia Skin Self Control: Nova geração em fotoproteção para pele oleosa (glicoesferas de sílica précarregadas com os ativos Miniporyl e Nelupure) 12h de controle da oleosidade e brilho facial Reduz o tamanho e número de poros (ação adstringente) Alta proteção UVA/UVB e Infravermelho A Previne o envelhecimento precoce Toque seco e Efeito Matte Sensação de pele limpa Preserva o colágeno Disponível nos FPS30, FPS60 e FPS99 Não obstrui os poros Textura agradável de rápida absorção e fácil espalhabilidade Uso diário Muito resistente à água.', 161.88, 161.88, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-82599-mqrkf7k4sruq06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F20199245437', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697579831', 'Kit 2 Esmalte Dailus Color Cor Petit Four com 8ml', 'ESMALTE DAILUS COLOR COR PETIT FOUR Em um design exclusivo, sua tampa anatômica possui um pincel flat big blush, desenvolvido com cerdas mais cheias, proporcionando uniformidade na aplicação e resultado surpreendente. Modo de usar: Agite antes de usar. Aplicar sobre as unhas com auxílio do pincel. Precauções: Uso externo. Manter fora do alcance de crianças e fonte de calor e fogo. Usar somente em adultos. Não aplicar sobre a pele lesionada ou infeccionada. Em caso de irritação, retirar o esmalte e procurar o auxílio médico', 17.98, 17.98, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-8258b-mqmd6q5s4avj76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23697579831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
