INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398240642', 'Kit 2 Nutren Senior Complemento Alimentar Sem Sabor Zero Lactose 740g', 'Nutren Senior Sem Sabor Zero Lactose 740g Composto lácteo com cálcio, proteínas, vitamina D e outros nutrientes essenciais. Zero lactose. Benefícios: Como parte de dieta ou para complementação da nutrição diária. Auxilia na manutenção das funções do tecido ósseo e do músculo esquelético. Para dietas com restrição de lactose. Indicação: Para dietas com restrição de lactose. Para adultos a partir de 50 anos. NÃO CONTÉM GLÚTEN. ALÉRGICOS: CONTÉM LEITE E DERIVADOS E DERIVADOS DE SOJA. Ingredientes: Leite integral, concentrado proteico de soro de leite, maltodextrina, minerais (citrato de cálcio, sais de magnésio do ácido cítrico, pirofosfato férrico, sulfato de zinco, sulfato de manganês, sulfato de cobre e selenato de sódio), proteína de soja isolada, polidextrose, caseinato de cálcio, colágeno hidrolisado, enzima lactase, vitaminas (L-ascorbato de sódio, acetato de DL-alfa tocoferila, nicotinamida, D-pantotenato de cálcio, cloridrato de piridoxina, tiamina mononitrato, acetato de retinila, riboflavina, ácido N-pteroil-L-glutâmico, fitomenadiona, colecalciferol, D biotina e cianocobalamina), reguladores de acidez citrato de potássio, hidróxido de potássio e ácido cítrico e emulsificante lecitina. Modo de Uso: Sugestão de Consumo: 3 colheres de sopa rasas (27,5g) 2x ao dia de Nutren Senior Sem Sabor em Pó Zero Lactose equivalem a 6 colheres diárias (55g). Modo de Conservação: Manter a lata sempre bem fechada em local fresco, seco e inodoro. Iniciado o uso do produto, recomenda-se o consumo em até 30 dias. Consumir imediatamente após o preparo. Durante o transporte este produto pode se compactar. No entanto, seu volume e conteúdo correspondem ao peso líquido indicado no rótulo. Modo de Preparo: Coloque 3 colheres de sopa rasas (27,5g) em um copo, em seguida, adicione uma pequena quantidade de água à temperatura ambiente (aproximadamente 50ml) e mexa bem até formar uma pasta cremosa, adicione o restante da água (130 ml) e mexa bem até completa dissolução.', 441.98, 441.98, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-823r3-mojpvcu93ojwb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22398240642', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22707626694', 'Kit 2 Tintura Creme Koleston Wella Castanho Claro 50 Kit', 'TINTURA CREME KOLESTON WELLA CASTANHO CLARO 50 Tenha uma nova experiência em coloração usando o novo Koleston! Koleston traz agora o exclusivo tratamento Gloss Intenso Ultra. Cor mais fascinante e brilho revitalizado por 6 semanas. 3razões porque o novo koleston é a coloração perfeita para você! 1)O tratamento pré-coloração com proteína de amêndoas cuida e prepara seus cabelos em somente 1 minuto para que você obtenha uma cor fascinantemente uniforme. 2)A tintura creme Clareadora que, com sua fórmula especial, oferece uma cor fascinante e uma perfeita cobertura dos cabelos brancos. 3)O novo e exclusivo tratamento Gloss Intenso Ultra com proteína de amêndoas vem em quantidade suficiente para 6 aplicações que, utilizadas 1 vez por semana, revitalizam o brilho da cor de seus cabelos por 6 semanas.', 48.38, 48.38, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-823oc-mokc1jmc8d1q44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22707626694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
