INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209236862', 'Bota Bebecê Em Couro Com Ilhós Lateral', 'Realce sua elegância com a bota cano curto em couro Legitimo Bebecê, marcada por detalhe lateral de ilhós com passante que adiciona sofisticação discreta. Forro e palmilha em tecido cacharel com espuma oferecem conforto excepcional para uso prolongado. Bico levemente quadrado e salto bloco médio garantem versatilidade, transitando perfeitamente entre casual e formal. Aposte em estilo atemporal para composições impecáveis no dia a dia. Venda apenas para Pessoas Físicas(CPF), não faturamos para Pessoas Jurídicas(CNPJ).', 389.9, 299.99, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-820m6-mnacoshl5tza35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1543493429%2F58209236862', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199365764', 'EUCERIN AQUAPHOR SPRAY CORPORAL 150ML', 'O Eucerin Aquaphor Spray Corporal Reparação Intensiva auxilia na reparação da pele seca, com ação calmante, reparadora e hidratante. Os 8 ingredientes presentes no Eucerin Aquaphor Reparação Intensiva auxiliam na reparação da pele seca, promovendo hidratação profunda e garantindo uma pele macia e com aspecto saudável o dia todo. Seu formato em spray, promove uma aplicação facilitada e prática para grandes áreas do corpo. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 134.9, 134.9, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-82635-mka3k2cskh6r9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F22199365764', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207004355', 'Kit TRUSS Uso Obrigatório & Night Spa Tratamento (2 Produtos)', 'O Kit TRUSS Uso Obrigatório + Night Spa oferece uma poderosa combinação para transformar seus cabelos durante o dia e a noite. Enquanto o Spray Uso Obrigatório atua como um tratamento instantâneo, desembaraçando, protegendo e proporcionando brilho imediato, o Sérum Noturno Night Spa age profundamente durante o sono, nutrindo, hidratando e reparando os fios. O resultado? Cabelos profundamente reconstruídos, nutridos, livres do frizz e com um brilho radiante. Contém: 1 Spray Uso Obrigatório; 260ml 1 Night Spa - Sérum de Tratamento Noturno 250ml SPRAY USO OBRIGATÓRIO:Um verdadeiro aliado para seus cabelos, proporcionando múltiplos benefícios em um único produto. Sua fórmula inovadora desembaraça instantaneamente, reconstrói a fibra capilar, oferece proteção térmica contra secadores e chapinhas, controla o frizz e promove brilho intenso, tudo isso sem pesar nos fios. Ideal para usar como leave-in ou como “máscara líquida” para um tratamento rápido e eficaz. NIGHT SPA:Um tratamento noturno de luxo para todos os tipos de cabelos. Sua fórmula rica em nutrientes e agentes hidratantes penetra profundamente na fibra capilar, proporcionando uma reparação intensa durante a noite. Ao acordar, seus cabelos estarão visivelmente mais macios, sedosos, brilhantes e livres do frizz, revelando todo o seu potencial de beleza. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 319.98, 319.98, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260v-mlw9zz68ldl436', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58207004355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
