INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48600994282', 'Kit de 2 ou 4 Calças Moletom Inverno Menina Infantil Peluciado', '👧 Calça Moletom Infantil Menina – Conforto e Estilo no Dia a Dia 💖 Você pode escolher entre 2 ou 4 calças. 🌸 Confortável, prática e quentinha! Nossa calça de moletom infantil menina é perfeita para os dias mais frios, garantindo liberdade de movimento e muito conforto para a sua pequena. ✨ Detalhes do produto: • Confeccionada em moletom flanelado/peluciado por dentro 🧵 • Cós com elástico que se ajusta perfeitamente à cintura • Punho na barra, deixando o visual moderno e confortável • Tecido macio, leve e super resistente – ideal para brincar, ir à escola ou passear 🎀 Cores e modelos sortidos – envio aleatório conforme disponibilidade, sempre mantendo a mesma qualidade e beleza. 🧺 Fácil de lavar e durável, perfeita para o dia a dia ou para compor conjuntos com blusas e casacos. 📦 Devolução grátis: até 7 dias se não servir 📏 Dica: peça um número maior para melhor ajuste 👧 Ideal para quem busca roupa infantil menina, calça moletom infantil ou roupa de bebê menina com conforto e ótimo custo-benefício. 💬 Dúvidas? Fale com a gente no chat! Garanta já a sua calça de moletom infantil menina e vista sua pequena com conforto e estilo!', 53.9, 32.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Bottoms', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgs1k4vcslj83a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436773535%2F48600994282', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
