INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098021756', 'Case Hd Externo Notebook Sata 2.5 Usb 3.0 Gaveta Hd Slim', 'Protetor bringIT tipo gaveta para HD de 2,5"! Em material Material Alumínio de alta qualidade e resistência ao calor, o Protetor bringIT para HD de 2,5" é perfeito para quem precisa armazenar e transportar dados de um dispositivo à outro de forma fácil, com mobilidade e comodidade. A interface de conexão USB 3.0 garante altas velocidades de transferência de dados. É muito simples de usar, basta conectar o HD de 2,5 polegadas dentro do case e fixar em seu notebook com os parafusos e, em seguida conectar o cabo USB; esses materiais estão inclusos no kit. O kit acompanha: 1 Case para HD 1 Capa Protetora em couro ecológico 4 Parafusos de fixação do Case 1 Chave Philips (2 mm) 1 Cabo USB', 29.75, 26.32, NULL, 'Computers & Accessories > Data Storage > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zvu-mmtbcf3advrcfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097013207%2F21098021756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599008815', 'Darker Preteador Para Pneus Plásticos Borrachas Vintex 1,5l', 'DARKER é um produto desenvolvido para renovar e dar brilho em pneus e borrachas em geral, com aplicação ideal em caminhões. Cria um filme preto, sólido, semi-flexível e de alta resistência, proporcionando longa duração.• Resistente• Longa duração• Filme 100% seco• Não atrai poeira• Fácil aplicação• Seguro para borrachas por ser à base de água**Cuidado! Produto pigmentado. Se entrar em contato com outras superfícies, remover prontamente com água abundante e um pincel de detalhamento externo.#COMO USAR:1. Limpar e secar bem a superfície;2. Agitar bem o produto antes de usar;3. Usar uma trincha ou pincel para aplicar o produto de maneira uniforme no pneu ou borrachas e esperar secar por 30 minutos;4. Para mais brilho, aplicar uma segunda camada após 30 minutos.', 54.48, 54.48, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-824ig-mfmvpauzqjgv66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F23599008815', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494355221', 'Kit 10 Faixas Refletivas Vermelha E Branca Isoflex', '- KIT COM 05 PÇS LD X 05 PÇS LE- UNIVERSAL (APLICÁVEL EM QUALQUER VEÍCULO)- MÁXIMA REFLETIVIDADE- TECNOLOGIA MICROPRISMAS- DURABILIDADE ESTIMADA DE 7 A 10 ANOS- SUPORTA LAVAGENS DE ALTA PRESSÃO- REFLETE MESMO APÓS SOFRER IMPACTO- NÃO DESBOTA- PRODUTO AUTO COLANTE ÓTIMA QUALIDADE - FÁCIL APLICAÇÃO- VISIBILIDADE E SEGURANÇA A UMA DISTÂNCIA SEGURA EM TODOS OS ÂNGULOSDIMENSÕES: 50X300MM (5x30cm)*Atende as especificações do Contran (Resoluções nº 128 / Deliberação nº 30 e nº 316).*O uso das faixas refletivas é obrigatório (Artigo 237 CTB) e a infração é grave, 5 pontos na CNH, multa de R$ 195,23 e veículo retido.Produto novoPreço do anuncio é para o kit 5ld 5 leMercadoria a pronta entregaEnvio em até 24 horas úteisCompra pode ser parceladaProduto de qualidadeCompra garantidaGarantia do vendedor: 3 meses', 35.9, 35.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-824j9-mdw153gatkozbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F22494355221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598785933', 'Escova Cerda Silicone P/ Remover Tirar Pelos Gato Cachorro', 'A Escova Com Cerda De Silicone P/ Remover Tirar Pelos Mandala é a solução ideal para quem busca praticidade e eficiência na remoção de pelos de animais. Com origem no Brasil e fabricada pela renomada marca Vonixx, esta escova apresenta um design inovador que facilita a limpeza de carpetes e estofados, tanto em veículos quanto em residências. Suas cerdas de silicone, com 3 cm de comprimento, garantem uma limpeza profunda, alcançando até os pelos mais difíceis que os aspiradores não conseguem remover. A alça de ótima qualidade proporciona um manuseio confortável e prático. Com uma área útil de 16 cm x 5 cm, esta escova é perfeita para quem deseja manter o ambiente livre de pelos indesejados. Além disso, seu acabamento mate e a cor azul-turquesa conferem um toque moderno e elegante ao produto. Ideal para quem valoriza a limpeza e a estética do lar.', 54.9, 54.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rdya-mcwjsashf59041', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F22598785933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
