INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43111902243', 'Caixa Térmica Porta Latas e Garrafa 5 Litros com Alça Soprano Cooler Térmico Preto', 'Caixa Térmica Compacta 5L – Ideal para Praia, Viagens e Lanches A Caixa Térmica 5 Litros é a escolha perfeita para quem busca mobilidade, praticidade e conservação térmica em um único produto. Com tamanho compacto e excelente desempenho, ela é ideal para levar em viagens curtas, passeios à praia, acampamentos, trilhas ou até mesmo para usar como lancheira térmica ou balde de gelo. Seu isolamento em EPS (isopor) garante a conservação por até 8 horas, mantendo bebidas ou alimentos frescos durante toda a atividade. Além disso, é livre de BPA, sendo segura para o transporte de alimentos embalados. Destaques do Produto: ✅ Capacidade: 5 Litros ✅ Conserva por até 8 horas (com 20% da capacidade em gelo) ✅ Tampa com trava segura, que ajuda a manter o isolamento térmico ✅ Alça de mão retrátil – facilita o transporte no dia a dia ✅ Pode ser usada como lancheira térmica ou balde de gelo ✅ Produto BPA Free – seguro para armazenar alimentos e bebidas Capacidade Interna Estimada (sem gelo): 🥤 6 latas de 350 ml 🥤 6 latas de 473 ml Especificações Técnicas: 📏 Dimensões: 26,4 x 16,6 x 20,3 cm ⚖️ Peso: leve e fácil de carregar 🧊 Isolamento: Poliestireno Expandido (EPS) 🧪 Material: Polipropileno (PP) 📦 Garantia: 90 dias contra defeitos de fabricação', 65.9, 49.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-820l4-mq6ndovqs64g66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316557325%2F43111902243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
